async def _gate_disabled_reply(message: types.Message, gate: str) -> None:
    """v70 — Send the standardized 'gate disabled' reply. Used by EVERY gate command."""
    try:
        await message.reply(
            f"{wpe('cross')} {_to_bi(_gate_disabled_msg(gate))}"
        )
    except Exception:
        try:
            await message.reply(_gate_disabled_msg(gate))
        except Exception:
            pass


def _gate_off(gate: str) -> bool:
    """True if the gate is currently OFF (disabled). Convenience wrapper."""
    try:
        return not _gate_is_enabled(gate)
    except Exception:
        return False
