_freeproxy_pending: dict[int, list[dict]] = {}   # uid → parsed proxy dicts


# ══════════════════════════════════════════════════════════════════════════════
#  SITES LIST — source of truth = sites.json (same file shp.py uses on nodes)
#  sites.txt is kept as a flat URL dump for admin filter tools only.
# ══════════════════════════════════════════════════════════════════════════════

_sites_cache: list[str] | None = None
_sites_cache_mtime: float = 0.0
_sites_cache_src: str = ""


def _load_sites() -> list[str]:
    """Load Site URLs from sites.json (preferred) or fall back to sites.txt."""
    global _sites_cache, _sites_cache_mtime, _sites_cache_src

    src = SITES_JSON if os.path.isfile(SITES_JSON) else SITES_FILE
    try:
        mt = os.path.getmtime(src)
    except OSError:
        return []

    if (
        _sites_cache is not None
        and mt == _sites_cache_mtime
        and _sites_cache_src == src
    ):
        return _sites_cache

    urls: list[str] = []
    if src == SITES_JSON:
        try:
            with open(SITES_JSON, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, list):
                for entry in data:
                    site = (entry.get("Site") or "").strip().rstrip("/")
                    if site:
                        if not site.startswith("http"):
                            site = "https://" + site
                        urls.append(site)
            # Keep sites.txt in sync so admin /filter tools still work
            try:
                with open(SITES_FILE, "w", encoding="utf-8") as f:
                    f.write("\n".join(urls) + ("\n" if urls else ""))
            except OSError:
                pass
        except Exception as exc:
            log.error("Failed to load sites.json: %s — falling back to sites.txt", exc)
            src = SITES_FILE
            try:
                mt = os.path.getmtime(SITES_FILE)
            except OSError:
                return []
            with open(SITES_FILE, "r", encoding="utf-8") as f:
                urls = [l.strip().rstrip("/") for l in f if l.strip()]
    else:
        with open(SITES_FILE, "r", encoding="utf-8") as f:
            urls = [l.strip().rstrip("/") for l in f if l.strip()]

    # Dedupe while preserving order
    seen: set[str] = set()
    deduped: list[str] = []
    for u in urls:
        if u not in seen:
            seen.add(u)
            deduped.append(u)

    _sites_cache = deduped
    _sites_cache_mtime = mt
    _sites_cache_src = src
    log.info("Loaded %d sites from %s", len(deduped), os.path.basename(src))
    return _sites_cache


def get_random_site() -> str | None:
    sites = _load_sites()
    return random.choice(sites) if sites else None


# ══════════════════════════════════════════════════════════════════════════════
#  HIT SITES LOG  (auto-creates hit_sites.txt and appends one line per hit)
# ══════════════════════════════════════════════════════════════════════════════

# Only these 4 outcome categories are logged. Everything else
# (tax required, generic errors, timeouts, incorrect_number, expired, etc.)
# is silently ignored.
_HIT_LOG_LOCK = asyncio.Lock()


def _classify_hit_response(response: str, result: dict | None = None) -> str | None:
    """Map a checker response string into one of the four loggable hit labels.

    Returns one of: "Order Placed", "Insufficient Funds", "3DS Required",
    "Declined", or None if the response is not a loggable hit.
    """
    rl = (response or "").lower()
    if not rl:
        return None

    # Order Placed / Charged — check dict first (more reliable), then string patterns
    if _is_charged_response(response, result):
        return "Order Placed"
    if any(k in rl for k in (
        "order_placed", "order placed", "order completed",
        "processedreceipt", "payment successful", "payment_success",
        "charged", "approved", "succeeded",
    )):
        return "Order Placed"
    # Insufficient funds (CVV-matched live card)
    if any(k in rl for k in (
        "insufficient_funds", "insufficient funds", "insufficient fund",
        "insufficient_balance", "insufficient balance",
    )):
        return "Insufficient Funds"
    # 3DS / OTP required — broader matching
    if any(k in rl for k in (
        "otp_required", "otp required", "3ds", "3d secure", "3d-secure",
        "3dsecure", "three_d_secure", "three d secure",
        "requires_action", "challenge required", "authentication required",
    )):
        return "3DS Required"
    # Generic decline — broadest match
    if any(k in rl for k in (
        "card_declined", "card declined", "declined", "do_not_honor",
        "do not honor", "generic_decline", "transaction_declined",
        "transaction declined", "payment_declined", "payment declined",
        "rejected", "blocked", "fraudulent",
    )):
        return "Declined"
    return None


def _normalize_amount(price) -> str:
    """Coerce a Price field into a clean `$X.YY` USD string."""
    if price is None:
        return "-"
    s = str(price).strip()
    if not s or s in ("-", "—", "N/A"):
        return "-"
    # Already has $ prefix?
    if s.startswith("$"):
        return s
    # Find first numeric run anywhere in the string (handles "USD 99.99", "$5", etc.)
    m = re.search(r"([0-9]+(?:\.[0-9]+)?)", s)
    if m:
        return f"${m.group(1)}"
    return s


def _normalize_site(site: str | None) -> str:
    if not site:
        return "-"
    s = site.strip().rstrip("/")
    if not s:
        return "-"
    return s


async def _save_hit_site(site_url: str | None, amount, response_label: str) -> None:
    """Append a single line to hit_sites.txt (auto-creates the file).

    Line format:  <site_url> - $<amount> - <response_label>
    Safe to call from any async context; uses an asyncio.Lock to serialise writes.
    Logs the absolute path on first write so the operator can verify the location.
    """
    if not response_label:
        return
    line = (
        f"{_normalize_site(site_url)} - "
        f"{_normalize_amount(amount)} - "
        f"{response_label}"
    )
    try:
        async with _HIT_LOG_LOCK:
            await asyncio.to_thread(_append_hit_line, line)
    except Exception as exc:  # never break a check because of a log write
        log.error("hit_sites.txt append FAILED for line=%r path=%s err=%s",
                  line, os.path.abspath(HIT_SITES_FILE), exc, exc_info=True)


# Tracks whether we've already logged the absolute path of hit_sites.txt once.
_HIT_PATH_LOGGED: bool = False


def _append_hit_line(line: str) -> None:
    """Blocking append helper — called via asyncio.to_thread.

    Auto-creates the file if missing (open with 'a' does that for free).
    On the very first write, logs the absolute path so the operator can locate
    the file even if the bot's CWD differs from bot.py's directory.
    """
    global _HIT_PATH_LOGGED
    abs_path = os.path.abspath(HIT_SITES_FILE)
    if not _HIT_PATH_LOGGED:
        _HIT_PATH_LOGGED = True
        log.info("hit_sites.txt FIRST WRITE — absolute path: %s", abs_path)
    with open(HIT_SITES_FILE, "a", encoding="utf-8") as f:
        f.write(line + "\n")
    log.info("hit_sites.txt <- %s", line)


# ══════════════════════════════════════════════════════════════════════════════
#  CHECKED.TXT  —  auto-saves EVERY approved + insufficient card with
#  full details (username, card, response, price, timestamp).
#  Created in the same folder as bot.py.
# ══════════════════════════════════════════════════════════════════════════════

CHECKED_FILE = os.path.join(BASE_DIR, "checked.txt")
_CHECKED_LOCK = asyncio.Lock()
_checked_first_write = True


async def _save_to_checked_txt(
    *,
    card: str,
    status: str,
    response: str,
    price: str,
    user_id: int,
    user_name: str,
    user_uname: str,
    site: str = "Whop",
    elapsed: float = 0.0,
    card_brand: str = "-",
) -> None:
    """Append a card to checked.txt with full details.

    Format per line:
      [2026-08-25 04:30:00] STATUS | card | $price | brand | 8.48s | @username (Name) | site:Whop | response

    Called from ALL checkers (cmd_sh, cmd_whop, _whop_check_single, _whop_bulk_processor)
    whenever a card is APPROVED or INSUFFICIENT.
    """
    global _checked_first_write
    try:
        ts = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        # Build username display
        if user_uname:
            user_display = f"@{user_uname}"
        elif user_name:
            user_display = user_name
        else:
            user_display = str(user_id)

        # Truncate response to 150 chars to keep lines readable
        resp_short = (response or "-")[:150]

        line = (
            f"[{ts}] {status} | {card} | ${price} | {card_brand} | "
            f"{elapsed:.2f}s | {user_display} | site:{site} | {resp_short}"
        )

        async with _CHECKED_LOCK:
            if _checked_first_write:
                _checked_first_write = False
                abs_path = os.path.abspath(CHECKED_FILE)
                log.info("checked.txt FIRST WRITE — absolute path: %s", abs_path)
            with open(CHECKED_FILE, "a", encoding="utf-8") as f:
                f.write(line + "\n")
            log.info("checked.txt <- %s | %s", status, card.split("|")[0])
    except Exception as e:
        log.error("checked.txt append FAILED for card=%s err=%s",
                  card.split("|")[0], e, exc_info=True)


# ══════════════════════════════════════════════════════════════════════════════
#  UNIFIED PER-USER STATS TRACKER — v64.3
#
#  Replaces the broken update_whop_user_stats(user_id, category) which never
#  set "total_checked" and never tracked per-gate breakdowns.
#
#  _track_user_check() is called from EVERY gate (whop, mwhop, hitw, sh,
#  msh, st, mst, mmst, st1, mst1, b3, mb3) after every card check.
#  It atomically increments:
#    stats["total_checked"]               ← total cards across ALL gates
#    stats["approved"]                    ← total approved across ALL gates
#    stats["insufficient"]                ← total live CC across ALL gates
#    stats["declined"]                    ← total declined across ALL gates
#    stats["3ds"]                         ← total 3DS across ALL gates
#    stats["error"]                       ← total errors across ALL gates
#    stats["by_gate"][<gate>]["checked"]  ← per-gate breakdown
#    stats["by_gate"][<gate>]["approved"] ← per-gate approved
#
#  /rank reads this to show top 10 with all-gate totals + per-gate
#  breakdown in real time.
# ══════════════════════════════════════════════════════════════════════════════

_STATS_LOCK = asyncio.Lock()

# Map gate labels to their canonical names (used in by_gate stats)
_GATE_NAMES = {
    "Whop": "Whop",
    "Whop Hitter": "Whop",
    "Shopify": "Shopify",
    "Stripe ST": "Stripe ST",
    "Stripe 1$": "Stripe 1$",
    "Braintree": "Braintree",
    "Adyen": "Adyen",
}


def _normalize_gate(site: str) -> str:
    """Normalize the `site` parameter to a canonical gate name."""
    if not site:
        return "Other"
    s = str(site).strip()
    return _GATE_NAMES.get(s, s)


def _normalize_category(status: str) -> str:
    """Normalize the status to one of the canonical categories:
    approved, declined, insufficient, 3ds, error
    """
    if not status:
        return "error"
    s = str(status).upper().strip()
    if s in ("APPROVED", "CHARGED", "CARD_CHARGED", "CARD_APPROVED"):
        return "approved"
    if s in ("INSUFFICIENT", "INSUFFICIENT_FUNDS"):
        return "insufficient"
    if s in ("3DS", "3DS_AUTH", "AUTHENTICATION_REQUIRED"):
        return "3ds"
    if s in ("DECLINED", "CARD_DECLINED", "FRAUD", "INCORRECT",
             "EXPIRED", "GENERIC_DECLINE"):
        return "declined"
    if s in ("ERROR", "RETRYABLE", "UNKNOWN", "CLOUDFLARE_CHALLENGE"):
        return "error"
    # Default: declined (safest bucket for unknown statuses)
    return "declined" if s else "error"


async def _track_user_check(
    *,
    user_id: int,
    username: str = "",
    full_name: str = "",
    gate: str = "Other",
    status: str = "",
) -> None:
    """Atomically update per-user stats after every card check.

    Updates the whop_users.json file with:
      - total_checked (all gates combined)
      - approved / declined / insufficient / 3ds / error (all gates combined)
      - by_gate[<gate>]["checked"] and by_gate[<gate>]["approved"] (per-gate)

    Called from EVERY gate handler after each card result.
    NEVER raises — failures are silently absorbed (stats are best-effort).
    """
    try:
        uid_str = str(int(user_id))
    except (TypeError, ValueError):
        return
    cat = _normalize_category(status)
    gate_name = _normalize_gate(gate)
    try:
        async with _STATS_LOCK:
            data = _load_whop_users()
            user = data.get(uid_str, {})
            if not user:
                user = {
                    "username": username or "",
                    "full_name": full_name or "",
                    "added_at": int(time.time()),
                    "stats": {},
                }
            # Update username/full_name if provided (so /rank has fresh data)
            if username:
                user["username"] = username
            if full_name:
                user["full_name"] = full_name
            stats = user.get("stats", {})
            if not isinstance(stats, dict):
                stats = {}
            # Total counters (across ALL gates)
            stats["total_checked"] = int(stats.get("total_checked", 0)) + 1
            stats[cat] = int(stats.get(cat, 0)) + 1
            # Per-gate breakdown
            by_gate = stats.get("by_gate", {})
            if not isinstance(by_gate, dict):
                by_gate = {}
            gate_stats = by_gate.get(gate_name, {})
            if not isinstance(gate_stats, dict):
                gate_stats = {}
            gate_stats["checked"] = int(gate_stats.get("checked", 0)) + 1
            if cat == "approved":
                gate_stats["approved"] = int(gate_stats.get("approved", 0)) + 1
            by_gate[gate_name] = gate_stats
            stats["by_gate"] = by_gate
            user["stats"] = stats
            data[uid_str] = user
            _save_whop_users(data)
    except Exception as e:
        log.error("[_track_user_check] failed for user=%s gate=%s: %s",
                  user_id, gate_name, e, exc_info=True)


# Separate debug log: records EVERY /sh and /msh result, including ones
# that DON'T match the 4 loggable categories. Useful for finding missed
# response strings. Lives next to hit_sites.txt as hits_debug.txt.
HITS_DEBUG_FILE = os.path.join(BASE_DIR, "hits_debug.txt")
_HITS_DEBUG_LOCK = asyncio.Lock()


def _append_debug_line(line: str) -> None:
    """Append a line to hits_debug.txt (raw dump of every check)."""
    with open(HITS_DEBUG_FILE, "a", encoding="utf-8") as f:
        f.write(line + "\n")


async def _log_check_debug(source: str, cc_str: str, site: str | None,
                            result: dict | None, hit_label: str | None) -> None:
    """Always log the raw result of a check to hits_debug.txt.

    Format:  <timestamp> | <source> | cc=<bin6> | site=<url> | response=<raw> | price=<amt> | classified=<label|NONE>
    """
    try:
        bin6 = (cc_str.split("|")[0][:6]) if cc_str else "?"
        resp = (result or {}).get("Response", "?") if isinstance(result, dict) else "?"
        price = (result or {}).get("Price", "?") if isinstance(result, dict) else "?"
        ts = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        line = (
            f"{ts} | {source:11s} | cc={bin6} | "
            f"site={site or '-'} | "
            f"response={str(resp)[:120]!r} | "
            f"price={price} | "
            f"classified={hit_label or 'NONE'}"
        )
        async with _HITS_DEBUG_LOCK:
            await asyncio.to_thread(_append_debug_line, line)
    except Exception as exc:
        log.error("hits_debug.txt write failed: %s", exc, exc_info=True)


# ══════════════════════════════════════════════════════════════════════════════
#  FINAL RECONCILIATION PASS — guarantees every result in a bulk check is logged
# ══════════════════════════════════════════════════════════════════════════════

async def _finalize_bulk_hits(results: dict, order: list, source: str = "msh") -> int:
    """Run AFTER asyncio.gather completes. Iterates over EVERY result and logs it.

    This is the safety net: even if the in-flight logging inside _msh_check_single
    was swallowed by gather(return_exceptions=True), this sequential post-pass
    will still log every single card.

    Returns the number of NEW hit lines written to hit_sites.txt.
    """
    written = 0
    total = len(order)
    logged_count = 0
    skipped_count = 0

    log.info("[%s] FINAL PASS: checking %d results for hit logging", source, total)

    for cc_str in order:
        entry = results.get(cc_str)
        if entry is None:
            log.warning("[%s] FINAL PASS: cc=%s has NO result entry (check never completed?)",
                       source, cc_str.split('|')[0])
            skipped_count += 1
            continue

        result = entry.get("result") or {}
        site = entry.get("site")
        response = result.get("Response") or ""
        price = result.get("Price", "-")

        try:
            _hit_label = _classify_hit_response(response, result)
        except Exception as cls_exc:
            log.error("[%s] FINAL PASS: classifier crashed for cc=%s: %s",
                     source, cc_str.split('|')[0], cls_exc)
            _hit_label = None

        # ALWAYS write to debug log (so we have a record of every card)
        try:
            await _log_check_debug(f"{source}_final", cc_str, site, result, _hit_label)
        except Exception:
            pass

        # Write to hit_sites.txt only if classified
        if _hit_label:
            try:
                await _save_hit_site(site, price, _hit_label)
                written += 1
                log.info("[%s] FINAL PASS: LOGGED cc=%s -> %s", source, cc_str.split('|')[0], _hit_label)
            except Exception as save_exc:
                log.error("[%s] FINAL PASS: FAILED to save cc=%s: %s",
                         source, cc_str.split('|')[0], save_exc, exc_info=True)
        else:
            skipped_count += 1
            log.info("[%s] FINAL PASS: SKIPPED cc=%s response=%r (not a loggable hit)",
                    source, cc_str.split('|')[0], response[:80])

        logged_count += 1

    log.info("[%s] FINAL PASS COMPLETE: %d processed, %d written to hit_sites.txt, %d skipped",
             source, logged_count, written, skipped_count)
    return written


def _hit_sites_selftest() -> tuple[bool, str]:
    """Synchronous self-test used by startup banner and /hitstest.

    Writes a test line, reads it back, returns (ok, message).
    NEVER raises — catches all exceptions and returns (False, str(exc)).
    """
    try:
        abs_path = os.path.abspath(HIT_SITES_FILE)
        existed_before = os.path.isfile(abs_path)
        test_line = f"SELFTEST - $0.00 - Test write @ {datetime.datetime.now():%Y-%m-%d %H:%M:%S}"
        with open(HIT_SITES_FILE, "a", encoding="utf-8") as f:
            f.write(test_line + "\n")
        size_after = os.path.getsize(abs_path)
        return True, (
            f"abs_path={abs_path}\n"
            f"existed_before={existed_before}\n"
            f"size_after={size_after} bytes\n"
            f"test_line={test_line!r}"
        )
    except Exception as exc:
        return False, f"abs_path={os.path.abspath(HIT_SITES_FILE)}\nERROR: {exc!r}"



