@router.callback_query(F.data == "verify_join")
async def cb_verify_join(callback: types.CallbackQuery):
    # Always do a fresh API check — bypasses cache so users see instant result
    joined = await check_user_joined(callback.from_user.id, force=True)
    if not joined:
        await safe_callback_answer(callback, f"{bold('You have not joined yet! Join both channel and group first.')}",
            show_alert=True,
        )
        return

    # v64.4 — clear the negative cache entry so the next command doesn't
    # show "Access Restricted" because of a stale 30-second cache.
    _join_cache.pop(callback.from_user.id, None)

    await safe_callback_answer(callback, f"{bold('Verified! Welcome!')}")
    await safe_edit(callback.message, WELCOME_MSG, reply_markup=menu_keyboard())


