#  SHARED: format a single CC result line (compact, for /msh)
# ══════════════════════════════════════════════════════════════════════════════

def _is_charged_response(response: str, result: dict | None = None) -> bool:
    """Detect charged/ORDER_PLACED from shp.py response string or result dict."""
    rl = response.lower()
    if "order_placed" in rl or "order completed" in rl or "processedreceipt" in rl or "💎" in response:
        return True
    if result:
        if result.get("Charged") == "True" or result.get("Code") == "ORDER_PLACED":
            return True
    return False


def _to_mi(text: str) -> str:
    """Convert ASCII letters to Mathematical Italic Unicode (𝑀𝑒𝑟𝑐ℎ𝑎𝑛𝑡 style)."""
    out = []
    for ch in str(text):
        if 'A' <= ch <= 'Z':
            out.append(chr(0x1D434 + ord(ch) - ord('A')))
        elif 'a' <= ch <= 'z':
            out.append('\u210E' if ch == 'h' else chr(0x1D44E + ord(ch) - ord('a')))
        else:
            out.append(ch)
    return ''.join(out)


def _to_bi(text: str) -> str:
    """Convert ASCII letters/digits to Mathematical Bold Italic Unicode.

    Example:  "Serifs and italics? This is crazy!"
              -> "S e r i f s   a n d   i t a l i c s ?   T h i s   i s   c r a z y !"
              (each letter rendered in bold-italic math font)

    Used for ALL Whop-related messages per the operator's spec.
    """
    out = []
    for ch in str(text):
        o = ord(ch)
        if 0x41 <= o <= 0x5A:        # A-Z
            out.append(chr(0x1D468 + (o - 0x41)))
        elif 0x61 <= o <= 0x7A:      # a-z
            out.append(chr(0x1D482 + (o - 0x61)))
        elif 0x30 <= o <= 0x39:      # 0-9
            out.append(chr(0x1D7EC + (o - 0x30)))
        else:
            out.append(ch)
    return ''.join(out)


def _bi_wrap(label: str, value: str = "") -> str:
    """Helper: format 'Label: value' all in bold-italic math font."""
    if value == "":
        return _to_bi(label)
    return f"{_to_bi(label)} {_to_bi(value)}"


@router.message(Command("adduser"))
async def cmd_adduser(message: types.Message):
    """Add a user to the Whop bulk access list.

    Usage:
      /adduser @username   (reply to a user's message)
      /adduser <user_id>   (by numeric ID)
    """
    if not auth.is_owner(message.from_user.id):
        try:
            if not auth.is_admin(message.from_user.id):
                await message.reply(
                    f"{wpe('skull')} {_to_bi('Owner/Admin only command.')}"
                )
                return
        except Exception:
            await message.reply(
                f"{wpe('skull')} {_to_bi('Owner/Admin only command.')}"
            )
            return

    args = message.text.split(maxsplit=1)
    target_username = ""
    target_id = 0

    # Method 1: Reply to a message
    if message.reply_to_message:
        target_id = message.reply_to_message.from_user.id
        target_username = message.reply_to_message.from_user.username or ""
        target_name = message.reply_to_message.from_user.full_name or ""
    # Method 2: By @username or numeric ID
    elif len(args) >= 2:
        raw = args[1].strip().lstrip("@")
        if raw.isdigit():
            target_id = int(raw)
        else:
            target_username = raw
        target_name = ""
    else:
        await message.reply(
            f"{wpe('warn')} {_to_bi('Usage:')}\n"
            f"{wpe('arrow_right')} /adduser @username\n"
            f"{wpe('arrow_right')} /adduser <user_id>\n"
            f"{wpe('arrow_right')} {_to_bi('Or reply to a user message with /adduser')}"
        )
        return

    # If we only have a username (no ID), try to find the user
    if target_id == 0 and target_username:
        await message.reply(
            f"{wpe('warn')} {_to_bi('Cannot add by username alone — Telegram requires a user ID.')}\n\n"
            f"{wpe('arrow_right')} {_to_bi('Reply to the user message, then send /adduser')}\n"
            f"{wpe('arrow_right')} {_to_bi('Or use:')} /adduser <user_id>"
        )
        return

    if target_id == 0:
        await message.reply(f"{wpe('skull')} {_to_bi('Could not determine target user.')}")
        return

    # Add the user
    added = add_whop_user(target_id, target_username, target_name)
    if added:
        # Notify the admin
        uname_display = f"@{target_username}" if target_username else str(target_id)
        await message.reply(
            f"{wpe('check')} {_to_bi('User Added')}\n\n"
            f"{wpe('user')} {_to_bi('User:')} {_to_bi(uname_display)}\n"
            f"{wpe('triple_ring')} {_to_bi('ID:')} <code>{target_id}</code>\n"
            f"{wpe('approved')} {_to_bi('Access: Full (Whop bulk enabled)')}\n\n"
            f"{wpe('arrow_right')} {_to_bi('They can now use /mwhop and /msh')}"
        )
        # Notify the user
        try:
            notify_text = (
                f"{wpe('approved')} {_to_bi('GRANTED FULL ACCESS')} {wpe('approved')}\n\n"
                f"{wpe('whop_hitter')} {_to_bi('You have been granted full access to Whopex.')}\n\n"
                f"{wpe('rocket')} {_to_bi('You can now use:')}\n"
                f"{wpe('whop_hitter')} /mwhop — {_to_bi('Bulk Whop check (upload .txt or paste)')}\n"
                f"{wpe('rocket')} /msh — {_to_bi('Mass Whop check')}\n"
                f"{wpe('approved')} /sh — {_to_bi('Single Whop check')}\n"
                f"{wpe('whop_hitter')} /whop — {_to_bi('Free Whop check (1-50 cards)')}\n\n"
                f"{wpe('whop_hitter')} {_to_bi('Whopex')} — {_to_bi('Made by @tatsuyo_001')}"
            )
            await bot.send_message(target_id, notify_text)
        except Exception as e:
            log.warning("Could not notify added user %s: %s", target_id, e)
            await message.reply(
                f"{wpe('warn')} {_to_bi('User added but could not send DM (bot not started by user yet).')}"
            )
    else:
        uname_display = f"@{target_username}" if target_username else str(target_id)
        await message.reply(
            f"{wpe('warn')} {_to_bi('User already has access:')}\n"
            f"{wpe('user')} {_to_bi(uname_display)}"
        )


@router.message(Command("rmuser"))
async def cmd_rmuser(message: types.Message):
    """Remove a user from the Whop bulk access list."""
    try:
        if not auth.is_admin(message.from_user.id):
            await message.reply(
                f"{wpe('skull')} {_to_bi('Admin only command.')}"
            )
            return
    except Exception:
        await message.reply(
            f"{wpe('skull')} {_to_bi('Admin only command.')}"
        )
        return

    args = message.text.split(maxsplit=1)
    target_id = 0

    if message.reply_to_message:
        target_id = message.reply_to_message.from_user.id
    elif len(args) >= 2:
        raw = args[1].strip().lstrip("@")
        if raw.isdigit():
            target_id = int(raw)
        else:
            # Try to find by username in whop_users.json
            data = _load_whop_users()
            for uid, info in data.items():
                if info.get("username", "").lower() == raw.lower():
                    target_id = int(uid)
                    break
            if target_id == 0:
                await message.reply(
                    f"{wpe('skull')} {_to_bi('Cannot remove by username alone.')}\n"
                    f"{wpe('arrow_right')} {_to_bi('Use:')} /rmuser <user_id>\n"
                    f"{wpe('arrow_right')} {_to_bi('Or reply to their message with /rmuser')}\n"
                    f"{wpe('arrow_right')} {_to_bi('Or use:')} /rmuser @username {_to_bi('(if they were added by username)')}"
                )
                return
    else:
        await message.reply(
            f"{wpe('warn')} {_to_bi('Usage:')}\n"
            f"{wpe('arrow_right')} /rmuser @username\n"
            f"{wpe('arrow_right')} /rmuser <user_id>\n"
            f"{wpe('arrow_right')} {_to_bi('Or reply to a user message with /rmuser')}"
        )
        return

    if target_id == 0:
        await message.reply(f"{wpe('skull')} {_to_bi('Could not determine target user.')}")
        return

    removed = remove_whop_user(target_id)
    if removed:
        await message.reply(
            f"{wpe('check')} {_to_bi('User Removed')}\n\n"
            f"{wpe('user')} {_to_bi('ID:')} <code>{target_id}</code>\n"
            f"{wpe('skull')} {_to_bi('Access revoked — can no longer use /mwhop or /msh')}"
        )
    else:
        await message.reply(
            f"{wpe('warn')} {_to_bi('User not found in access list.')} "
            f"{_to_bi('ID:')} <code>{target_id}</code>"
        )


@router.message(Command("users"))
async def cmd_users(message: types.Message):
    """List all users with Whop bulk access + their stats."""
    try:
        if not auth.is_admin(message.from_user.id):
            await message.reply(
                f"{wpe('skull')} {_to_bi('Admin only command.')}"
            )
            return
    except Exception:
        await message.reply(
            f"{wpe('skull')} {_to_bi('Admin only command.')}"
        )
        return

    data = _load_whop_users()
    if not data:
        await message.reply(
            f"{wpe('warn')} {_to_bi('No users in the access list yet.')}\n\n"
            f"{wpe('arrow_right')} {_to_bi('Use /adduser to add a user.')}"
        )
        return

    lines = [
        f"{wpe('whop_hitter')} {_to_bi('Whopex Users')} {wpe('whop_hitter')}\n",
        f"{'=' * 35}",
        f"{_to_bi('Total users:')} {_to_bi(str(len(data)))}\n",
    ]

    for uid, info in data.items():
        username = info.get("username", "")
        full_name = info.get("full_name", "")
        added_at = info.get("added_at", 0)
        stats = info.get("stats", {})

        display = f"@{username}" if username else (full_name or uid)
        total = stats.get("total_checked", 0)
        approved = stats.get("approved", 0)
        insuff = stats.get("insufficient", 0)
        declined = stats.get("declined", 0)
        three_ds = stats.get("3ds", 0)

        lines.append(f"{wpe('user')} {_to_bi(display)}")
        lines.append(f"   {_to_bi('ID:')} <code>{uid}</code>")
        if total > 0:
            lines.append(
                f"   {_to_bi('Checked:')} {_to_bi(str(total))}"
                f" | {_to_bi('Approved:')} {_to_bi(str(approved))}"
                f" | {_to_bi('Insuff:')} {_to_bi(str(insuff))}"
                f" | {_to_bi('3DS:')} {_to_bi(str(three_ds))}"
                f" | {_to_bi('Declined:')} {_to_bi(str(declined))}"
            )
        lines.append("")

    lines.append(f"{'=' * 35}")
    lines.append(f"{wpe('whop_hitter')} {_to_bi('Whopex')} — {_to_bi('Made by @tatsuyo_001')}")

    text = "\n".join(lines)
    # If too long, send as file
    if len(text) > 3500:
        try:
            await message.reply_document(
                document=types.BufferedInputFile(
                    text.encode("utf-8"),
                    filename="whopex_users.txt",
                ),
                caption=f"{wpe('whop_hitter')} {_to_bi(f'{len(data)} users')}",
            )
            return
        except Exception:
            pass
    await message.reply(text)


# ══════════════════════════════════════════════════════════════════════════════
#  /info COMMAND — Show current user's info + stats
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("info"))
async def cmd_info(message: types.Message):
    """Show the current user's info: name, ID, username, total checked, approved, etc."""
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return
    if auth.is_banned(message.from_user.id):
        return

    user_id = message.from_user.id
    user_name = message.from_user.full_name or ""
    user_uname = message.from_user.username or ""

    # Load user stats from whop_users.json
    data = _load_whop_users()
    user_data = data.get(str(user_id), {})
    stats = user_data.get("stats", {})

    total = stats.get("total_checked", 0)
    approved = stats.get("approved", 0)
    insufficient = stats.get("insufficient", 0)
    declined = stats.get("declined", 0)
    three_ds = stats.get("3ds", 0)
    buyer_err = stats.get("buyer_error", 0)
    errors = stats.get("error", 0)
    by_gate = stats.get("by_gate", {}) or {}

    # Check access level
    is_admin_user = False
    try:
        is_admin_user = auth.is_admin(user_id)
    except Exception:
        pass
    is_owner = getattr(auth, "OWNER_ID", None) == user_id
    has_bulk_access = has_whop_bulk_access(user_id)

    if is_owner:
        access_level = "OWNER"
    elif is_admin_user:
        access_level = "ADMIN"
    elif has_bulk_access:
        access_level = "BULK USER"
    else:
        access_level = "FREE"

    # Check proxy count
    proxy_count = len(get_user_whop_proxies(user_id))

    # Build per-gate breakdown (only show gates with at least 1 check)
    gate_order = ["Whop", "Shopify", "Stripe ST", "Stripe 1$",
                  "Braintree", "Adyen", "Other"]
    gate_lines = []
    seen = set(by_gate.keys())
    ordered = [g for g in gate_order if g in seen]
    for g in by_gate.keys():
        if g not in ordered:
            ordered.append(g)
    for gate_name in ordered:
        gs = by_gate.get(gate_name, {})
        if not isinstance(gs, dict):
            continue
        g_checked = int(gs.get("checked", 0))
        g_approved = int(gs.get("approved", 0))
        if g_checked <= 0:
            continue
        gate_lines.append(
            f"{wpe('bolt')}   {gate_name}: {_to_bi(str(g_checked))} checked · "
            f"{_to_bi(str(g_approved))} approved"
        )

    sep = "=" * 35
    sep_thin = "─" * 35

    # Build the per-gate block (only if any gate has data)
    if gate_lines:
        gate_block = (
            f"{sep}\n"
            f"{wpe('triple_ring')} {_to_bi('Per-Gate Breakdown')}\n"
            f"{sep_thin}\n"
            + "\n".join(gate_lines) + "\n"
        )
    else:
        gate_block = ""

    text = (
        f"{wpe('whop_hitter')} {_to_bi('User Info')} {wpe('whop_hitter')}\n\n"
        f"{sep}\n"
        f"{wpe('user')} {_to_bi('Name:')} {_to_bi(user_name)}\n"
        f"{wpe('link')} {_to_bi('Username:')} {_to_bi(f'@{user_uname}' if user_uname else '-')}\n"
        f"{wpe('triple_ring')} {_to_bi('User ID:')} <code>{user_id}</code>\n"
        f"{wpe('star')} {_to_bi('Access:')} {_to_bi(access_level)}\n"
        f"{sep}\n\n"
        f"{wpe('whop_hitter')} {_to_bi('Check Stats (All Gates)')}\n"
        f"{sep}\n"
        f"{wpe('check')} {_to_bi('Total Checked:')} {_to_bi(str(total))}\n"
        f"{wpe('approved')} {_to_bi('Approved:')} {_to_bi(str(approved))}\n"
        f"{wpe('insufficient')} {_to_bi('Insufficient:')} {_to_bi(str(insufficient))}\n"
        f"{wpe('warn')} {_to_bi('3DS:')} {_to_bi(str(three_ds))}\n"
        f"{wpe('cross')} {_to_bi('Declined:')} {_to_bi(str(declined))}\n"
        f"{wpe('exclamation')} {_to_bi('Errors:')} {_to_bi(str(errors))}\n"
        f"{gate_block}"
        f"{sep}\n\n"
        f"{wpe('arrow_right')} {_to_bi('Proxies:')} {_to_bi(f'{proxy_count}/{MAX_PROXIES_PER_USER}')}\n"
        f"{wpe('arrow_right')} {_to_bi('Proxy:')} {_to_bi('REQUIRED (always)')}\n\n"
        f"{wpe('whop_hitter')} {_to_bi('Whopex')} — {_to_bi('Made by @tatsuyo_001')}"
    )
    await message.reply(text)


# ══════════════════════════════════════════════════════════════════════════════
#  /ownerid COMMAND — Debug: show your Telegram user ID + the bot's OWNER_ID
#  Used to diagnose "Access Restricted" issues when the owner can't use /b3.
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("ownerid"))
async def cmd_ownerid(message: types.Message):
    """Debug command — shows your Telegram user ID and the bot's configured OWNER_ID.

    This command NEVER checks join status — it always responds.  Use it to
    diagnose why /b3 says "Access Restricted" even when you're the owner:

      1. Run /ownerid
      2. Compare "Your Telegram ID" with "Bot OWNER_ID"
      3. If they DON'T match → your auth.py has the wrong OWNER_ID.
         Fix: edit auth.py and set OWNER_ID = <your real Telegram ID>
      4. If they DO match → the owner bypass should work.  If /b3 still
         says "Access Restricted", you haven't redeployed the latest bot.py.
    """
    user_id = message.from_user.id
    user_name = message.from_user.full_name or ""
    user_uname = message.from_user.username or ""

    # Get the bot's configured OWNER_ID
    bot_owner_id = getattr(auth, "OWNER_ID", None)
    bot_owner_id_str = str(bot_owner_id) if bot_owner_id is not None else "<not set>"

    # Check if the caller is the owner (using the same logic as /b3)
    is_owner = False
    try:
        if bot_owner_id is not None:
            try:
                if int(bot_owner_id) == user_id:
                    is_owner = True
            except (TypeError, ValueError):
                pass
        if not is_owner and hasattr(auth, "is_owner") and auth.is_owner(user_id):
            is_owner = True
    except Exception:
        pass

    # Check admin status
    is_admin = False
    try:
        if hasattr(auth, "is_admin") and auth.is_admin(user_id):
            is_admin = True
    except Exception:
        pass

    sep = "═" * 35
    sep_thin = "─" * 35
    match_emoji = "✅" if is_owner else "❌"
    match_text = "MATCH — owner bypass will work" if is_owner else "MISMATCH — owner bypass will NOT work"

    text = (
        f"{wpe('fire')} {_to_bi('Owner ID Debug')} {wpe('fire')}\n\n"
        f"{sep}\n"
        f"{wpe('user')} {_to_bi('Your Telegram ID:')} <code>{user_id}</code>\n"
        f"{wpe('user')} {_to_bi('Your Name:')} {_to_bi(user_name)}\n"
        f"{wpe('link')} {_to_bi('Your Username:')} {_to_bi(f'@{user_uname}' if user_uname else '-')}\n"
        f"{sep_thin}\n"
        f"{wpe('crown')} {_to_bi('Bot OWNER_ID:')} <code>{bot_owner_id_str}</code>\n"
        f"{wpe('check')} {_to_bi('Is Owner:')} {match_emoji} {_to_bi(match_text)}\n"
        f"{wpe('star')} {_to_bi('Is Admin:')} {_to_bi('Yes' if is_admin else 'No')}\n"
        f"{sep}\n\n"
    )
    if not is_owner:
        text += (
            f"{wpe('warn')} {_to_bi('FIX: Edit your auth.py and set:')}\n"
            f"<code>OWNER_ID = {user_id}</code>\n\n"
            f"{wpe('arrow_right')} {_to_bi('Then restart the bot.')}\n\n"
        )
    else:
        text += (
            f"{wpe('approved')} {_to_bi('Your ID matches OWNER_ID.')}\n"
            f"{_to_bi('The owner bypass in /b3 and /mb3 will work.')}\n"
            f"{_to_bi('If /b3 still says Access Restricted, you haven')}'"
            f"{_to_bi('t redeployed the latest bot.py — re-upload and restart.')}\n\n"
        )
    text += f"{wpe('sparkle')} {_to_bi('Whopex')} · {_to_bi('Made by @tatsuyo_001')}"
    await message.reply(text)



# ══════════════════════════════════════════════════════════════════════════════
#  /rank COMMAND — Show top 10 users by total checked
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("rank"))
async def cmd_rank(message: types.Message):
    """Show top 10 users — all-gate totals + per-gate breakdown.

    v64.3 — rewritten to:
      • Show both username AND TG name
      • Show "Checked" + "Approved" only (per the user's spec)
      • Aggregate across ALL gates (Whop, Shopify, Stripe ST, Stripe 1$, Braintree)
      • Display per-gate breakdown inline
      • Real-time — reads whop_users.json on every /rank call
    """
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return
    if auth.is_banned(message.from_user.id):
        return

    data = _load_whop_users()
    if not data:
        await message.reply(
            f"{wpe('warn')} {_to_bi('No users in the system yet.')}\n\n"
            f"{wpe('arrow_right')} {_to_bi('Start checking cards to appear on the leaderboard!')}"
        )
        return

    # Build list of dicts: {uid, username, full_name, total, approved, by_gate}
    users_list = []
    for uid, info in data.items():
        if not isinstance(info, dict):
            continue
        stats = info.get("stats", {})
        if not isinstance(stats, dict):
            continue
        total = int(stats.get("total_checked", 0))
        approved = int(stats.get("approved", 0))
        by_gate = stats.get("by_gate", {}) or {}
        if total <= 0:
            continue
        users_list.append({
            "uid": uid,
            "username": info.get("username", "") or "",
            "full_name": info.get("full_name", "") or "",
            "total": total,
            "approved": approved,
            "by_gate": by_gate,
        })

    # Sort by total checked (descending), tiebreak by approved (descending)
    users_list.sort(key=lambda u: (u["total"], u["approved"]), reverse=True)

    # Take top 10
    top_10 = users_list[:10]

    if not top_10:
        await message.reply(
            f"{wpe('warn')} {_to_bi('No users have checked cards yet.')}"
        )
        return

    # Aggregate totals across the top 10 (for the summary footer)
    grand_total = sum(u["total"] for u in top_10)
    grand_approved = sum(u["approved"] for u in top_10)

    # Aggregate per-gate totals across the top 10 (for the per-gate summary)
    gate_totals: dict[str, dict[str, int]] = {}
    for u in top_10:
        for gate_name, gs in (u["by_gate"] or {}).items():
            if not isinstance(gs, dict):
                continue
            gate_totals.setdefault(gate_name, {"checked": 0, "approved": 0})
            gate_totals[gate_name]["checked"] += int(gs.get("checked", 0))
            gate_totals[gate_name]["approved"] += int(gs.get("approved", 0))

    sep = "=" * 35
    sep_thin = "─" * 35

    lines = [
        f"{wpe('whop_hitter')} {_to_bi('Top 10 Users')} {wpe('whop_hitter')}",
        f"{_to_bi('All Gates · Real-time')}",
        f"{sep}\n",
    ]

    medals = [
        wpe('crown'), wpe('star'), wpe('star'),
        wpe('check'), wpe('check'), wpe('check'),
        wpe('check'), wpe('check'), wpe('check'), wpe('check'),
    ]

    # ── Per-user rows ────────────────────────────────────────────────
    for i, u in enumerate(top_10, 1):
        medal = medals[i - 1] if i <= 10 else wpe('check')
        # Display: TG name + @username (both, per the user's spec)
        uname = u["username"]
        fname = u["full_name"]
        if uname and fname:
            display = f"{fname} @{uname}"
        elif uname:
            display = f"@{uname}"
        elif fname:
            display = fname
        else:
            display = f"id:{u['uid']}"
        lines.append(
            f"{medal} {_to_bi(f'#{i}')} {_to_bi(display)}"
        )
        # Main row: Checked + Approved only
        lines.append(
            f"   {_to_bi('Checked:')} {_to_bi(str(u['total']))}"
            f"  ·  {_to_bi('Approved:')} {_to_bi(str(u['approved']))}"
        )
        # Per-gate breakdown line (only show gates with checked > 0)
        gate_parts = []
        # Stable gate ordering: Whop, Shopify, Stripe ST, Stripe 1$, Braintree, Adyen, Other
        gate_order = ["Whop", "Shopify", "Stripe ST", "Stripe 1$",
                      "Braintree", "Adyen", "Other"]
        seen_gates = set((u["by_gate"] or {}).keys())
        ordered_gates = [g for g in gate_order if g in seen_gates]
        # Append any gates not in the standard list
        for g in (u["by_gate"] or {}).keys():
            if g not in ordered_gates:
                ordered_gates.append(g)
        for gate_name in ordered_gates:
            gs = (u["by_gate"] or {}).get(gate_name, {})
            if not isinstance(gs, dict):
                continue
            g_checked = int(gs.get("checked", 0))
            g_approved = int(gs.get("approved", 0))
            if g_checked <= 0:
                continue
            gate_parts.append(f"{gate_name}:{g_checked}✓{g_approved}")
        if gate_parts:
            lines.append(f"   {_to_bi(' · '.join(gate_parts))}")
        lines.append("")

    # ── Summary section ──────────────────────────────────────────────
    lines.append(sep_thin)
    lines.append(
        f"{wpe('triple_ring')} {_to_bi('Top 10 totals:')}"
        f" {_to_bi(str(grand_total))} {_to_bi('checked')}"
        f" · {_to_bi(str(grand_approved))} {_to_bi('approved')}"
    )
    # Per-gate totals across the top 10
    if gate_totals:
        gate_summary_parts = []
        for gate_name in ["Whop", "Shopify", "Stripe ST", "Stripe 1$",
                          "Braintree", "Adyen", "Other"]:
            if gate_name not in gate_totals:
                continue
            gs = gate_totals[gate_name]
            if gs["checked"] <= 0:
                continue
            gate_summary_parts.append(
                f"{gate_name} {gs['checked']}/{gs['approved']}"
            )
        if gate_summary_parts:
            lines.append(
                f"{wpe('bolt')} {_to_bi('By gate:')} "
                + _to_bi(" · ".join(gate_summary_parts))
            )

    lines.append(sep)
    lines.append(f"{wpe('sparkle')} {_to_bi('Whopex')} · {_to_bi('Made by @tatsuyo_001')}")

    text = "\n".join(lines)
    await message.reply(text)


async def _send_charged_notification(
    user_id: int, username: str, full_name: str,
    amount: str, gate_type: str = "shopify",
    is_3d_bypassed: bool = False,
    status_label: str = "Order Placed",
    header_title: str = "ORDER PLACED",
) -> None:
    """Send a styled hit notification to the join_chat_id channel."""
    try:
        _is_order = header_title == "ORDER PLACED"

        # ── random custom emoji selection ──────────────────────────────
        _CE_HDR    = pe(random.choice(["5039670412733055750","5767209624675553166","5039816072253932764"])
                        if _is_order else
                        random.choice(["6235628846855492222","5215414165178425004","5375452661036358740"]))
        _CE_UNAME  = pe(random.choice(["5978915975808945445","5978784790327856236","5364105417569868801"]))
        _CE_NAME   = pe(random.choice(["5784914081165087232","6235252066554484059","5375295710046462188"]))
        _CE_STATUS = pe(random.choice(["5226656353744862682","5472250091332993630","5989800724312101453"])
                        if _is_order else
                        random.choice(["6235628846855492222","5215414165178425004","5375452661036358740"]))
        _CE_PRICE  = pe(random.choice(["6235459831302460476","5429651785352501917","5197369495739455200"]))
        _CE_GATE   = pe(random.choice(["5332455502917949981","5039600026809009149","5042111805288089118"]))

        uname_display = _to_mi(f"@{username}" if username else (full_name or "Unknown"))
        name_display  = _to_mi(full_name or "Unknown")
        gate_label    = _to_mi("Stripe Hitter" if gate_type == "stripe" else "Shopify")
        status_mi     = _to_mi(status_label)
        header_mi     = _to_mi(header_title)
        amount_mi     = _to_mi(str(amount))
        tds_line      = f"\n{_CE_GATE}  {_to_mi('3D Bypassed')}" if is_3d_bypassed else ""

        msg = (
            f"꒰ {_CE_HDR} ꒱  {header_mi}  ꒰ {_CE_HDR} ꒱\n"
            f"\n"
            f"{_CE_UNAME}  {uname_display}\n"
            f"{_CE_NAME}  {name_display}\n"
            f"\n"
            f"━━━━━━━━━━━━━━━━━━━━\n"
            f"\n"
            f"{_CE_STATUS}  {status_mi}\n"
            f"{_CE_PRICE}  ${amount_mi}\n"
            f"{_CE_GATE}  {gate_label}"
            f"{tds_line}"
        )

        await bot.send_message(join_chat_id, msg, parse_mode="HTML")
    except Exception:
        pass


def _format_status_line(response: str) -> str:
    """Return the status header line for a given checker response."""
    rl = response.lower()
    if _is_charged_response(response):
        return f"{pe(E['gem'])} {bold('Order Placed!')}"
    elif any(k in rl for k in ["insufficient_funds", "insufficient funds"]):
        return f"{pe(E['check2'])} {bold('Insufficient Funds')}"
    elif any(k in rl for k in ["incorrect_cvc", "invalid_cvc", "incorrect_cvv", "invalid_cvv"]):
        return f"{pe(E['check3'])} {bold('CCN Live')}"
    elif any(k in rl for k in ["incorrect_zip"]):
        return f"{pe(E['check'])} {bold('ZIP Error — Live')}"
    elif "otp_required" in rl or "3ds" in rl:
        return f"{pe(E['check'])} {bold('3DS / OTP — Live')}"
    elif any(k in rl for k in ["card_declined", "do_not_honor", "declined"]):
        return f"{pe(E['cross'])} {bold('Declined')}"
    elif "expired" in rl:
        return f"{pe(E['cross2'])} {bold('Expired')}"
    elif "risky" in rl:
        return f"{pe(E['warn'])} {bold('Risky')}"
    elif "incorrect_number" in rl:
        return f"{pe(E['cross3'])} {bold('Dead')}"
    else:
        return f"{pe(E['warn2'])} {bold(response[:50])}"


def _format_compact_result(cc_str: str, result: dict, bin_info: dict, site: str | None = None) -> str:
    """Format a compact result block for one CC (used by /msh)."""
    response = result.get("Response", "Unknown")
    gate = result.get("Gate", "-")
    price = result.get("Price", "-")
    status_line = _format_status_line(response)

    bin_line = (
        f"{bin_info['brand']} | {bin_info['type']} | {bin_info['level']} | "
        f"{bin_info['bank']} | {bin_info['flag']} {bin_info['country']}"
    )

    site_line = (
        f"{pe(E['globe'])} {bold('Site:')} {bold(site if site else '-')}\n"
        if site else ""
    )

    return (
        f"{status_line}\n"
        f"{pe(R['cc'])} {bold('CC:')} <tg-spoiler>{cc_str}</tg-spoiler>\n"
        f"{pe(R['gate'])} {bold('Gate:')} {bold(gate)}\n"
        f"{pe(R['price'])} {bold('Price:')} {bold(str(price))}\n"
        f"{site_line}"
        f"{pe(R['bin_info'])} {bold('BIN:')} {bold(bin_line)}"
    )


# ══════════════════════════════════════════════════════════════════════════════
#  /msh COMMAND — Mass CC Check (parallel batch)
# ══════════════════════════════════════════════════════════════════════════════

_MSH_EDIT_LOCKS: dict[int, asyncio.Lock] = {}   # msg_id -> Lock

# ── v33 STATUS CADENCE — simple 50-second time-based throttle ────────────────
# The OLD 40% rule (refresh every 40% of batch size) updated the status box
# every 40 cards on a 100-card batch — fine for short runs but on an 80,000-
# card bulk that meant ~320 status edits per batch cycle, which eventually
# tripped Telegram FloodWait.  The NEW rule is dead simple: refresh the
# status box at most once every 50 seconds, plus always on the very first
# update and on the FINAL update (when done >= total).  This caps the total
# edits to ~1 per minute regardless of bulk size — well within Telegram's
# edit rate limit.  The `_MASS_STATUS_LAST_EDIT` dict now stores the
# monotonic timestamp of the last edit (was a card-count integer).
_MASS_STATUS_LAST_EDIT: dict[int, float] = {}   # msg_id -> monotonic time of last edit
_MASS_STATUS_EDIT_INTERVAL = 50.0                # seconds between status box refreshes


def _mass_status_step(total: int) -> int:
    """40% of the effective batch size — kept for backward-compat (unused)."""
    return max(1, (min(total, _USER_SEM_LIMIT) * 40 + 99) // 100)


def _mass_edit_due(msg_id: int, done: int, total: int) -> bool:
    """True when the shared status box should refresh right now.

    v33 — time-based: refresh at most once every 50 seconds, plus always
    on the very first call (no last-edit recorded yet) and on the FINAL
    call (done >= total).  Updates the last-edit marker as a side effect,
    so call it ONLY right before an actual safe_edit.  Self-cleans at
    completion.
    """
    # FINAL update — always refresh and clean up the marker.
    if done >= total:
        _MASS_STATUS_LAST_EDIT.pop(msg_id, None)
        return True
    import time as _time
    now = _time.monotonic()
    last = _MASS_STATUS_LAST_EDIT.get(msg_id, 0.0)
    # First-ever edit for this msg_id (last == 0.0) OR 50s elapsed → due.
    if last == 0.0 or (now - last) >= _MASS_STATUS_EDIT_INTERVAL:
        _MASS_STATUS_LAST_EDIT[msg_id] = now
        return True
    return False


async def _msh_check_single(
    cc_str: str, proxy_data: dict, status_msg: types.Message,
    results: dict, order: list, user_name: str, user_uname: str = "", user_id: int = 0,
    sites_list: list | None = None,
):
    """Check a single CC and update the shared status message immediately.

    NOTE: Hit-logging here is best-effort. A FINAL reconciliation pass in
    cmd_msh() / cb_quick_msh() guarantees every result is logged even if
    this function raises before reaching the save call.
    """
    try:
        site = random.choice(sites_list) if sites_list else get_random_site()
        if not site:
            results[cc_str] = {"result": {"Response": "Card declined", "Gate": "-", "Price": "-", "Status": "Dead"}, "bin": {"brand":"-","type":"-","level":"-","bank":"-","country":"-","flag":"🏳️"}, "site": None}
        else:
            bin_num = cc_str.split("|")[0][:6]
            _bin = asyncio.create_task(bin_lookup(bin_num))
            sem = get_user_semaphore(user_id)
            async with sem:
                try:
                    result = await checker_bridge.check_card_site(cc_str, site, proxy_data)
                except Exception:
                    result = {"Response": "Card declined", "Price": "-", "Gate": "-", "Status": "Dead"}
            bin_info = await _bin

            results[cc_str] = {"result": result, "bin": bin_info, "site": site}

            # Save charged CC
            rl = (result.get("Response") or "").lower()
            if _is_charged_response(result.get("Response") or "", result):
                auth.save_charged_cc(cc_str, user_id, user_name, result.get("Gate", "-"), str(result.get("Price", "-")))

            # ── Best-effort in-flight logging (the final pass will catch misses) ─
            try:
                _hit_label = _classify_hit_response(result.get("Response") or "", result)
                log.info("[/msh] cc=%s site=%s price=%s response=%r -> hit_label=%r",
                         cc_str.split('|')[0], site, result.get("Price", "-"),
                         (result.get("Response") or "")[:80], _hit_label)
                await _log_check_debug("msh", cc_str, site, result, _hit_label)
                if _hit_label:
                    await _save_hit_site(site, result.get("Price", "-"), _hit_label)
            except Exception as _inflight_exc:
                log.warning("[/msh] in-flight logging failed for cc=%s: %s (will be caught by final pass)",
                           cc_str.split('|')[0], _inflight_exc)
    except Exception as _outer_exc:
        # Catastrophic failure — record a placeholder result so the final pass can still log it
        log.error("[/msh] _msh_check_single crashed for cc=%s: %s", cc_str.split('|')[0], _outer_exc, exc_info=True)
        results[cc_str] = {
            "result": {"Response": f"INTERNAL ERROR: {_outer_exc!r}"[:200], "Price": "-", "Gate": "-", "Status": "Error"},
            "bin": {"brand":"-","type":"-","level":"-","bank":"-","country":"-","flag":"🏳️"},
            "site": None,
        }

    # ── Update the shared message ─────────────────────────────────────────────
    msg_id = status_msg.message_id
    if msg_id not in _MSH_EDIT_LOCKS:
        _MSH_EDIT_LOCKS[msg_id] = asyncio.Lock()

    async with _MSH_EDIT_LOCKS[msg_id]:
        done_count = sum(1 for cc in order if cc in results)
        total = len(order)

        lines = [f"{pe(E['bolt'])} {bold('Mass Check')} [{bold(str(done_count))}/{bold(str(total))}]\n"]

        for cc in order:
            if cc in results:
                entry = results[cc]
                block = _format_compact_result(cc, entry["result"], entry["bin"], entry.get("site"))
                lines.append(block)
            else:
                lines.append(
                    f"{pe(E['loading'])} <tg-spoiler>{cc}</tg-spoiler> {bold('checking...')}"
                )

        lines.append(f"\n{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}")

        new_text = "\n\n".join(lines)
        if _mass_edit_due(msg_id, done_count, total):
            try:
                await safe_edit(status_msg, new_text)
            except Exception:
                pass

    # Clean up lock when all done
    if sum(1 for cc in order if cc in results) == len(order):
        _MSH_EDIT_LOCKS.pop(msg_id, None)


async def _whop_check_single(
    cc_str, status_msg, results, order,
    user_name, user_uname, user_id, sites_list,
    chat_id: int | None = None,
):
    """Check one CC via the Whop pool and update the shared status message.

    NOTE: Best-effort in-flight logging. A final pass in cmd_msh()
    guarantees every result is logged.
    """
    try:
        site_pair = random.choice(sites_list) if sites_list else None
        if not site_pair:
            results[cc_str] = {
                "result": {
                    "status": "DECLINED", "card": cc_str, "card_brand": "-",
                    "price": "-", "elapsed": 0.0,
                    "response": "Card declined",
                    "site": "", "biz_id": "",
                    "is_charged": False, "is_insufficient": False, "is_dead": True,
                },
                "site": None,
            }
        else:
            site_url, biz_id = site_pair
            bin_num = cc_str.split("|")[0][:6]
            _bin = asyncio.create_task(bin_lookup(bin_num))
            sem = get_user_semaphore(user_id)
            async with sem:
                try:
                    # v37 — pass chat_id so whop_check_card records/looks-up
                    # trusted real-response sites for this chat.
                    result = await whop_check_card(cc_str, site_url, biz_id,
                                                   user_id=user_id,
                                                   priority=True,
                                                   chat_id=chat_id)
                except Exception:
                    # Never surface an exception — show a normal decline.
                    result = {
                        "status": "DECLINED", "card": cc_str, "card_brand": "-",
                        "price": "-", "elapsed": 0.0,
                        "response": "Card declined",
                        "site": site_url, "biz_id": biz_id,
                        "is_charged": False, "is_insufficient": False, "is_dead": True,
                    }
            bin_info = await _bin
            results[cc_str] = {"result": result, "bin": bin_info, "site": site_url}

            # Save charged CC
            if result.get("is_charged"):
                try:
                    auth.save_charged_cc(cc_str, user_id, user_name, "Whop",
                                          str(result.get("price", "-")))
                except Exception:
                    pass

            # ── Send APPROVED hits to the user's personal chat IMMEDIATELY ────
            if result.get("is_charged"):
                try:
                    _price = str(result.get("price", "-"))
                    _elapsed = float(result.get("elapsed", 0.0) or 0.0)
                    _resp = str(result.get("response", ""))[:120]
                    _appr = (
                        f"{wpe('approved')} {_to_bi('APPROVED')} {wpe('approved')}\n\n"
                        f"{wpe('card')} {_to_bi('CC:')} <code>{cc_str}</code>\n"
                        f"{wpe('site')} {_to_bi('Site:')} {_to_bi('Whop')}\n"
                        f"{wpe('amount')} {_to_bi('Price:')} {_to_bi(f'${_price}')}\n"
                        f"{wpe('time')} {_to_bi('Time:')} {_to_bi(f'{_elapsed:.2f}s')}\n"
                        f"{wpe('gem')} {_to_bi('Response:')} {_to_bi(_resp)}\n\n"
                        f"{wpe('checked_by')} {_to_bi('Checked by:')} "
                        f"{user_link(user_id, user_name, user_uname)}\n"
                        f"{wpe('whop_hitter')} {_to_bi('Whopex')}"
                    )
                    asyncio.create_task(status_msg.bot.send_message(status_msg.chat.id, _appr))
                except Exception:
                    pass

            # Update user stats
            try:
                _cat = _classify_whop_result(result)
                update_whop_user_stats(user_id, _cat)
            except Exception:
                pass
            # v64.3 — unified per-gate stats for /rank
            try:
                await _track_user_check(
                    user_id=user_id, username=user_uname,
                    full_name=user_name, gate="Shopify",
                    status=_cat,
                )
            except Exception:
                pass

            # Best-effort logging
            try:
                _hit_label = (
                    "Approved" if result.get("is_charged")
                    else ("Insufficient" if result.get("is_insufficient")
                          else ("Declined" if result.get("is_dead") else None))
                )
                log.info("[/msh] cc=%s site=%s price=%s status=%r -> hit_label=%r",
                         cc_str.split("|")[0], site_url, result.get("price", "-"),
                         result.get("status"), _hit_label)
                await _log_check_debug("msh", cc_str, site_url, result, _hit_label)
                if _hit_label:
                    await _save_hit_site(site_url, result.get("price", "-"), _hit_label)
            except Exception as _inf:
                log.warning("[/msh] in-flight logging failed for cc=%s: %s",
                            cc_str.split("|")[0], _inf)
    except Exception as _o:
        log.error("[/msh] _whop_check_single crashed for cc=%s: %s",
                  cc_str.split("|")[0], _o, exc_info=True)
        results[cc_str] = {
            "result": {
                "status": "ERROR", "card": cc_str, "card_brand": "-",
                "price": "-", "elapsed": 0.0,
                "response": f"INTERNAL ERROR: {_o!r}"[:200],
                "site": "", "biz_id": "",
                "is_charged": False, "is_insufficient": False, "is_dead": True,
            },
            "bin": {"brand": "-", "type": "-", "level": "-",
                    "bank": "-", "country": "-", "flag": ""},
            "site": None,
        }

    # ── Update shared message ───────────────────────────────────────────
    # Build the new text inside the lock (fast), then call safe_edit
    # OUTSIDE the lock so a slow edit (FloodWait) doesn't block parallel workers.
    msg_id = status_msg.message_id
    if msg_id not in _MSH_EDIT_LOCKS:
        _MSH_EDIT_LOCKS[msg_id] = asyncio.Lock()
    async with _MSH_EDIT_LOCKS[msg_id]:
        done = sum(1 for cc in order if cc in results)
        total = len(order)
        lines = [
            f"{wpe('bolt_yellow')} {_to_bi('Whop Mass Check')} "
            f"[{_to_bi(str(done))}/{_to_bi(str(total))}]\n"
        ]
        for cc in order:
            if cc in results:
                r = results[cc]["result"]
                block = _format_whop_compact(cc, r, results[cc].get("bin", {}),
                                             results[cc].get("site"))
                lines.append(block)
            else:
                lines.append(
                    f"{wpe('arc_reactor')} <tg-spoiler>{cc}</tg-spoiler> "
                    f"{_to_bi('checking')}... {wpe('processing')}"
                )
        lines.append(
            f"\n{wpe('checked_by')} {_to_bi('Checked by:')} "
            f"{user_link(user_id, user_name, user_uname)}"
        )
        new_text = "\n\n".join(lines)
    # ── Lock released — safe_edit runs without blocking other workers ───
    if _mass_edit_due(msg_id, done, total):
        try:
            await safe_edit(status_msg, new_text)
        except Exception:
            pass
    if sum(1 for cc in order if cc in results) == len(order):
        _MSH_EDIT_LOCKS.pop(msg_id, None)


def _format_whop_compact(cc_str, result, bin_info, site):
    """Format a single Whop result block (used inside /msh status message)."""
    is_charged = result.get("is_charged", False)
    is_insufficient = result.get("is_insufficient", False)
    is_dead = result.get("is_dead", False)
    price = str(result.get("price", "-"))
    elapsed = float(result.get("elapsed", 0.0) or 0.0)
    status = str(result.get("status", "UNKNOWN"))
    resp_low = str(result.get("response", "")).lower()

    # v34 — explicit ERROR branch (status="ERROR" + is_dead=False is how
    # the v34 $amount rule surfaces a no-amount proxy error).  Without
    # this branch the else branch shows "ERROR" via `status[:50]`, but
    # the user wanted a clearer "ERROR" / "Proxy Error" label.
    # v35 — explicit 3DS branch: the Whop pool sets is_dead=True on 3DS
    # results (because the charge didn't go through), so the is_dead
    # check below used to swallow 3DS into DECLINED.  Check 3DS first.
    if is_charged:
        head = f"{wpe('approved')} {_to_bi('APPROVED')} {wpe('approved')}"
    elif is_insufficient:
        head = f"{wpe('insufficient')} {_to_bi('INSUFFICIENT')} {wpe('insufficient')}"
    elif status.upper() == "ERROR":
        head = f"{wpe('warn2')} {_to_bi('ERROR')} {wpe('warn2')}"
    elif (status.upper() == "3DS"
          or "3ds" in resp_low
          or "requires_action" in resp_low
          or "authentication" in resp_low
          or "otp" in resp_low):
        head = f"{wpe('warn')} {_to_bi('3DS')}"
    elif is_dead:
        head = f"{wpe('skull')} {_to_bi('DECLINED')}"
    else:
        head = f"{wpe('warn')} {_to_bi(status[:50])}"

    site_label = site if site else "-"
    bin_line = (
        f"{bin_info.get('brand', '-')} | {bin_info.get('type', '-')} | "
        f"{bin_info.get('bank', '-')} | "
        f"{bin_info.get('flag', '')} {bin_info.get('country', '-')}"
    )

    return (
        f"{head}\n"
        f"{wpe('card')} {_to_bi('CC:')} <code>{cc_str}</code>\n"
        f"{wpe('site')} {_to_bi('Site:')} {_to_bi('Whop')}\n"
        f"{wpe('amount')} {_to_bi('Price:')} {_to_bi(f'${price}')}\n"
        f"{wpe('time')} {_to_bi('Time:')} {_to_bi(f'{elapsed:.2f}s')}\n"
        f"{wpe('triple_ring')} {_to_bi('BIN:')} {_to_bi(bin_line)}"
    )


async def _finalize_whop_hits(results, order, source="msh"):
    """Final reconciliation pass for Whop bulk checks."""
    written = 0
    for cc in order:
        if cc not in results:
            continue
        r = results[cc]["result"]
        try:
            _hit_label = (
                "Approved" if r.get("is_charged")
                else ("Insufficient" if r.get("is_insufficient")
                      else ("Declined" if r.get("is_dead") else None))
            )
            if _hit_label:
                await _save_hit_site(
                    r.get("site", "") or "-", r.get("price", "-"), _hit_label
                )
                written += 1
            await _log_check_debug(source, cc, r.get("site", "") or "-", r, _hit_label)
        except Exception as _e:
            log.warning("[/whop-%s] final pass failed for cc=%s: %s",
                        source, cc.split("|")[0], _e)
    return written


# ══════════════════════════════════════════════════════════════════════════════
#  /whop COMMAND — Free for everyone, 1-50 cards (sequential)
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("whop"))
async def cmd_whop(message: types.Message):
    """Free Whop check for everyone. Accepts 1-50 cards (auto-cuts if more).

    Each card is checked sequentially. Each result is sent as a NEW message
    (no edit dependency). This guarantees the user ALWAYS sees every result,
    even when Telegram FloodWait blocks message edits.
    """
    # v70 — gate on/off check (dashboard toggle)
    if _gate_off("whop"):
        await _gate_disabled_reply(message, "whop")
        return
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return
    user_id = message.from_user.id
    if auth.is_banned(user_id):
        return

    # ── Antispam cooldown ───────────────────────────────────────────────
    remaining = whop_check_cooldown(user_id)
    if remaining > 0:
        await message.reply(
            f"{wpe('warn')} {_to_bi('Slow down!')} "
            f"{_to_bi(f'Please wait {remaining:.0f}s before next check.')}"
        )
        return

    # ── Extract CCs from args + reply ──────────────────────────────────
    raw_text = ""
    args = message.text.split(maxsplit=1)
    if len(args) >= 2:
        raw_text = args[1]
    if message.reply_to_message:
        reply_text = message.reply_to_message.text or message.reply_to_message.caption or ""
        raw_text = raw_text + "\n" + reply_text if raw_text else reply_text

    if not raw_text.strip():
        await message.reply(
            f"{wpe('warn')} {_to_bi('No CCs found!')}\n\n"
            f"{wpe('arrow_right')} {_to_bi('Usage:')}\n"
            f"/whop cc|mm|yy|cvv\n"
            f"cc|mm|yy|cvv  (up to 50 cards)"
        )
        return

    from helpers import CC_PATTERN
    all_ccs = _DedupeList()
    for m in CC_PATTERN.finditer(raw_text):
        cc = f"{m.group(1)}|{m.group(2)}|{m.group(3)}|{m.group(4)}"
        if cc not in all_ccs:
            all_ccs.append(cc)
    if not all_ccs:
        for line in raw_text.strip().splitlines():
            line = line.strip()
            parts = re.split(r'[|/]', line)
            if len(parts) >= 4:
                cc = "|".join(p.strip() for p in parts[:4])
                if cc not in all_ccs:
                    all_ccs.append(cc)
    if not all_ccs:
        await message.reply(
            f"{wpe('skull')} {_to_bi('No valid CCs found!')}"
        )
        return

    # ── Auto-save to all_cards.txt (every paste/reply counts) ──────────
    await _append_to_all_cards(
        ccs=list(all_ccs),
        user_id=user_id,
        user_name=message.from_user.full_name or "",
        user_uname=message.from_user.username or "",
        source="whop",
    )

    # ── Auto-cut at WHOP_USER_MAX_CARDS (50) ────────────────────────────
    original_count = len(all_ccs)
    if original_count > WHOP_USER_MAX_CARDS:
        cut_amount = original_count - WHOP_USER_MAX_CARDS
        all_ccs = all_ccs[:WHOP_USER_MAX_CARDS]
        await message.reply(
            f"{wpe('warn')} {_to_bi('Auto-Cut')}\n\n"
            f"{wpe('triple_ring')} {_to_bi('Original:')} {_to_bi(str(original_count))} {_to_bi('cards')}\n"
            f"{wpe('skull')} {_to_bi('Cut:')} {_to_bi(str(cut_amount))} {_to_bi('cards')}\n"
            f"{wpe('check')} {_to_bi('Checking:')} {_to_bi(str(len(all_ccs)))} {_to_bi('cards (one by one)')}\n\n"
            f"{wpe('star')} {_to_bi(f'Max {WHOP_USER_MAX_CARDS} cards per /whop.')}\n"
            f"{wpe('arrow_right')} {_to_bi('For unlimited, contact admin: @tatsuyo_001')}"
        )

    # ── Load Whop sites (waits politely — never shows an error) ────────
    sites_list = _load_whop_sites()
    if not sites_list:
        _wait_msg = await message.reply(
            f"{wpe('arc_reactor')} {_to_bi('Preparing Whop sites...')} {wpe('processing')}"
        )
        _waited = 0.0
        while not sites_list and _waited < 120.0:
            await asyncio.sleep(2.0)
            _waited += 2.0
            sites_list = _load_whop_sites()
        if not sites_list:
            try:
                await safe_edit(
                    _wait_msg,
                    f"{wpe('hourglass')} {_to_bi('Sites are still being prepared.')}",
                    )
            except Exception:
                pass
            return
        try:
            await safe_edit(
                _wait_msg,
                f"{wpe('check')} {_to_bi('Sites ready — starting check.')}",
                )
        except Exception:
            pass




    # ── Set antispam cooldown ──────────────────────────────────────────
    whop_set_cooldown(user_id)

    user_name = message.from_user.full_name or ""
    user_uname = message.from_user.username or ""
    total = len(all_ccs)

    # ── Send ONE short initial status message (edited to "Done" at end) ─
    init_msg = await message.reply(
        f"{wpe('bolt_yellow')} {_to_bi('Whop Check')} "
        f"[{_to_bi('0')}/{_to_bi(str(total))}]\n"
        f"{wpe('arc_reactor')} {_to_bi('Checking cards sequentially...')} {wpe('processing')}"
    )

    results: dict = {}
    order = list(all_ccs)

    # ── Process each card SEQUENTIALLY ──────────────────────────────────
    for i, cc in enumerate(all_ccs, 1):
        site_pair = random.choice(sites_list)
        site_url, biz_id = site_pair
        bin_num = cc.split("|")[0][:6]

        # Run Whop check + BIN lookup in parallel
        _bin_task = asyncio.create_task(bin_lookup(bin_num))
        try:
            # v67 — /whop now runs on the DEDICATED SINGLE LANE
            # (single_whop.py + single_api.txt) — fully isolated from the
            # /mwhop bulk lane (whop.py + apis.txt).  Same retry law:
            # flagged answers get 3 retries on 3 different sites / APIs /
            # proxies (fresh SID) + new mail on a different domain, and a
            # real API response is always hunted before anything shows.
            result = await single_whop_check_card(cc, site_url, biz_id,
                                                  user_id=user_id,
                                                  priority=True,
                                                  chat_id=message.chat.id)
        except Exception:
            # Absolute last resort — the pool itself never raises.  A
            # normal-looking declined result is shown, NEVER an error.
            result = {
                "status": "DECLINED", "card": cc, "card_brand": "-",
                "price": "-", "elapsed": 0.0,
                "response": "Card declined",
                "site": site_url, "biz_id": biz_id,
                "is_charged": False, "is_insufficient": False, "is_dead": True,
            }
        try:
            bin_info = await _bin_task
        except Exception:
            bin_info = {"brand": "-", "type": "-", "level": "-",
                        "bank": "-", "country": "-", "flag": ""}

        results[cc] = {"result": result, "bin": bin_info, "site": site_url}

        # Save charged CC
        if result.get("is_charged"):
            try:
                auth.save_charged_cc(cc, user_id, user_name, "Whop",
                                      str(result.get("price", "-")))
            except Exception:
                pass

        # v64.3 — unified per-gate stats for /rank (Whop /whop)
        try:
            await _track_user_check(
                user_id=user_id, username=user_uname,
                full_name=user_name, gate="Whop",
                status=str(result.get("status", "")),
            )
        except Exception:
            pass

        # Best-effort hit logging
        try:
            _hit_label = (
                "Approved" if result.get("is_charged")
                else ("Insufficient" if result.get("is_insufficient")
                      else ("Declined" if result.get("is_dead") else None))
            )
            log.info("[/whop] cc=%s site=%s price=%s status=%r -> hit_label=%r",
                     cc.split("|")[0], site_url, result.get("price", "-"),
                     result.get("status"), _hit_label)
            await _log_check_debug("whop", cc, site_url, result, _hit_label)
            if _hit_label:
                await _save_hit_site(site_url, result.get("price", "-"), _hit_label)
        except Exception as _e:
            log.warning("[/whop] hit logging failed for cc=%s: %s",
                        cc.split("|")[0], _e)

        # ── Build result message for THIS card ───────────────────────────
        result_text = _format_whop_single_card(
            cc, result, bin_info, site_url,
            user_id, user_name, user_uname, i, total,
        )

        # ── Send result as a NEW message (no edit dependency) ────────────
        # Try 2 times to send the result; if all fail, log and continue.
        for send_attempt in range(2):
            try:
                await message.reply(result_text)
                break
            except TelegramRetryAfter as e:
                wait = min(e.retry_after + 1, 30)
                log.warning("FloodWait %ss on /whop result send (attempt %s) - sleeping",
                            wait, send_attempt + 1)
                await asyncio.sleep(wait)
            except Exception as e:
                log.error("/whop result send failed (attempt %s): %s",
                          send_attempt + 1, e)
                await asyncio.sleep(1)

        # ── Forward APPROVED + INSUFFICIENT to the public channel ──────
        _is_charged = result.get("is_charged", False)
        _is_insufficient = result.get("is_insufficient", False)
        _is_3ds = str(result.get("status", "")) == "3DS"
        if _is_charged or (_is_insufficient and _insufficient_forward_enabled):
            asyncio.create_task(_send_whop_hit_channel(
                is_approved=_is_charged,
                is_insufficient=_is_insufficient,
                price=str(result.get("price", "-")),
                elapsed=float(result.get("elapsed", 0.0) or 0.0),
                user_id=user_id,
                user_name=user_name,
                user_uname=user_uname,
            ))

        # ── Auto-forward APPROVED to charged group ─────────────────────
        if _is_charged:
            await _forward_charged_group(
                card=cc, price=str(result.get("price", "-")),
                gate="Whop", response=str(result.get("response", "-")),
                user_id=user_id, user_name=user_name, user_uname=user_uname,
                bin_info=bin_info,
                elapsed=float(result.get("elapsed", 0.0) or 0.0))

        # ── Save to checked.txt (approved + insufficient + 3ds) ──────────
        if _is_charged or _is_insufficient or _is_3ds:
            await _save_to_checked_txt(
                card=cc,
                status="APPROVED" if _is_charged else ("INSUFFICIENT" if _is_insufficient else "3DS"),
                response=str(result.get("response", "-")),
                price=str(result.get("price", "-")),
                user_id=user_id,
                user_name=user_name,
                user_uname=user_uname,
                site="Whop",
                elapsed=float(result.get("elapsed", 0.0) or 0.0),
                card_brand=str(result.get("card_brand", "-")),
            )

        # ── Update the initial message progress every 10 cards ───────────
        # Count-based (not time-based) — matches the bulk checker and keeps
        # edit volume far below Telegram's FloodWait threshold.
        if i % 10 == 0 or i == total:
            asyncio.create_task(safe_edit(
                init_msg,
                f"{wpe('bolt_yellow')} {_to_bi('Whop Check')} "
                f"[{_to_bi(str(i))}/{_to_bi(str(total))}]\n"
                f"{wpe('arc_reactor')} {_to_bi(f'Checked {i}/{total}...')}"
            ))

        # Small breathing room between cards
        await asyncio.sleep(0.2)

    # ── Final: edit initial message to "Done" (1 edit only) ─────────────
    await safe_edit(
        init_msg,
        f"{wpe('check')} {_to_bi('Whop Check Complete')} "
        f"[{_to_bi(str(total))}/{_to_bi(str(total))}]\n"
        f"{wpe('checked_by')} {_to_bi('Checked by:')} "
        f"{user_link(user_id, user_name, user_uname)}\n"
        f"{wpe('whop_hitter')} {_to_bi('Whopex')}"
    )

    # ── Final reconciliation pass ──────────────────────────────────────
    try:
        await _finalize_whop_hits(results, order, source="whop")
    except Exception as _fp:
        log.error("[/whop] final pass crashed: %s", _fp, exc_info=True)


def _format_whop_single_card(cc_str, result, bin_info, site_url,
                              user_id, user_name, user_uname, idx, total):
    """Format a complete result message for a single card (used by /whop)."""
    is_charged = result.get("is_charged", False)
    is_insufficient = result.get("is_insufficient", False)
    is_dead = result.get("is_dead", False)
    price = str(result.get("price", "-"))
    elapsed = float(result.get("elapsed", 0.0) or 0.0)
    status = str(result.get("status", "UNKNOWN"))
    resp_msg = str(result.get("response", ""))
    resp_low = resp_msg.lower()
    card_brand = str(result.get("card_brand", "-"))

    # v34 — explicit ERROR branch so the v34 $amount rule surfaces as a
    # clean "ERROR" header instead of "DECLINED" (no-amount case).
    # v35 — explicit 3DS branch: the Whop pool sets is_dead=True on 3DS
    # results, so the is_dead check used to swallow 3DS into DECLINED.
    # Check 3DS first so /whop shows "3DS" instead of "DECLINED".
    if is_charged:
        status_line = (
            f"{wpe('approved')} {_to_bi('APPROVED')} {wpe('approved')}"
        )
    elif is_insufficient:
        status_line = (
            f"{wpe('insufficient')} {_to_bi('INSUFFICIENT')} {wpe('insufficient')}"
        )
    elif status.upper() == "ERROR":
        status_line = f"{wpe('warn2')} {_to_bi('ERROR')} {wpe('warn2')}"
    elif (status.upper() == "3DS"
          or "3ds" in resp_low
          or "requires_action" in resp_low
          or "authentication" in resp_low
          or "otp" in resp_low):
        status_line = f"{wpe('warn')} {_to_bi('3DS')}"
    elif is_dead:
        status_line = f"{wpe('skull')} {_to_bi('DECLINED')}"
    else:
        status_line = f"{wpe('warn')} {_to_bi(status[:60])}"

    resp_disp = resp_msg[:120] if resp_msg else "-"
    site_disp = site_url if site_url else "-"

    return (
        f"{status_line}\n\n"
        f"{wpe('card')} {_to_bi('CC:')} <code>{cc_str}</code>\n"
        f"{wpe('site')} {_to_bi('Site:')} {_to_bi('Whop')}\n"
        f"{wpe('amount')} {_to_bi('Price:')} {_to_bi(f'${price}')}\n"
        f"{wpe('time')} {_to_bi('Time:')} {_to_bi(f'{elapsed:.2f}s')}\n"
        f"{wpe('gem')} {_to_bi('Response:')} {_to_bi(resp_disp)}\n\n"
        f"{wpe('triple_ring')} {_to_bi('BIN Info:')}\n"
        f"{brand_emoji(bin_info.get('brand', '-'))}{_to_bi('Brand:')} {_to_bi(bin_info.get('brand', '-'))}\n"
        f"{wpe('arrow_right')} {_to_bi('Type:')} {_to_bi(bin_info.get('type', '-'))}\n"
        f"{wpe('arrow_right')} {_to_bi('Bank:')} {_to_bi(bin_info.get('bank', '-'))}\n"
        f"{wpe('arrow_right')} {_to_bi('Country:')} {bin_info.get('flag', '')} {_to_bi(bin_info.get('country', '-'))}\n\n"
        f"{wpe('checked_by')} {_to_bi('Checked by:')} {user_link(user_id, user_name, user_uname)}\n"
        f"{_to_bi('gate')} : {wpe('whop_hitter')} {_to_bi('Whop')}\n"
        f"{wpe('whop_hitter')} {_to_bi('Whopex')}"
    )


# ══════════════════════════════════════════════════════════════════════════════
#  /hitw COMMAND — WHOP HITTER (auto full-payment hit on ANY Whop URL)
# ══════════════════════════════════════════════════════════════════════════════
#  /hitw <affiliate-or-checkout-url> [personal@mail.com] cc|mm|yy|cvv ... (1-50)
#
#  * ANY Whop URL works (affiliate https://whop.com/x?a=ref or plain
#    checkout https://whop.com/x) — the deployed Whop Hitter API
#    (hitterapis.txt) auto-extracts biz_id + plan and runs the whole
#    payment by itself.
#  * Personal mail is used when given; otherwise a brand-new faker Gmail
#    (same 5 formats as /whop and /mwhop) is generated per card.
#  * 1 card  → NO processing box: the exact response is shown in chat.
#  * 2-50    → live processing box; the run STOPS IMMEDIATELY on the first
#    APPROVED and the remaining unchecked cards are sent as text.
#  * PROXY LAW: the hitter NEVER sends a request without a proxy — no
#    proxy / dead proxies → a clear PROXY ERROR, never a direct request.
#  * Every APPROVED card lands in the charged group + log group exactly
#    like /whop and /mwhop do (owner cards stay private — v17 guard).
# ══════════════════════════════════════════════════════════════════════════════

_HITW_MAX_CARDS = 50
_HITW_CONCURRENCY = 10          # parallel hitter requests per user's run
_HITW_ACTIVE: set[int] = set()

_HITW_URL_RE = re.compile(
    r"https?://[^\s<>\"']+|(?:www\.)?whop\.com/[^\s<>\"']+",
    re.IGNORECASE,
)
_HITW_MAIL_RE = re.compile(r"[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}")

_HITW_EMPTY_BIN = {"brand": "-", "type": "-", "level": "-",
                   "bank": "-", "country": "-", "flag": ""}

_HITW_USAGE = (
    f"{wpe('whop_hitter')} {_to_bi('Whop Hitter — Usage')} {wpe('whop_hitter')}\n\n"
    f"{wpe('bolt_yellow')} /hitw &lt;url&gt; [mail] cc|mm|yy|cvv\n\n"
    f"{wpe('arrow_right')} &lt;url&gt; — {_to_bi('ANY whop link: affiliate or checkout')}\n"
    f"{wpe('arrow_right')} [mail] — {_to_bi('optional personal mail (auto-Gmail if skipped)')}\n"
    f"{wpe('arrow_right')} {_to_bi('1-50 cards (1 card = direct answer, no box)')}\n\n"
    f"{wpe('star')} {_to_bi('Example:')}\n"
    f"<code>/hitw https://whop.com/toolsuite?a=radiy772 4342562513557668|04|2029|765\n"
    f"/hitw https://whop.com/toolsuite my@mail.com 4342562513557668|04|2029|765\n"
    f"/hitw https://whop.com/toolsuite 4242424242424242|12|29|123 4342562513557668|04|2029|765</code>\n\n"
    f"{wpe('red_warn')} {_to_bi('Proxy REQUIRED — the hitter never runs without one.')}\n"
    f"{wpe('fire')} {_to_bi('Stops instantly on the first APPROVED — remaining cards sent as text.')}\n\n"
    f"{wpe('whop_hitter')} {_to_bi('Whopex')}"
)


def _hitw_proxy_error_text(detail: str) -> str:
    """The PROXY ERROR message — shown instead of EVER going direct."""
    detail = _html.escape(str(detail or "Proxy connect failed")[:220])
    return (
        f"{wpe('red_warn')} {_to_bi('PROXY ERROR')} {wpe('red_warn')}\n\n"
        f"{wpe('skull')} {detail}\n\n"
        f"{wpe('arrow_right')} {_to_bi('The Hitter NEVER sends a request without a working proxy.')}\n"
        f"{wpe('arrow_right')} {_to_bi('Fix or re-add your proxies with /addproxy and try again.')}\n\n"
        f"{wpe('whop_hitter')} {_to_bi('Whopex')}"
    )


def _hitw_parse(message_text: str, reply_text: str):
    """Parse /hitw input → (checkout_url, personal_mail, cards, error).

    Recognition order: the FIRST URL is the checkout/affiliate target; the
    FIRST e-mail OUTSIDE that URL (if any) is the optional personal mail;
    everything left is mined for cards (CC_PATTERN — same as /whop).
    """
    raw = message_text or ""
    if reply_text and reply_text.strip():
        raw = raw + "\n" + reply_text if raw.strip() else reply_text
    if not raw.strip():
        return None, None, [], "usage"
    m = _HITW_URL_RE.search(raw)
    if not m:
        return None, None, [], "usage"
    checkout_url = m.group(0).rstrip("),.;]")
    if not checkout_url.lower().startswith(("http://", "https://")):
        checkout_url = "https://" + checkout_url      # bare whop.com/... link
    rest = raw[:m.start()] + " " + raw[m.end():]

    personal_mail = None
    mm = _HITW_MAIL_RE.search(rest)
    if mm:
        personal_mail = mm.group(0).strip(".").lower()
        rest = rest[:mm.start()] + " " + rest[mm.end():]

    from helpers import CC_PATTERN
    cards = _DedupeList()
    for cm in CC_PATTERN.finditer(rest):
        cc = f"{cm.group(1)}|{cm.group(2)}|{cm.group(3)}|{cm.group(4)}"
        if cc not in cards:
            cards.append(cc)
    if not cards:
        for line in rest.strip().splitlines():
            line = line.strip()
            parts = re.split(r"[|/]", line)
            if len(parts) >= 4:
                cc = "|".join(p.strip() for p in parts[:4])
                if cc and cc not in cards:
                    cards.append(cc)
    if not cards:
        return checkout_url, personal_mail, [], "usage"
    return checkout_url, personal_mail, list(cards), None


def _hitw_price_disp(price) -> str:
    p = str(price or "-").strip()
    if p in ("", "-", "?", "None"):
        return "-"
    return p if p.startswith("$") else f"${p}"


