@router.callback_query(F.data.startswith("whop_bulk_stop:"))
async def cb_whop_bulk_stop(callback: types.CallbackQuery):
    """Stop an active Whop bulk check — INSTANT stop (v37).

    Sets the stop flag, removes the STOP button from the message, and
    shows a confirmation.  The bulk processor's worker loop AND the
    per-card retry loop (whop_bulk_check_card) both check this flag
    and bail out within milliseconds — was: up to ~75 min worst-case
    before v37 because the per-card retry valve could loop 100 times
    × 45s timeout before noticing STOP.
    """
    stop_key = callback.data.split(":", 1)[1] if ":" in callback.data else ""
    if not stop_key:
        await safe_callback_answer(callback)
        return
    # v37 — owner/admin check (matches every other stop handler):
    # only the user who started the bulk (or an admin) can stop it.
    try:
        clicker_id = callback.from_user.id
        owner_id = int(stop_key.split(":")[-1])
    except (ValueError, IndexError):
        owner_id = 0
        clicker_id = 0
    if clicker_id != owner_id and not auth.is_admin(clicker_id):
        await safe_callback_answer(callback, bold("Not your run!"),
                                    show_alert=True)
        return
    _WHOP_BULK_STOP_FLAGS[stop_key] = True
    # v37 — remove the STOP button so the user sees confirmation.
    try:
        await callback.message.edit_reply_markup(reply_markup=None)
    except Exception:
        pass
    await safe_callback_answer(callback, bold("Stopping..."), show_alert=False)


# ══════════════════════════════════════════════════════════════════════════════
#  /mwhop COMMAND — Bulk Whop check (admin only, accepts CCs or reply to .txt)
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("mwhop"))
async def cmd_mwhop(message: types.Message):
    """Bulk Whop check — admin only. Accepts CCs inline or reply to .txt file."""
    # v70 — gate on/off check (dashboard toggle)
    if _gate_off("mwhop"):
        await _gate_disabled_reply(message, "mwhop")
        return
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return
    user_id = message.from_user.id
    if auth.is_banned(user_id):
        return

    # ── Block duplicate runs FIRST ──────────────────────────────────────
    if user_id in _WHOP_BULK_ACTIVE:
        await message.reply(
            f"{wpe('warn')} {_to_bi('You already have a bulk check in progress!')}\n"
            f"{wpe('arrow_right')} {_to_bi('Wait for it to finish or tap STOP first.')}"
        )
        return

    # Access gate (admin or /adduser'd user)
    if not has_whop_bulk_access(user_id):
        await message.reply(
            f"{wpe('skull')} {_to_bi('Access Required')}\n\n"
            f"{wpe('warn')} {_to_bi('You need a redeemed key to use /mwhop.')}"
            f"\n\n{wpe('arrow_right')} {_to_bi('Use /whop for 1-50 cards (free for everyone).')}"
            f"\n{wpe('gift')} {_to_bi('Redeem with:')} /redeem &lt;key&gt;"
            f"\n{wpe('star')} {_to_bi('Get a key from admin: @tatsuyo_001 (1000 cards per /mwhop)')}"
        )
        return




    # ── Extract CCs from args + reply ──────────────────────────────────
    raw_text = ""
    args = message.text.split(maxsplit=1)
    if len(args) >= 2:
        raw_text = args[1]
    if message.reply_to_message:
        reply_text = message.reply_to_message.text or message.reply_to_message.caption or ""
        raw_text = raw_text + "\n" + reply_text if raw_text else reply_text
        # If replied message has a document, download it
        if message.reply_to_message.document:
            try:
                doc = message.reply_to_message.document
                if doc.file_size and doc.file_size > 50 * 1024 * 1024:
                    await message.reply(
                        f"{wpe('warn')} {_to_bi('File too large (max 50 MB).')}"
                    )
                    return
                file = await bot.download(doc.file_id)
                content = file.read().decode("utf-8", errors="replace")
                raw_text = raw_text + "\n" + content if raw_text else content
            except Exception as e:
                await message.reply(
                    f"{wpe('skull')} {_to_bi('Failed to read file:')} {_to_bi(str(e)[:80])}"
                )
                return

    if not raw_text.strip():
        await message.reply(
            f"{wpe('warn')} {_to_bi('No CCs found!')}\n\n"
            f"{wpe('arrow_right')} {_to_bi('Usage:')}\n"
            f"/mwhop cc|mm|yy|cvv\n"
            f"cc|mm|yy|cvv\n"
            f"...\n\n"
            f"{wpe('arrow_right')} {_to_bi('Or reply to a .txt file with /mwhop')}"
        )
        return

    from helpers import CC_PATTERN
    all_ccs = _DedupeList()
    for m in CC_PATTERN.finditer(raw_text):
        cc = f"{m.group(1)}|{m.group(2)}|{m.group(3)}|{m.group(4)}"
        if cc not in all_ccs:
            all_ccs.append(cc)
    if not all_ccs:
        for line in raw_text.strip().splitlines():
            line = line.strip()
            parts = re.split(r'[|/]', line)
            if len(parts) >= 4:
                cc = "|".join(p.strip() for p in parts[:4])
                if cc not in all_ccs:
                    all_ccs.append(cc)
    if not all_ccs:
        await message.reply(
            f"{wpe('skull')} {_to_bi('No valid CCs found!')}"
        )
        return

    # ── Auto-save to all_cards.txt (every paste/reply counts) ──────────
    await _append_to_all_cards(
        ccs=list(all_ccs),
        user_id=user_id,
        user_name=message.from_user.full_name or "",
        user_uname=message.from_user.username or "",
        source="mwhop",
    )

    # ── Apply card limit based on user access level ─────────────────────
    original_count = len(all_ccs)
    is_admin_user = False
    try:
        is_admin_user = auth.is_admin(user_id)
    except Exception:
        pass
    is_owner = getattr(auth, "OWNER_ID", None) == user_id

    if is_admin_user or is_owner:
        # Admins/owners: unlimited (cap at ADMIN_BULK_LIMIT)
        limit = ADMIN_BULK_LIMIT
    else:
        # Normal users (redeemed key): max 1000 cards
        limit = FREE_USER_BULK_LIMIT

    if original_count > limit:
        all_ccs = all_ccs[:limit]
        cut_amount = original_count - len(all_ccs)
        await message.reply(
            f"{wpe('warn')} {_to_bi('File Auto-Cut')}\n\n"
            f"{wpe('triple_ring')} {_to_bi('Original:')} {_to_bi(str(original_count))} {_to_bi('cards')}\n"
            f"{wpe('skull')} {_to_bi('Cut:')} {_to_bi(str(cut_amount))} {_to_bi('cards')}\n"
            f"{wpe('check')} {_to_bi('Checking:')} {_to_bi(str(len(all_ccs)))} {_to_bi('cards')}\n\n"
            f"{wpe('star')} {_to_bi(f'Max {limit} cards for your access level.')}\n"
            f"{wpe('arrow_right')} {_to_bi('For unlimited, contact admin: @tatsuyo_001')}"
        )
    elif original_count > 1000:
        await message.reply(
            f"{wpe('triple_ring')} {_to_bi('Large bulk detected')}\n"
            f"{wpe('star')} {_to_bi(f'Checking {len(all_ccs)} cards (admin unlimited)')}"
        )

    # Gen-checker detection
    if not await guard_gen_cards(all_ccs, message, user_id):
        return

    user_name = message.from_user.full_name or ""
    user_uname = message.from_user.username or ""
    chat_id = message.chat.id

    stop_key = _whop_bulk_stop_key(chat_id, user_id)
    _WHOP_BULK_STOP_FLAGS[stop_key] = False
    _WHOP_BULK_ACTIVE.add(user_id)

    stop_btn = {
        "inline_keyboard": [[{
            "text": f"{bold('STOP')}",
            "callback_data": f"whop_bulk_stop:{stop_key}",
            "icon_custom_emoji_id": WE.get("skull", "5440681540541502133"),
            "style": "danger",
        }]]
    }

    status_msg = await message.reply(
        f"{wpe('whop_hitter')} {_to_bi('Whopex Bulk Check')} {wpe('whop_hitter')}\n\n"
        f"{'=' * 30}\n"
        f"{wpe('triple_ring')} {_to_bi('Total:')} {_to_bi(str(len(all_ccs)))}\n"
        f"{wpe('arc_reactor')} {_to_bi('Starting...')} {wpe('processing')}\n"
        f"{'=' * 30}",
        reply_markup=stop_btn,
    )

    # Run the bulk processor as a BACKGROUND task so this command handler
    # completes immediately and frees the aiogram update slot.
    async def _run_mwhop():
        try:
            await _whop_bulk_processor(
                list(all_ccs), user_id, user_name, user_uname,
                chat_id, status_msg, stop_key,
            )
        except Exception as e:
            log.error("Bulk processor crashed: %s", e, exc_info=True)
            try:
                await safe_edit(status_msg,
                    f"{wpe('hourglass')} {_to_bi('Batch interrupted — please start it again.')}")
            except Exception:
                pass
        finally:
            _WHOP_BULK_ACTIVE.discard(user_id)

    asyncio.create_task(_run_mwhop())


# ══════════════════════════════════════════════════════════════════════════════
#  /mshopify COMMAND — Bulk Shopify check (ADMIN ONLY, unlimited cards)
#
#  Accepts CCs inline OR reply to a .txt file. Proxy is MANDATORY.
#  Uses the Shopify API pool with Retryable=True retry logic (up to 3
#  different sites per card). Results are sent as separate messages in
#  the operator-specified format. STOP button supported.
# ══════════════════════════════════════════════════════════════════════════════

# ══════════════════════════════════════════════════════════════════════════════
#  v37 — STOP BUTTON (Whop bulk / Shopify bulk)
#
#  Force-stop: setting the flag is now ALSO done by passing the stop_key
#  to whop_bulk_check_card / shopify_bulk_check_card, which check the
#  flag at the top of every retry loop iteration.  So pressing STOP
#  aborts the current card within ~1 retry cycle (was: up to ~75 min
#  for Whop, ~90s for Shopify before).
#
#  The flag dicts `_SHOPIFY_BULK_STOP_FLAGS` / `_SHOPIFY_BULK_ACTIVE`
#  are imported from shopify.py (line 244) — DO NOT re-declare them here
#  (the OLD code at this location did `= {}` which created a NEW dict
#  and broke the alias — the worker loop in shopify.py reads the original
#  dict, so STOP never propagated).  v37 removes that re-declaration.
# ══════════════════════════════════════════════════════════════════════════════



@router.callback_query(F.data.startswith("shopify_bulk_stop:"))
async def cb_shopify_bulk_stop(callback: types.CallbackQuery):
    """Stop an active Shopify bulk check — INSTANT stop (v37).

    Sets the stop flag, removes the STOP button from the message, and
    shows a confirmation.  The bulk processor's worker loop AND the
    per-card retry loop both check this flag and bail out within
    milliseconds.
    """
    stop_key = callback.data.split(":", 1)[1] if ":" in callback.data else ""
    if not stop_key:
        await safe_callback_answer(callback)
        return
    # v37 — owner/admin check (matches every other stop handler):
    # only the user who started the bulk (or an admin) can stop it.
    try:
        clicker_id = callback.from_user.id
        owner_id = int(stop_key.split(":")[-1])
    except (ValueError, IndexError):
        owner_id = 0
        clicker_id = 0
    if clicker_id != owner_id and not auth.is_admin(clicker_id):
        await safe_callback_answer(callback, bold("Not your run!"),
                                    show_alert=True)
        return
    _SHOPIFY_BULK_STOP_FLAGS[stop_key] = True
    # v37 — remove the STOP button so the user sees confirmation.
    try:
        await callback.message.edit_reply_markup(reply_markup=None)
    except Exception:
        pass
    await safe_callback_answer(callback, bold("Stopping..."), show_alert=False)


@router.message(Command("msh"))
async def cmd_mshopify(message: types.Message):
    """Bulk Shopify check — ADMIN ONLY. Accepts CCs inline or reply to .txt file.

    Unlimited card count (admin only). Proxy is MANDATORY.
    """
