@router.message(Command("checkapi"))
async def cmd_checkapi(message: types.Message):
    if not auth.is_owner(message.from_user.id) and not auth.is_admin(message.from_user.id):
        await message.reply(f"{wpe('cross')} {bold('Owner/Admin only command!')}")
        return

    args = message.text.split(maxsplit=1)
    if len(args) < 2:
        await message.reply(
            f"{wpe('warn')} {bold('Usage:')}\n"
            f"  /checkapi {bold('sh')}   — test all Shopify APIs\n"
            f"  /checkapi {bold('whop')} — test all Whop APIs\n"
            f"  /checkapi {bold('st1')}  — test all Stripe 1$ APIs\n"
            f"  /checkapi {bold('sq')}   — test all Square APIs (v75 NEW)"
        )
        return

    gate = args[1].strip().lower()
    if gate not in ("sh", "shopify", "whop", "st1", "sq", "square"):
        await message.reply(
            f"{wpe('cross')} {bold('Unknown gate.')}\n"
            f"{wpe('next')} {bold('Usage:')} /checkapi {bold('sh|whop|st1|sq')}"
        )
        return

    if gate in ("sh", "shopify"):
        apis_file = SHOPIFY_APIS_FILE
        apis = _load_shopify_apis()
        gate_label = "Shopify"
    elif gate == "st1":
        apis_file = ST1_APIS_FILE
        apis = _load_st1_apis()
        gate_label = "Stripe 1$"
    elif gate in ("sq", "square"):
        apis_file = SQUARE_APIS_FILE
        apis = _load_square_apis() if HAS_SQUARE else []
        gate_label = "Square"
    else:
        apis_file = APIS_FILE
        try:
            apis = _load_apis()
        except Exception:
            apis = []
        gate_label = "Whop"

    if not apis:
        await message.reply(
            f"{wpe('warn')} {bold('No APIs configured for ' + gate_label)}"
        )
        return

    total = len(apis)
    status_msg = await message.reply(
        f"{wpe('arc_reactor')} {bold(gate_label + ' API Health Check')} {wpe('processing')}\n\n"
        f"{wpe('triple_ring')} {bold('Total:')} {bold(str(total))}\n"
        f"{wpe('check')} {bold('Live:')} 0\n"
        f"{wpe('skull')} {bold('Dead:')} 0\n"
        f"{wpe('arc_reactor')} {bold('Testing...')}"
    )

    # Test each API with a short timeout GET to its /check endpoint.
    # v45 — progressive updates: show live/dead count as each API completes.
    async def _test_one(api_url: str) -> tuple[str, bool, str]:
        api_url = api_url.rstrip("/")
        try:
            async with httpx.AsyncClient(timeout=15.0) as cli:
                try:
                    resp = await cli.get(f"{api_url}/check", timeout=15.0)
                    if resp.status_code < 500:
                        return (api_url, True, f"HTTP {resp.status_code}")
                    return (api_url, False, f"HTTP {resp.status_code}")
                except Exception:
                    # /check didn't work — try the root URL
                    resp = await cli.get(api_url, timeout=15.0)
                    if resp.status_code < 500:
                        return (api_url, True, f"root HTTP {resp.status_code}")
                    return (api_url, False, f"HTTP {resp.status_code}")
        except httpx.TimeoutException:
            return (api_url, False, "timeout")
        except httpx.ConnectError:
            return (api_url, False, "connection refused")
        except Exception as e:
            return (api_url, False, str(e)[:60])

    # v45 — progressive: test APIs and update the status box as each completes.
    _live_count = 0
    _dead_count = 0
    _last_edit = 0.0
    results = []

    async def _test_with_progress(api_url: str):
        nonlocal _live_count, _dead_count, _last_edit
        result = await _test_one(api_url)
        if result[1]:
            _live_count += 1
        else:
            _dead_count += 1
        results.append(result)
        # Update the status box every 3 completions or on every dead API.
        _now = time.monotonic()
        if (_dead_count > 0 or (_now - _last_edit) >= 2.0
                or len(results) == total):
            _last_edit = _now
            _tested = _live_count + _dead_count
            try:
                await safe_edit(status_msg,
                    f"{wpe('arc_reactor')} {bold(gate_label + ' API Health Check')} {wpe('processing')}\n\n"
                    f"{wpe('triple_ring')} {bold('Total:')} {bold(str(total))}\n"
                    f"{wpe('check')} {bold('Tested:')} {bold(str(_tested))}\n"
                    f"{wpe('approved')} {bold('Live:')} {bold(str(_live_count))}\n"
                    f"{wpe('skull')} {bold('Dead:')} {bold(str(_dead_count))}\n"
                    f"{wpe('arc_reactor')} {bold('Testing...')}"
                )
            except Exception:
                pass
        return result

    await asyncio.gather(*[_test_with_progress(a) for a in apis])

    live_apis = [r[0] for r in results if r[1]]
    dead_apis = [(r[0], r[2]) for r in results if not r[1]]

    # Remove dead APIs from the file (rewrite the file with only live ones).
    if dead_apis:
        try:
            with open(apis_file, "w", encoding="utf-8") as f:
                f.write(f"# {gate_label} APIs — auto-cleaned by /checkapi at "
                        f"{datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
                f.write(f"# Removed {len(dead_apis)} dead API(s)\n")
                for api in live_apis:
                    f.write(api + "\n")
        except Exception as e:
            log.error("Failed to rewrite %s: %s", apis_file, e)

    dead_lines = "\n".join(
        f"{wpe('skull')} <code>{_html.escape(url)}</code> — {reason}"
        for url, reason in dead_apis[:10]
    )
    if len(dead_apis) > 10:
        dead_lines += f"\n{wpe('arrow_right')} {bold(f'... {len(dead_apis) - 10} more dead')}"

    final_text = (
        f"{wpe('check')} {bold(gate_label + ' API Health Check')} {wpe('check')}\n\n"
        f"{wpe('triple_ring')} {bold('Tested:')} {bold(str(total))}\n"
        f"{wpe('approved')} {bold('Live:')} {bold(str(len(live_apis)))}\n"
        f"{wpe('skull')} {bold('Dead:')} {bold(str(len(dead_apis)))}\n"
    )
    if dead_apis:
        final_text += f"\n{bold('Removed dead APIs from ' + apis_file.split(os.sep)[-1])}:\n{dead_lines}\n"
    else:
        final_text += f"\n{wpe('approved')} {bold('All APIs are live — no removals needed')}\n"
    final_text += f"\n{wpe('whop_hitter')} {bold('Whopex')}"

    try:
        await safe_edit(status_msg, final_text)
    except Exception:
        await message.reply(final_text)


