@router.message(Command("st1"))
async def cmd_st1(message: types.Message):
    # v70 — gate on/off check (dashboard toggle)
    if _gate_off("st1"):
        await _gate_disabled_reply(message, "st1")
        return
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return

    user_id = message.from_user.id
    if auth.is_banned(user_id):
        return

    if not auth.has_premium_access(user_id, message.chat.id):
        await message.reply(
            f"{wpe('cross')} {bold('Premium Access Required!')}\n\n"
            f"{wpe('bolt')} {bold('Contact admin or redeem a key: @tatsuyo_001')}\n"
            f"{wpe('next')} /redeem {bold('Tatsuyo-xxxxx')}"
        )
        return

    remaining = check_cooldown(user_id)
    if remaining > 0:
        await message.reply(
            f"{wpe('warn')} {bold('Slow down!')} Please wait {bold(f'{remaining:.0f}s')} before next check."
        )
        return

    # Extract CC
    cc_str = None
    args = message.text.split(maxsplit=1)
    if len(args) >= 2:
        cc_str = extract_cc(args[1])
        if not cc_str:
            parts = re.split(r'[|/]', args[1].strip())
            if len(parts) >= 4:
                cc_str = "|".join(p.strip() for p in parts[:4])
    if not cc_str and message.reply_to_message:
        reply_text = message.reply_to_message.text or message.reply_to_message.caption or ""
        cc_str = extract_cc(reply_text)

    if not cc_str:
        await message.reply(
            f"{wpe('warn')} {bold('No CC found!')}\n\n"
            f"{wpe('next')} {bold('Usage:')} /st1 4111111111111111|01|2030|123"
        )
        return

    user_name = message.from_user.full_name or ""
    user_uname = message.from_user.username or ""
    user_link_html = user_link(user_id, user_name, user_uname)

    loading_msg = await message.reply(
        f"{wpe('arc_reactor')} {_to_bi('Stripe 1$ Auth')} {wpe('processing')}\n\n"
        f"{wpe('card')} {_to_bi('CC:')} <code>{cc_str}</code>\n"
        f"{wpe('time')} {_to_bi('Checking...')}"
    )

    bin_num = cc_str.split("|")[0][:6]
    _bin_task = asyncio.create_task(bin_lookup(bin_num))
    whop_set_cooldown(user_id)

    try:
        result = await st1_check_card(cc_str, user_id=user_id, priority=True)
    except Exception:
        result = {
            "status": "ERROR", "card": cc_str, "price": "-",
            "elapsed": 0.0, "response": "Check failed",
            "status_code": "ERROR", "gate": "Stripe 1$",
            "is_charged": False, "is_approved": False,
            "is_dead": False, "is_retryable": False,
        }

    bin_info = await _bin_task
    result_text = _st1_format_message(result, user_link_html, cc_str, bin_info)

    try:
        await loading_msg.edit_text(result_text)
    except Exception:
        await message.reply(result_text)

    # Log side effects
    try:
        await _save_to_checked_txt(cc_str, result, user_id, user_name, "st1")
    except Exception:
        pass
    # v52 — write to st1_logs.txt (every check) + st1_dec&approved.txt (real responses)
    try:
        await _st1_log_check(result, user_id, user_name, user_uname)
    except Exception:
        pass
    try:
        await _st1_save_dec_appr(cc_str, result, user_id, user_name, user_uname)
    except Exception:
        pass
    # v52 — hit_sites.txt logging (only for real responses)
    try:
        _hit_site = str(result.get("site", "") or "")
        _hit_sc = str(result.get("status_code", "") or "").upper()
        if _hit_site and _hit_site not in ("-", "—", "N/A", "None") and _hit_sc and _hit_sc not in ("", "-", "NO_RESPONSE", "UNKNOWN"):
            _status = str(result.get("status", "")).upper()
            if _status == "APPROVED":
                _hit_label = "Approved"
            elif _status == "3DS":
                _hit_label = "3DS"
            elif _status == "INSUFFICIENT":
                _hit_label = "Insufficient"
            elif _status == "DECLINED":
                _hit_label = "Declined"
            else:
                _hit_label = None
            if _hit_label:
                await _save_hit_site(_hit_site, result.get("price", "-"), _hit_label)
    except Exception:
        pass

    _status = str(result.get("status", "")).upper()
    if _status == "APPROVED":
        # v52 — send approved message to user's chat
        try:
            await message.reply(result_text)
        except Exception:
            pass
        try:
            auth.save_charged_cc(cc_str, user_id, user_name, "Stripe 1$",
                                  str(result.get("price", "-")))
        except Exception:
            pass
        # v52 — pin the approved message
        try:
            await bot.pin_chat_message(
                message.chat.id, loading_msg.message_id, disable_notification=True,
            )
        except Exception:
            pass
        # v52 — forward to charged group
        try:
            await _forward_charged_group(
                card=cc_str, price=str(result.get("price", "-")),
                gate="Stripe 1$", response=str(result.get("display_response") or result.get("response", "-")),
                user_id=user_id, user_name=user_name, user_uname=user_uname,
                elapsed=float(result.get("elapsed", 0.0) or 0.0))
        except Exception:
            pass
        # v52 — send to hit channel (like Shopify's _send_shopify_hit_channel)
        try:
            asyncio.create_task(_send_st1_hit_channel(
                price=str(result.get("price", "-")),
                elapsed=float(result.get("elapsed", 0.0) or 0.0),
                user_id=user_id, user_name=user_name, user_uname=user_uname,
            ))
        except Exception:
            pass


# ══════════════════════════════════════════════════════════════════════════════
#  /mst1 — Stripe 1$ Auth bulk check (reply to .txt file)
#  Key-redeemed users: max 1000 cards (auto-cut).  Admin/owner: unlimited.
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("mst1"))
async def cmd_mst1(message: types.Message):
    # v70 — gate on/off check (dashboard toggle)
    if _gate_off("mst1"):
        await _gate_disabled_reply(message, "mst1")
        return
    if not auth.is_owner(message.from_user.id) and not auth.is_admin(message.from_user.id):
        # Key-redeemed users can use /mst1 up to 1000 cards
        if not auth.has_premium_access(message.from_user.id, message.chat.id):
            await message.reply(
                f"{wpe('cross')} {bold('Premium Access Required!')}\n\n"
                f"{wpe('bolt')} {bold('Contact admin or redeem a key: @tatsuyo_001')}\n"
                f"{wpe('next')} /redeem {bold('Tatsuyo-xxxxx')}"
            )
            return

    user_id = message.from_user.id
    if auth.is_banned(user_id):
        return

    # Must reply to a .txt file
    if not message.reply_to_message or not message.reply_to_message.document:
        await message.reply(
            f"{wpe('warn')} {bold('Reply to a .txt file with cards!')}\n\n"
            f"{wpe('next')} {bold('Usage:')} Reply to a .txt file with /mst1"
        )
        return

    # Download and read the file
    loading_msg = await message.reply(
        f"{wpe('arc_reactor')} {_to_bi('Downloading and reading file...')} {wpe('processing')}"
    )
    try:
        file_id = message.reply_to_message.document.file_id
        file = await bot.get_file(file_id)
        raw_bytes = await bot.download_file(file.file_path)
        # v50 — bot.download_file returns BytesIO in newer aiogram; read() first.
        if hasattr(raw_bytes, "read"):
            raw_bytes = raw_bytes.read()
        raw_text = raw_bytes.decode("utf-8", errors="replace")
    except Exception as e:
        await safe_edit(loading_msg, f"{wpe('cross')} {bold('Failed to read file:')} {str(e)[:80]}")
        return

    # Extract CCs
    from helpers import CC_PATTERN
    all_ccs = _DedupeList()
    for m in CC_PATTERN.finditer(raw_text):
        cc = f"{m.group(1)}|{m.group(2)}|{m.group(3)}|{m.group(4)}"
        if cc not in all_ccs:
            all_ccs.append(cc)
    if not all_ccs:
        for line in raw_text.strip().splitlines():
            line = line.strip()
            parts = re.split(r'[|/]', line)
            if len(parts) >= 4:
                cc = "|".join(p.strip() for p in parts[:4])
                if cc not in all_ccs:
                    all_ccs.append(cc)
    if not all_ccs:
        await safe_edit(loading_msg, f"{wpe('skull')} {bold('No valid CCs found!')}")
        return

    # v38-style: auto-cut expired cards
    import calendar
    import datetime as _dt
    _now = _dt.datetime.now(_dt.timezone.utc)
    _kept_ccs = _DedupeList()
    _expired_ccs: list = []
    for cc_str in all_ccs:
        try:
            parts = cc_str.split("|")
            if len(parts) < 4:
                _kept_ccs.append(cc_str)
                continue
            mm = int(parts[1])
            yy = int(parts[2])
            if yy < 100:
                yy = 2000 + yy
            if mm < 1 or mm > 12:
                _kept_ccs.append(cc_str)
                continue
            last_day = calendar.monthrange(yy, mm)[1]
            expiry = _dt.datetime(yy, mm, last_day, 23, 59, 59, tzinfo=_dt.timezone.utc)
            if expiry < _now:
                _expired_ccs.append(cc_str)
            else:
                _kept_ccs.append(cc_str)
        except Exception:
            _kept_ccs.append(cc_str)

    _original_count = len(all_ccs)
    _expired_count = len(_expired_ccs)
    if _expired_count > 0:
        all_ccs = _kept_ccs
        try:
            await message.reply(
                f"{wpe('warn')} {bold('Auto-cut expired cards')} {wpe('warn')}\n\n"
                f"{wpe('triple_ring')} {bold('Original:')} {bold(str(_original_count))} {bold('cards')}\n"
                f"{wpe('skull')} {bold('Expired (auto-cut):')} {bold(str(_expired_count))} {bold('cards')}\n"
                f"{wpe('check')} {bold('Remaining (will check):')} {bold(str(len(all_ccs)))} {bold('cards')}"
            )
        except Exception:
            pass

    if not all_ccs:
        await safe_edit(loading_msg, f"{wpe('skull')} {bold('All cards were expired!')}")
        return

    # v45 — card limit: key-redeemed users max 1000, admin/owner unlimited
    is_admin_user = auth.is_owner(user_id) or auth.is_admin(user_id)
    max_cards = ST1_ADMIN_MAX_CARDS if is_admin_user else ST1_USER_MAX_CARDS
    if len(all_ccs) > max_cards:
        cut_count = len(all_ccs) - max_cards
        all_ccs = all_ccs[:max_cards]
        try:
            await message.reply(
                f"{wpe('warn')} {bold('Card limit reached')} {wpe('warn')}\n\n"
                f"{wpe('triple_ring')} {bold('Max for your tier:')} {bold(str(max_cards))} {bold('cards')}\n"
                f"{wpe('skull')} {bold('Auto-cut:')} {bold(str(cut_count))} {bold('cards')}\n"
                f"{wpe('check')} {bold('Will check:')} {bold(str(len(all_ccs)))} {bold('cards')}"
            )
        except Exception:
            pass

    user_name = message.from_user.full_name or ""
    user_uname = message.from_user.username or ""
    chat_id = message.chat.id
    total = len(all_ccs)
    stop_key = _st1_bulk_stop_key(chat_id, user_id)
    _ST1_BULK_STOP_FLAGS[stop_key] = False
    _ST1_BULK_ACTIVE.add(user_id)

    stop_btn = {
        "inline_keyboard": [[{
            "text": f"{bold('STOP')}",
            "callback_data": f"st1_bulk_stop:{stop_key}",
            "icon_custom_emoji_id": WE.get("skull", "5440681540541502133"),
            "style": "danger",
        }]]
    }
    status_msg = await message.reply(
        f"{wpe('sparkle')} {_to_bi('Stripe 1$ Bulk Check')} {wpe('sparkle')}\n\n"
        f"{'=' * 30}\n"
        f"{wpe('triple_ring')} {_to_bi('Total:')} {_to_bi(str(total))}\n"
        f"{wpe('check')} {_to_bi('Checked:')} 0\n"
        f"{wpe('arc_reactor')} {_to_bi('Pending:')} {_to_bi(str(total))}\n"
        f"{'=' * 30}\n"
        f"{wpe('approved')} {_to_bi('Approved:')} 0\n"
        f"{wpe('insufficient')} {_to_bi('Live CC:')} 0\n"
        f"{wpe('warn')} {_to_bi('3DS:')} 0\n"
        f"{wpe('skull')} {_to_bi('Declined:')} 0\n"
        f"{wpe('red_warn')} {_to_bi('Error:')} 0\n"
        f"{'=' * 30}\n\n"
        f"{wpe('arc_reactor')} {_to_bi('Starting...')} {wpe('processing')}",
        reply_markup=stop_btn,
    )

    async def _run_mst1():
        try:
            await _st1_bulk_processor(all_ccs, user_id, user_name, user_uname,
                                       chat_id, status_msg, stop_key)
        except Exception as e:
            log.error("[/mst1] bulk processor crashed: %s", e, exc_info=True)
        finally:
            _ST1_BULK_ACTIVE.discard(user_id)

    asyncio.create_task(_run_mst1())


# ══════════════════════════════════════════════════════════════════════════════
#  ST1 STOP callback
# ══════════════════════════════════════════════════════════════════════════════

@router.callback_query(F.data.startswith("st1_bulk_stop:"))
async def cb_st1_bulk_stop(callback: types.CallbackQuery):
    stop_key = callback.data.split(":", 1)[1] if ":" in callback.data else ""
    if not stop_key:
        await safe_callback_answer(callback)
        return
    try:
        clicker_id = callback.from_user.id
        owner_id = int(stop_key.split(":")[-1])
    except (ValueError, IndexError):
        owner_id = 0
        clicker_id = 0
    if clicker_id != owner_id and not auth.is_admin(clicker_id):
        await safe_callback_answer(callback, bold("Not your run!"), show_alert=True)
        return
    _ST1_BULK_STOP_FLAGS[stop_key] = True
    try:
        await callback.message.edit_reply_markup(reply_markup=None)
    except Exception:
        pass
    await safe_callback_answer(callback, bold("Stopping..."), show_alert=False)


# ══════════════════════════════════════════════════════════════════════════════
#  /sq — Square single-card charge (1-20 cards, $1-$10 amount)
#  v75 NEW
#
#  Usage:
#    /sq <card>                 → $1.00 charge, 1 card
#    /sq <card1> <card2> ...    → $1.00 charge, up to 5 cards
#    /sq2 <card>                → $2.00 charge
#    /sq3 <card>                → $3.00 charge
#    ...
#    /sq10 <card>               → $10.00 charge
#
#  The amount is parsed from the command name: /sq = $1, /sq2 = $2, ... /sq10 = $10
#  Default (no number) = $1.00
# ══════════════════════════════════════════════════════════════════════════════

# Map of /sqN command → amount in cents
_SQ_AMOUNT_MAP = {
    "sq":   100,    # $1.00
    "sq1":  100,    # $1.00 (alias)
    "sq2":  200,    # $2.00
    "sq3":  300,    # $3.00
    "sq4":  400,    # $4.00
    "sq5":  500,    # $5.00
    "sq6":  600,    # $6.00
    "sq7":  700,    # $7.00
    "sq8":  800,    # $8.00
    "sq9":  900,    # $9.00
    "sq10": 1000,   # $10.00
}


def _parse_sq_command(text: str) -> tuple[str, int]:
    """Extract the command name + amount_cents from a message like '/sq5 card...'.
    Returns (command_name, amount_cents). Defaults to ('sq', 100) if parse fails.
    """
    if not text or not text.startswith("/"):
        return ("sq", 100)
    # Get the command name (first token, before space)
    first_token = text.split(maxsplit=1)[0].lstrip("/").lower().split("@")[0]
    # Strip any leading non-alphanumeric
    cmd = "".join(c for c in first_token if c.isalnum()).lower()
    amount_cents = _SQ_AMOUNT_MAP.get(cmd, 100)
    return (cmd if cmd in _SQ_AMOUNT_MAP else "sq", amount_cents)


# Register /sq, /sq1, /sq2, ..., /sq10 all on the same handler
@router.message(Command("sq", "sq1", "sq2", "sq3", "sq4", "sq5",
                         "sq6", "sq7", "sq8", "sq9", "sq10"))
async def cmd_sq(message: types.Message):
    """v78 — Square single-card charge. 1-20 cards, $1-$10 amount.

    Access: key-redeemed users, admins, owner. (Same as /st1.)
    Card limit: 1-20 cards per command (sequential).
    Amount: parsed from command name (/sq = $1, /sq2 = $2, ..., /sq10 = $10).
    """
    # Gate on/off check
    if _gate_off("sq"):
        await _gate_disabled_reply(message, "sq")
        return

    if not HAS_SQUARE:
        await message.reply(
            f"{wpe('cross')} {bold('Square gate not available.')}\n"
            f"{wpe('warn')} {_to_bi('sqcharge.py failed to import — check logs.')}"
        )
        return

    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return

    user_id = message.from_user.id
    if auth.is_banned(user_id):
        return

    # Access: key-redeemed / admin / owner (same as /st1)
    if not auth.has_premium_access(user_id, message.chat.id):
        await message.reply(
            f"{wpe('cross')} {bold('Premium Access Required!')}\n\n"
            f"{wpe('bolt')} {bold('Contact admin or redeem a key: @tatsuyo_001')}\n"
            f"{wpe('next')} /redeem {bold('Tatsuyo-xxxxx')}"
        )
        return

    remaining = check_cooldown(user_id)
    if remaining > 0:
        await message.reply(
            f"{wpe('warn')} {bold('Slow down!')} Please wait {bold(f'{remaining:.0f}s')} before next check."
        )
        return

    # Parse the command → amount_cents
    cmd_name, amount_cents = _parse_sq_command(message.text or "")
    price_str = f"${amount_cents / 100:.2f}"

    # Extract CCs from the message (inline 1-5 cards)
    raw_text = ""
    args = message.text.split(maxsplit=1)
    if len(args) >= 2:
        raw_text = args[1]
    if message.reply_to_message:
        reply_text = message.reply_to_message.text or message.reply_to_message.caption or ""
        raw_text = (raw_text + "\n" + reply_text).strip() if raw_text else reply_text

    if not raw_text.strip():
        await message.reply(
            f"{wpe('warn')} {bold('No CC found!')}\n\n"
            f"{wpe('next')} {bold('Usage:')} /sq 4111111111111111|12|2027|123\n"
            f"{wpe('next')} {_to_bi('Or /sq2-/sq10 for $2-$10 charges')}\n"
            f"{wpe('star')} {_to_bi(f'Max {SQUARE_SINGLE_MAX_CARDS} cards per /sq command')}"
        )
        return

    # Extract cards — use _FULL_CC_RE first (supports 12-19 digit numbers incl. Amex 15-digit)
    # then fall back to helpers.CC_PATTERN, then line-split
    all_ccs = _DedupeList()
    for m in _FULL_CC_RE.finditer(raw_text):
        cc = f"{m.group(1)}|{m.group(2)}|{m.group(3)}|{m.group(4)}"
        if cc not in all_ccs:
            all_ccs.append(cc)
    if not all_ccs:
        try:
            from helpers import CC_PATTERN
            for m in CC_PATTERN.finditer(raw_text):
                cc = f"{m.group(1)}|{m.group(2)}|{m.group(3)}|{m.group(4)}"
                if cc not in all_ccs:
                    all_ccs.append(cc)
        except Exception:
            pass
    if not all_ccs:
        for line in raw_text.strip().splitlines():
            line = line.strip()
            parts = re.split(r'[|/]', line)
            if len(parts) >= 4:
                cc = "|".join(p.strip() for p in parts[:4])
                if cc not in all_ccs:
                    all_ccs.append(cc)

    if not all_ccs:
        await message.reply(
            f"{wpe('skull')} {bold('No valid CCs found!')}\n\n"
            f"{wpe('next')} {bold('Usage:')} /sq 4111111111111111|12|2027|123"
        )
        return

    # v78 — Auto-cut expired cards BEFORE checking (user spec: MUST)
    try:
        _valid_sq, _expired_sq = filter_expired_cards(list(all_ccs))
        if _expired_sq:
            all_ccs = _DedupeList()
            for _vcc in _valid_sq:
                all_ccs.append(_vcc)
            try:
                await message.reply(
                    f"{wpe('warn')} {bold('Auto-Cut Expired')} {wpe('warn')}\n\n"
                    f"{wpe('skull')} {bold('Removed:')} {bold(str(len(_expired_sq)))} {bold('expired cards')}\n"
                    f"{wpe('check')} {bold('Will check:')} {bold(str(len(all_ccs)))} {bold('cards')}"
                )
            except Exception:
                pass
    except Exception:
        pass
    if not all_ccs:
        await message.reply(
            f"{wpe('skull')} {bold('All cards are expired!')}\n\n"
            f"{wpe('warn')} {_to_bi('Nothing to check — every card in the list is past its expiry date.')}"
        )
        return

    # Enforce 1-20 card limit
    if len(all_ccs) > SQUARE_SINGLE_MAX_CARDS:
        cut = len(all_ccs) - SQUARE_SINGLE_MAX_CARDS
        all_ccs = all_ccs[:SQUARE_SINGLE_MAX_CARDS]
        try:
            await message.reply(
                f"{wpe('warn')} {bold('Card limit reached')} {wpe('warn')}\n\n"
                f"{wpe('triple_ring')} {bold('Max:')} {bold(str(SQUARE_SINGLE_MAX_CARDS))} {bold('cards per /sq')}\n"
                f"{wpe('skull')} {bold('Auto-cut:')} {bold(str(cut))} {bold('cards')}\n"
                f"{wpe('check')} {bold('Will check:')} {bold(str(len(all_ccs)))} {bold('cards')}\n\n"
                f"{wpe('star')} {_to_bi('Use /msq for bulk (reply to .txt file)')}"
            )
        except Exception:
            pass

    user_name = message.from_user.full_name or ""
    user_uname = message.from_user.username or ""
    user_link_html = user_link(user_id, user_name, user_uname)
    total = len(all_ccs)

    # v76 — load the user's UNIFIED proxy pool (whop_proxies.json + proxy.json
    # + global_proxies.txt). Previously /sq only read proxy.json, which meant
    # proxies added via /addproxy (saved to whop_proxies.json) were NEVER used
    # — leading to "CONNECT tunnel failed / response 403" errors with stale
    # proxies. The full pool is passed to square_check_card so it can rotate
    # through all proxies on transport/proxy errors.
    user_proxy_pool = _get_unified_proxy_pool(user_id)
    # Single-proxy compat: pick the first proxy from the pool as the "primary"
    # proxy argument. square_check_card will rotate through the full pool.
    user_proxy = user_proxy_pool[0] if user_proxy_pool else ""

    loading_msg = await message.reply(
        f"{wpe('arc_reactor')} {_to_bi('Square Charge')} {wpe('processing')}\n\n"
        f"{wpe('amount')} {_to_bi('Price:')} {_to_bi(price_str)}\n"
        f"{wpe('triple_ring')} {_to_bi('Cards:')} {_to_bi(str(total))}\n"
        f"{wpe('arrow_right')} {_to_bi('Proxies:')} {_to_bi(str(len(user_proxy_pool)))}\n"
        f"{wpe('time')} {_to_bi('Charging...')}"
    )

    set_cooldown(user_id)

    # Charge each card sequentially
    approved_count = 0
    for cc in all_ccs:
        bin_num = cc.split("|")[0][:6]
        _bin_task = asyncio.create_task(bin_lookup(bin_num))
        try:
            result = await square_check_card(
                cc, user_id=user_id, user_name=user_name, user_uname=user_uname,
                amount_cents=amount_cents, proxy=user_proxy,
                proxy_pool=user_proxy_pool, priority=True,
            )
        except Exception:
            result = {
                "status": "ERROR", "card": cc, "price": price_str,
                "elapsed": 0.0, "response": "Square API call failed",
                "reason": "Transport error", "display_response": "ERROR",
                "site": "", "merchant_id": "", "checkout_id": "",
                "amount_cents": amount_cents, "raw": {},
                "is_charged": False, "is_approved": False,
                "is_dead": False, "is_retryable": True,
                "gate": "Square", "status_code": "ERROR", "error": "Call failed",
                "time": "",
            }

        bin_info = await _bin_task
        result_text = _square_format_message(result, user_link_html, cc, bin_info, amount_cents)

        # Send the result as a new message
        try:
            await message.reply(result_text)
        except Exception:
            pass

        # Log side effects
        try:
            await _save_to_checked_txt(cc, result, user_id, user_name, "sq")
        except Exception:
            pass
        try:
            await _square_log_check(result, user_id, user_name, user_uname)
        except Exception:
            pass
        try:
            await _square_save_dec_appr(cc, result, user_id, user_name, user_uname)
        except Exception:
            pass

        _status = str(result.get("status", "")).upper()
        if _status == "APPROVED":
            approved_count += 1
            try:
                auth.save_charged_cc(cc, user_id, user_name, "Square", price_str)
            except Exception:
                pass
            try:
                await _forward_charged_group(
                    card=cc, price=price_str, gate="Square",
                    response=result.get("display_response", ""),
                    user_id=user_id, user_name=user_name, user_uname=user_uname,
                    bin_info=bin_info,
                    elapsed=float(result.get("elapsed", 0.0) or 0.0))
            except Exception:
                pass
            try:
                asyncio.create_task(_send_square_hit_channel(
                    price=price_str,
                    elapsed=float(result.get("elapsed", 0.0) or 0.0),
                    user_id=user_id, user_name=user_name, user_uname=user_uname,
                    amount_cents=amount_cents,
                    response=result.get("response", ""),
                    reason=result.get("reason", ""),
                ))
            except Exception:
                pass

    # Final summary edit on the loading_msg
    try:
        await safe_edit(loading_msg,
            f"{wpe('check')} {_to_bi('Square Charge Complete')} {wpe('check')}\n\n"
            f"{wpe('amount')} {_to_bi('Price:')} {_to_bi(price_str)}\n"
            f"{wpe('triple_ring')} {_to_bi('Total:')} {_to_bi(str(total))}\n"
            f"{wpe('approved')} {_to_bi('Approved:')} {_to_bi(str(approved_count))}\n"
            f"{wpe('skull')} {_to_bi('Declined:')} {_to_bi(str(total - approved_count))}\n\n"
            f"{wpe('whop_hitter')} {_to_bi('Whopex')}"
        )
    except Exception:
        pass


# ══════════════════════════════════════════════════════════════════════════════
#  /msq — Square bulk charge (reply to .txt file, always $1.00 charge)
#  v75 NEW
#
#  Usage: reply to a .txt file with cards, then send /msq
#
#  Card limits:
#    Key-redeemed users: 10-200 cards
#    Admins:             10-500 cards
#    Owner:              10-10,000,000 cards
#
#  Cards below 10 → auto-padded with a notice. Cards above the limit → auto-cut.
#  Always charges $1.00 per card (no /msq2-/msq10 variant).
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("msq"))
async def cmd_msq(message: types.Message):
    """v75 — Square bulk charge. Reply to .txt file. Always $1.00/card.

    Access: key-redeemed / admin / owner.
    Card limit by tier:
      key-redeemed: 10-200
      admin:        10-500
      owner:        10-10,000,000
    """
    # Gate on/off check
    if _gate_off("msq"):
        await _gate_disabled_reply(message, "msq")
        return

    if not HAS_SQUARE:
        await message.reply(
            f"{wpe('cross')} {bold('Square gate not available.')}\n"
            f"{wpe('warn')} {_to_bi('sqcharge.py failed to import — check logs.')}"
        )
        return

    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return

    user_id = message.from_user.id
    if auth.is_banned(user_id):
        return

    # Access: admin, owner, OR redeemed-key user
    is_admin_user = False
    try:
        is_admin_user = auth.is_admin(user_id)
    except Exception:
        pass
    is_owner = (getattr(auth, "OWNER_ID", None) == user_id) or \
               (hasattr(auth, "is_owner") and auth.is_owner(user_id))

    if not is_admin_user and not is_owner:
        if not auth.has_premium_access(user_id, message.chat.id):
            await message.reply(
                f"{wpe('cross')} {bold('Premium Access Required!')}\n\n"
                f"{wpe('bolt')} {bold('Contact admin or redeem a key: @tatsuyo_001')}\n"
                f"{wpe('next')} /redeem {bold('Tatsuyo-xxxxx')}"
            )
            return

    # Must reply to a .txt file
    if not message.reply_to_message or not message.reply_to_message.document:
        await message.reply(
            f"{wpe('warn')} {bold('Reply to a .txt file with cards!')}\n\n"
            f"{wpe('next')} {bold('Usage:')} Reply to a .txt file with /msq\n"
            f"{wpe('star')} {_to_bi('Always $1.00 charge per card')}\n"
            f"{wpe('triple_ring')} {_to_bi('Key users: 10-200 cards | Admin: 10-500 | Owner: 10-10M')}"
        )
        return

    # Download and read the file
    loading_msg = await message.reply(
        f"{wpe('arc_reactor')} {_to_bi('Downloading and reading file...')} {wpe('processing')}"
    )
    try:
        file_id = message.reply_to_message.document.file_id
        file = await bot.get_file(file_id)
        raw_bytes = await bot.download_file(file.file_path)
        if hasattr(raw_bytes, "read"):
            raw_bytes = raw_bytes.read()
        raw_text = raw_bytes.decode("utf-8", errors="replace")
    except Exception as e:
        await safe_edit(loading_msg, f"{wpe('cross')} {bold('Failed to read file:')} {str(e)[:80]}")
        return

    # Extract CCs — use _FULL_CC_RE first (supports Amex 15-digit), then helpers, then line-split
    all_ccs = _DedupeList()
    for m in _FULL_CC_RE.finditer(raw_text):
        cc = f"{m.group(1)}|{m.group(2)}|{m.group(3)}|{m.group(4)}"
        if cc not in all_ccs:
            all_ccs.append(cc)
    if not all_ccs:
        try:
            from helpers import CC_PATTERN
            for m in CC_PATTERN.finditer(raw_text):
                cc = f"{m.group(1)}|{m.group(2)}|{m.group(3)}|{m.group(4)}"
                if cc not in all_ccs:
                    all_ccs.append(cc)
        except Exception:
            pass
    if not all_ccs:
        for line in raw_text.strip().splitlines():
            line = line.strip()
            parts = re.split(r'[|/]', line)
            if len(parts) >= 4:
                cc = "|".join(p.strip() for p in parts[:4])
                if cc not in all_ccs:
                    all_ccs.append(cc)
    if not all_ccs:
        await safe_edit(loading_msg, f"{wpe('skull')} {bold('No valid CCs found!')}")
        return

    # Auto-cut expired cards
    try:
        from datetime import datetime
        import calendar
        now = datetime.now()
        kept = _DedupeList()
        cut_expired = 0
        for cc in all_ccs:
            parts = cc.split("|")
            if len(parts) < 4:
                kept.append(cc)
                continue
            try:
                mm = int(parts[1])
                yy = int(parts[2])
                if yy < 100:
                    yy = 2000 + yy
                if yy < now.year or (yy == now.year and mm < now.month):
                    cut_expired += 1
                    continue
                # Validate month
                if mm < 1 or mm > 12:
                    cut_expired += 1
                    continue
                # Validate day (use last day of month)
                last_day = calendar.monthrange(yy, mm)[1]
                if last_day < 1:
                    cut_expired += 1
                    continue
                kept.append(cc)
            except (ValueError, IndexError):
                kept.append(cc)
        if cut_expired > 0:
            all_ccs = kept
            try:
                await message.reply(
                    f"{wpe('warn')} {bold('Auto-Cut Expired')} {wpe('warn')}\n\n"
                    f"{wpe('skull')} {bold('Removed:')} {bold(str(cut_expired))} {bold('expired cards')}\n"
                    f"{wpe('check')} {bold('Remaining:')} {bold(str(len(all_ccs)))} {bold('cards')}"
                )
            except Exception:
                pass
    except Exception:
        pass

    if not all_ccs:
        await safe_edit(loading_msg, f"{wpe('skull')} {bold('No valid CCs after expiry cut!')}")
        return

    # Determine the user's tier limit
    if is_owner:
        max_cards = SQUARE_OWNER_MAX_CARDS
        tier_label = "Owner"
    elif is_admin_user:
        max_cards = SQUARE_ADMIN_MAX_CARDS
        tier_label = "Admin"
    else:
        max_cards = SQUARE_USER_MAX_CARDS
        tier_label = "Key User"

    # Enforce the limit (auto-cut if exceeds)
    original_count = len(all_ccs)
    if original_count > max_cards:
        cut_count = original_count - max_cards
        all_ccs = all_ccs[:max_cards]
        try:
            await message.reply(
                f"{wpe('warn')} {bold('Card limit reached')} {wpe('warn')}\n\n"
                f"{wpe('triple_ring')} {bold('Tier:')} {bold(tier_label)}\n"
                f"{wpe('triple_ring')} {bold('Max:')} {bold(str(max_cards))} {bold('cards')}\n"
                f"{wpe('skull')} {bold('Auto-cut:')} {bold(str(cut_count))} {bold('cards')}\n"
                f"{wpe('check')} {bold('Will check:')} {bold(str(len(all_ccs)))} {bold('cards')}\n\n"
                f"{wpe('star')} {_to_bi('For higher limits, contact admin: @tatsuyo_001')}"
            )
        except Exception:
            pass

    # Enforce the 10-card minimum
    if len(all_ccs) < SQUARE_USER_MIN_CARDS:
        try:
            await message.reply(
                f"{wpe('warn')} {bold('Too few cards')} {wpe('warn')}\n\n"
                f"{wpe('triple_ring')} {bold('Min:')} {bold(str(SQUARE_USER_MIN_CARDS))} {bold('cards')}\n"
                f"{wpe('check')} {bold('Found:')} {bold(str(len(all_ccs)))} {bold('cards')}\n\n"
                f"{wpe('star')} {_to_bi('Use /sq for 1-20 cards instead')}"
            )
        except Exception:
            pass
        # Don't return — still process what we have

    user_name = message.from_user.full_name or ""
    user_uname = message.from_user.username or ""
    chat_id = message.chat.id
    total = len(all_ccs)
    amount_cents = 100  # /msq always charges $1.00
    price_str = f"${amount_cents / 100:.2f}"

    # v76 — load the user's UNIFIED proxy pool (whop_proxies.json + proxy.json
    # + global_proxies.txt). Previously /msq only read proxy.json, which meant
    # proxies added via /addproxy (saved to whop_proxies.json) were NEVER used
    # — leading to "CONNECT tunnel failed / response 403" errors with stale
    # proxies. The full pool is passed to square_check_card so it can rotate
    # through all proxies on transport/proxy errors.
    user_proxy_list = _get_unified_proxy_pool(user_id)

    stop_key = _square_bulk_stop_key(chat_id, user_id)
    _SQUARE_BULK_STOP_FLAGS[stop_key] = False
    _SQUARE_BULK_ACTIVE.add(user_id)

    stop_btn = {
        "inline_keyboard": [[{
            "text": f"{bold('STOP')}",
            "callback_data": f"square_bulk_stop:{stop_key}",
            "icon_custom_emoji_id": WE.get("skull", "5440681540541502133"),
            "style": "danger",
        }]]
    }

    status_msg = await message.reply(
        f"{wpe('sparkle')} {_to_bi('Square Bulk Check')} {wpe('sparkle')}\n\n"
        f"{'=' * 30}\n"
        f"{wpe('triple_ring')} {_to_bi('Total:')} {_to_bi(str(total))}\n"
        f"{wpe('amount')} {_to_bi('Price:')} {_to_bi(price_str)} {_to_bi('per card')}\n"
        f"{wpe('arrow_right')} {_to_bi('Proxies:')} {_to_bi(str(len(user_proxy_list)))}\n"
        f"{wpe('arc_reactor')} {_to_bi('Starting...')} {wpe('processing')}\n"
        f"{'=' * 30}\n"
        f"{_to_bi('gate')} : {wpe('sparkle')} {_to_bi('Square')}\n"
        f"{wpe('checked_by')} {_to_bi('Checked by:')} {user_link(user_id, user_name, user_uname)}",
        reply_markup=stop_btn,
    )

    async def _run_msq():
        try:
            await _square_bulk_processor(
                list(all_ccs), user_id, user_name, user_uname,
                chat_id, status_msg, stop_key,
                amount_cents=amount_cents,
                proxy_list=user_proxy_list,
            )
        except Exception as e:
            log.error("[/msq] bulk processor crashed: %s", e, exc_info=True)
            try:
                await safe_edit(status_msg,
                    f"{wpe('skull')} {_to_bi('Square')} {_to_bi('Crashed:')} "
                    f"{_to_bi(str(e)[:80])}")
            except Exception:
                pass
        finally:
            _SQUARE_BULK_ACTIVE.discard(user_id)

    asyncio.create_task(_run_msq())


# STOP callback for /msq bulk
@router.callback_query(F.data.startswith("square_bulk_stop:"))
async def cb_square_bulk_stop(callback: types.CallbackQuery):
    stop_key = callback.data.split(":", 1)[1] if ":" in callback.data else ""
    if not stop_key:
        await safe_callback_answer(callback)
        return
    try:
        clicker_id = callback.from_user.id
        owner_id = int(stop_key.split(":")[-1])
    except (ValueError, IndexError):
        owner_id = 0
        clicker_id = 0
    if clicker_id != owner_id and not auth.is_admin(clicker_id):
        await safe_callback_answer(callback, bold("Not your run!"), show_alert=True)
        return
    _SQUARE_BULK_STOP_FLAGS[stop_key] = True
    try:
        await callback.message.edit_reply_markup(reply_markup=None)
    except Exception:
        pass
    await safe_callback_answer(callback, bold("Stopping..."), show_alert=False)


