# ══════════════════════════════════════════════════════════════════════════════
#  /ban COMMAND — Admin bans user
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("ban"))
async def cmd_ban(message: types.Message):
    # v58 — owner-only: admins can ban via the original numeric path,
    # but the GROUP REPLY + @username path is owner-only so a rogue
    # admin cannot ban people the owner hasn't vetted.  (Admins can
    # still use /ban <user_id>.)
    is_owner_caller = False
    try:
        is_owner_caller = auth.is_owner(message.from_user.id)
    except Exception:
        try:
            is_owner_caller = (getattr(auth, "OWNER_ID", None)
                                == message.from_user.id)
        except Exception:
            is_owner_caller = False
    is_admin_caller = False
    try:
        is_admin_caller = auth.is_admin(message.from_user.id)
    except Exception:
        is_admin_caller = False

    if not (is_owner_caller or is_admin_caller):
        await message.reply(f"{wpe('cross')} {bold('Admin/Owner only command!')}")
        return

    args = message.text.split(maxsplit=1)
    target_id = 0
    target_username = ""

    # ── Method 1: Reply to a message — owner can ban anyone (except self/owner)
    if message.reply_to_message:
        replied = message.reply_to_message
        if replied.from_user is None:
            await message.reply(
                f"{wpe('warn')} {_to_bi('Cannot ban — replied message has no sender.')}"
            )
            return
        target_id = replied.from_user.id
        target_username = replied.from_user.username or ""
        target_name = replied.from_user.full_name or ""
    # ── Method 2: /ban <user_id | @username>
    elif len(args) >= 2:
        raw = args[1].strip().lstrip("@")
        if raw.isdigit():
            target_id = int(raw)
            target_username = ""
            target_name = ""
        else:
            # Treat as a @username — look it up in the in-memory cache.
            target_username = raw.lower()
            target_id = _resolve_username_to_id(target_username)
            target_name = ""
            if target_id == 0:
                # Username was never observed by the bot — Telegram bot API
                # cannot resolve @username → user_id.  Ask the owner to reply
                # to a message of that user instead.
                await message.reply(
                    f"{wpe('warn')} {_to_bi('Cannot resolve @' + target_username + ' — bot has never seen this user.')}\n\n"
                    f"{wpe('arrow_right')} {_to_bi('Reply to a message from the user, then send /ban')}\n"
                    f"{wpe('arrow_right')} {_to_bi('Or use:')} /ban <user_id>"
                )
                return
    else:
        await message.reply(
            f"{wpe('warn')} {bold('Usage:')}\n"
            f"{wpe('arrow_right')} /ban {bold('user-id')}\n"
            f"{wpe('arrow_right')} /ban @username  "
            f"{_to_bi('(if bot has seen them before)')}\n"
            f"{wpe('arrow_right')} {_to_bi('Or reply to a user message with /ban')}"
        )
        return

    if target_id == 0:
        await message.reply(f"{wpe('skull')} {bold('Could not determine target user.')}")
        return

    # ── Owner cannot be banned ────────────────────────────────────────
    if auth.is_owner(target_id):
        await message.reply(f"{wpe('warn')} {bold('Cannot ban the owner.')}")
        return
    if target_id == message.from_user.id:
        await message.reply(f"{wpe('warn')} {bold('You cannot ban yourself.')}")
        return

    # Cache the username (if any) for future lookups.
    if target_username:
        _cache_username(target_username, target_id)

    # Ban in both systems (bot.py local + auth module)
    ban_user(target_id)  # local _banned_users set
    try:
        auth.ban_user(target_id)  # auth module ban
    except Exception:
        pass

    # Try to kick the user from the chat (if we're in a group).
    if message.chat.type in ("group", "supergroup"):
        try:
            await bot.ban_chat_member(message.chat.id, target_id)
        except Exception as _kick_e:
            log.info("Ban: could not kick %s from chat %s: %s",
                     target_id, message.chat.id, _kick_e)

    # Friendly display: @username when known, otherwise the numeric ID.
    if target_username:
        target_display = f"@{target_username}"
    else:
        target_display = str(target_id)

    await message.reply(
        f"{wpe('ban')} {bold('User Banned!')}\n\n"
        f"{wpe('user')} {bold('User:')} {_to_bi(target_display)}\n"
        f"{wpe('triple_ring')} {bold('ID:')} <code>{target_id}</code>"
    )


# ══════════════════════════════════════════════════════════════════════════════
#  /unban COMMAND — Admin/Owner unbans user (reply or @username both work)
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("unban"))
async def cmd_unban(message: types.Message):
    is_owner_caller = False
    try:
        is_owner_caller = auth.is_owner(message.from_user.id)
    except Exception:
        try:
            is_owner_caller = (getattr(auth, "OWNER_ID", None)
                                == message.from_user.id)
        except Exception:
            is_owner_caller = False
    is_admin_caller = False
    try:
        is_admin_caller = auth.is_admin(message.from_user.id)
    except Exception:
        is_admin_caller = False

    if not (is_owner_caller or is_admin_caller):
        await message.reply(f"{wpe('cross')} {bold('Admin/Owner only command!')}")
        return

    args = message.text.split(maxsplit=1)
    target_id = 0
    target_username = ""

    # ── Method 1: Reply to a message
    if message.reply_to_message:
        replied = message.reply_to_message
        if replied.from_user is None:
            await message.reply(
                f"{wpe('warn')} {_to_bi('Cannot unban — replied message has no sender.')}"
            )
            return
        target_id = replied.from_user.id
        target_username = replied.from_user.username or ""
    # ── Method 2: /unban <user_id | @username>
    elif len(args) >= 2:
        raw = args[1].strip().lstrip("@")
        if raw.isdigit():
            target_id = int(raw)
            target_username = ""
        else:
            target_username = raw.lower()
            target_id = _resolve_username_to_id(target_username)
            if target_id == 0:
                await message.reply(
                    f"{wpe('warn')} {_to_bi('Cannot resolve @' + target_username + ' — bot has never seen this user.')}\n\n"
                    f"{wpe('arrow_right')} {_to_bi('Reply to a message from the user, then send /unban')}\n"
                    f"{wpe('arrow_right')} {_to_bi('Or use:')} /unban <user_id>"
                )
                return
    else:
        await message.reply(
            f"{wpe('warn')} {bold('Usage:')}\n"
            f"{wpe('arrow_right')} /unban {bold('user-id')}\n"
            f"{wpe('arrow_right')} /unban @username  "
            f"{_to_bi('(if bot has seen them before)')}\n"
            f"{wpe('arrow_right')} {_to_bi('Or reply to a user message with /unban')}"
        )
        return

    if target_id == 0:
        await message.reply(f"{wpe('skull')} {bold('Could not determine target user.')}")
        return

    # Cache the username for future lookups.
    if target_username:
        _cache_username(target_username, target_id)

    # Check both ban systems (bot.py _banned_users + auth module)
    is_in_local = target_id in _banned_users
    is_in_auth = False
    try:
        is_in_auth = auth.is_banned(target_id)
    except Exception:
        pass

    if not is_in_local and not is_in_auth:
        await message.reply(f"{wpe('warn')} {bold('User is not banned.')}")
        return

    # Remove from both ban systems
    if is_in_local:
        unban_user(target_id)
    if is_in_auth:
        try:
            auth.unban_user(target_id)
        except Exception:
            pass

    # Try to unban from the chat (group/supergroup).
    if message.chat.type in ("group", "supergroup"):
        try:
            await bot.unban_chat_member(message.chat.id, target_id)
        except Exception as _unkick_e:
            log.info("Unban: could not unban %s from chat %s: %s",
                     target_id, message.chat.id, _unkick_e)

    if target_username:
        target_display = f"@{target_username}"
    else:
        target_display = str(target_id)

    await message.reply(
        f"{wpe('check')} {bold('User Unbanned!')}\n\n"
        f"{wpe('user')} {bold('User:')} {_to_bi(target_display)}\n"
        f"{wpe('triple_ring')} {bold('ID:')} <code>{target_id}</code>"
    )


# ══════════════════════════════════════════════════════════════════════════════
#  /key COMMAND — Admin generates premium keys
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("key"))
async def cmd_key(message: types.Message):
    if not auth.is_admin(message.from_user.id):
        await message.reply(f"{pe(E['cross'])} {bold('Admin only command!')}")
        return

    args = message.text.split()
    if len(args) < 3 or not args[1].isdigit() or not args[2].isdigit():
        await message.reply(
            f"{pe(E['warn'])} {bold('Usage:')} /key {bold('users')} {bold('days')}\n\n"
            f"{pe(E['next'])} {bold('Example:')} /key 10 1\n"
            f"{pe(E['next'])} {bold('Generates 1 key — 10 users can redeem, 1 day each')}"
        )
        return

    max_users = int(args[1])
    days = int(args[2])

    if max_users < 1 or max_users > 1000:
        await message.reply(f"{pe(E['cross'])} {bold('Users must be 1-1000')}")
        return

    try:
        keys = await asyncio.to_thread(auth.generate_keys, max_users, days, message.from_user.id)
        key = keys[0]
    except Exception as e:
        log.error("generate_keys failed: %s", e)
        await message.reply(f"{pe(E['cross'])} {bold('Failed to generate key:')} {str(e)[:100]}")
        return

    text = (
        f"{pe(E['gem'])} {bold('𝙆𝙚𝙮 𝙂𝙚𝙣𝙚𝙧𝙖𝙩𝙚𝙙')} {pe(E['check'])}\n"
        f"━━━━━━━━━━━━━━━━━━━━\n\n"
        f"┣ {pe(E['bolt'])} {bold('𝗞𝗲𝘆')} ➜ <code>{key}</code>\n"
        f"┣ {pe(E['user'])} {bold('𝗦𝗹𝗼𝘁𝘀')} ➜ {bold(str(max_users))} {bold('users can redeem')}\n"
        f"┣ {pe(E['star'])} {bold('𝗣𝗹𝗮𝗻')} ➜ {bold(str(days))} {bold('days each')}\n\n"
        f"{pe(E['sparkle'])} {bold('𝗨𝘀𝗲𝗿𝘀 𝗿𝗲𝗱𝗲𝗲𝗺 𝘄𝗶𝘁𝗵')} /redeem {key} {pe(E['bolt'])}"
    )
    await message.reply(text)


