# ══════════════════════════════════════════════════════════════════════════════
#  /nopecha COMMAND — Set / view / clear NopeCHA API key (per-user, optional)
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("nopecha"))
async def cmd_nopecha(message: types.Message):
    """
    /nopecha              — show current key status
    /nopecha <key>        — validate & save key
    /nopecha set <key>    — validate & save key (alias)
    /nopecha clear        — remove saved key
    """
    user_id = message.from_user.id

    if auth.is_banned(user_id):
        return

    args_text = (message.text or "").split(maxsplit=1)
    arg = args_text[1].strip() if len(args_text) >= 2 else ""

    # ── CLEAR ──
    if arg.lower() == "clear":
        auth.set_nopecha_key(user_id, "")
        await message.reply(
            f"{pe(E['check'])} {bold('NopeCHA key cleared.')}\n\n"
            f"{pe(E['warn'])} {bold('Captcha auto-solve is now disabled.')}\n"
            f"{pe(E['next'])} {bold('Use')} /nopecha {bold('<api_key>')} {bold('to add one.')}"
        )
        return

    # ── SHOW STATUS ──
    if not arg or arg.lower() == "status":
        existing = auth.get_nopecha_key(user_id)
        if not existing:
            await message.reply(
                f"{pe(E['warn2'])} {bold('No NopeCHA API key set.')}\n\n"
                f"{pe(E['next'])} {bold('To enable auto captcha solving:')}\n"
                f"{pe(E['bolt'])} /nopecha {bold('<your_api_key>')}\n\n"
                f"{pe(E['link'])} {bold('Get your key at:')} nopecha.com"
            )
        else:
            masked = existing[:6] + "..." + existing[-4:] if len(existing) > 10 else "****"
            await message.reply(
                f"{pe(E['check'])} {bold('NopeCHA key is set.')}\n\n"
                f"{pe(E['bolt'])} {bold('Key:')} {bold(masked)}\n"
                f"{pe(E['sparkle'])} {bold('hCaptcha will be auto-solved when triggered.')}\n\n"
                f"{pe(E['next'])} {bold('To remove:')} /nopecha clear"
            )
        return

    # ── SET KEY (strip optional "set " prefix) ──
    key = arg[4:].strip() if arg.lower().startswith("set ") else arg

    if not key:
        await message.reply(
            f"{pe(E['warn'])} {bold('Usage:')} /nopecha {bold('<api_key>')}"
        )
        return

    # Validate key against NopeCHA status endpoint
    validating_msg = await message.reply(
        f"{pe(E['loading'])} {bold('Validating NopeCHA key...')}"
    )
    try:
        async with httpx.AsyncClient(timeout=10) as client:
            resp = await client.get(
                "https://api.nopecha.com/v1/status",
                headers={"Authorization": f"Basic {key}"},
            )
        if resp.status_code == 401:
            await safe_edit(validating_msg, 
                f"{pe(E['cross'])} {bold('Invalid API key.')}\n\n"
                f"{pe(E['warn'])} {bold('NopeCHA rejected this key. Please check and try again.')}"
            )
            return
        if resp.status_code == 403:
            await safe_edit(validating_msg, 
                f"{pe(E['cross'])} {bold('Access denied.')}\n\n"
                f"{pe(E['warn'])} {bold('NopeCHA returned 403. IP may be banned or key suspended.')}"
            )
            return
        resp.raise_for_status()
        data    = resp.json()
        status  = (data.get("status") or "").strip()
        plan    = data.get("plan") or "Unknown"
        credit  = data.get("credit") or data.get("credits") or 0
    except httpx.HTTPStatusError as e:
        await safe_edit(validating_msg, 
            f"{pe(E['cross'])} {bold('Validation failed.')}\n\n"
            f"{pe(E['warn'])} {bold(f'HTTP {e.response.status_code}')}"
        )
        return
    except Exception as e:
        await safe_edit(validating_msg, 
            f"{pe(E['cross'])} {bold('Could not reach NopeCHA.')}\n\n"
            f"{pe(E['warn'])} {bold(str(e)[:80])}"
        )
        return

    if status.lower() not in ("active", "ok", "valid", ""):
        await safe_edit(validating_msg, 
            f"{pe(E['cross2'])} {bold('Key not active.')}\n\n"
            f"{pe(E['warn'])} {bold('Status:')} {bold(status)}\n"
            f"{pe(E['next'])} {bold('Please renew your NopeCHA plan.')}"
        )
        return

    # Key is valid — save it
    auth.set_nopecha_key(user_id, key)
    masked = key[:6] + "..." + key[-4:] if len(key) > 10 else "****"
    await safe_edit(validating_msg, 
        f"{pe(E['gem'])} {bold('NopeCHA Key Saved!')} {pe(E['gem'])}\n\n"
        f"{pe(E['check'])} {bold('Key:')} {bold(masked)}\n"
        f"{pe(E['bolt'])} {bold('Plan:')} {bold(str(plan))}\n"
        f"{pe(E['bank'])} {bold('Credits:')} {bold(str(credit))}\n\n"
        f"{pe(E['sparkle'])} {bold('hCaptcha will now be auto-solved during /hit checks.')}\n"
        f"{pe(E['next'])} {bold('To remove:')} /nopecha clear"
    )


# ══════════════════════════════════════════════════════════════════════════════
#  /ayd COMMAND — Adyen payment link checker (max 10 CCs)
# ══════════════════════════════════════════════════════════════════════════════

AYD_MAX_CCS = 10
_AYD_EDIT_LOCKS: dict[int, asyncio.Lock] = {}
_AYD_STOP_FLAGS: dict[str, bool] = {}
_AYD_ACTIVE_USERS: set[int] = set()

PROXY_MAX_RETRIES = 3


def _ayd_status_line(result: dict) -> str:
    """Map Adyen result to a styled status line."""
    err = result.get("error") or ""
    status = (result.get("payment_status") or "").lower()
    err_lower = err.lower()

    if status == "authorised" or status == "received":
        return f"{pe(E['gem'])} {bold('Charged / Success!')}"
    if "insufficient" in status or "insufficient" in err_lower:
        return f"{pe(E['check2'])} {bold('Insufficient Funds')}"
    if "cvc" in status or "cvc" in err_lower:
        return f"{pe(E['check3'])} {bold('Incorrect CVC — Live')}"
    if status == "refused" or "declined" in status or "declined" in err_lower:
        return f"{pe(E['cross'])} {bold('Declined')}"
    if "expired" in err_lower or "not active" in err_lower:
        return f"{pe(E['cross2'])} {bold('Checkout Expired')}"
    if "3ds" in err_lower or "challenge" in err_lower:
        return f"{pe(E['check'])} {bold('3DS Challenge')}"
    if err:
        return f"{pe(E['warn2'])} {bold(err[:60])}"
    if status:
        return f"{pe(E['warn2'])} {bold(status[:60])}"
    return f"{pe(E['warn2'])} {bold('Unknown')}"


def _ayd_raw_response(result: dict) -> str:
    """Extract the original Adyen response string."""
    return result.get("payment_status") or result.get("error") or "Unknown"


def _ayd_cc_block(cc: str, result: dict) -> str:
    sl = _ayd_status_line(result)
    raw = _ayd_raw_response(result)
    tds_line = f"\n{pe(E['bolt'])} {bold('3D Bypassed')}" if result.get("3d_bypassed") else ""
    return (
        f"{sl}\n"
        f"{pe(R['cc'])} {bold('CC:')} <tg-spoiler>{cc}</tg-spoiler>\n"
        f"{pe(R['gate'])} {bold('Response:')} {bold(raw)}"
        f"{tds_line}"
    )


def _is_checkout_expired(result: dict) -> bool:
    err = (result.get("error") or "").lower()
    return "not active" in err or "expired" in err


def _is_success(result: dict) -> bool:
    status = (result.get("payment_status") or "").lower()
    return status in ("authorised", "received")


async def _ayd_check_single(
    cc_str: str, link: str, user_id: int,
    status_msg: types.Message, results: dict, order: list,
    user_name: str, user_uname: str, stop_key: str,
    checkout_info: dict,
):
    if _AYD_STOP_FLAGS.get(stop_key):
        results[cc_str] = {"error": "Stopped", "cc": cc_str}
        return

    proxies = get_user_proxies(user_id)

    if not proxies:

        proxies = _global_fallback_proxy_dicts()
    last_result = None

    for attempt in range(PROXY_MAX_RETRIES):
        if _AYD_STOP_FLAGS.get(stop_key):
            results[cc_str] = {"error": "Stopped", "cc": cc_str}
            return

        proxy_data = random.choice(proxies) if proxies else None
        # v32 — fresh SID per Adyen retry (no-op on non-SID proxies).
        if proxy_data:
            try:
                proxy_data = _rotate_proxy_dict_sid(proxy_data)
            except Exception:
                pass
        try:
            last_result = await ayden.process_payment(link, cc_str, proxy_data)
            if last_result.get("error") and "proxy" in last_result["error"].lower():
                continue
            break
        except Exception as e:
            last_result = {"error": str(e)[:80], "cc": cc_str}
            continue

    results[cc_str] = last_result or {"error": "All proxy retries failed", "cc": cc_str}

    if _is_checkout_expired(results[cc_str]):
        _AYD_STOP_FLAGS[stop_key] = True

    # ── Update the shared message ──
    msg_id = status_msg.message_id
    if msg_id not in _AYD_EDIT_LOCKS:
        _AYD_EDIT_LOCKS[msg_id] = asyncio.Lock()

    async with _AYD_EDIT_LOCKS[msg_id]:
        done_count = sum(1 for cc in order if cc in results)
        total = len(order)

        header = (
            f"{pe(E['gem'])} {bold('Adyen Hitter')} [{bold(str(done_count))}/{bold(str(total))}]\n\n"
            f"{pe(E['bolt'])} {bold('Merchant:')} {bold(checkout_info.get('merchant', '-'))}\n"
            f"{pe(E['star'])} {bold('Product:')} {bold(checkout_info.get('product', '-'))}\n"
            f"{pe(E['bank'])} {bold('Amount:')} {bold(checkout_info.get('amount_str', '-'))}\n"
            f"{pe(E['link'])} {bold('Link:')} {bold(checkout_info.get('link_short', '-'))}\n"
            f"{pe(E['globe'])} {bold('URL:')} {bold(checkout_info.get('return_url', '-'))}\n"
        )

        lines = [header]
        for cc in order:
            if cc in results:
                lines.append(_ayd_cc_block(cc, results[cc]))
            else:
                lines.append(
                    f"{pe(E['loading'])} <tg-spoiler>{cc}</tg-spoiler> {bold('checking...')}"
                )

        if _AYD_STOP_FLAGS.get(stop_key) and _is_checkout_expired(results.get(cc_str, {})):
            lines.append(f"\n{pe(E['cross2'])} {bold('Checkout expired — stopped.')}")

        lines.append(f"\n{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}")

        if _mass_edit_due(msg_id, done_count, total):
            try:
                await safe_edit(status_msg, "\n\n".join(lines))
            except Exception:
                pass

    if sum(1 for cc in order if cc in results) == len(order):
        _AYD_EDIT_LOCKS.pop(msg_id, None)


@router.message(Command("ayd"))
async def cmd_ayd(message: types.Message):
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return

    user_id = message.from_user.id

    if auth.is_banned(user_id):
        return

    if not auth.has_premium_access(user_id, message.chat.id):
        await message.reply(
            f"{pe(E['cross'])} {bold('Premium Access Required!')}"
            f"\n\n{pe(E['bolt'])} {bold('Contact admin or redeem a key: @tatsuyo_001')}"
            f"\n{pe(E['next'])} /redeem {bold('Tatsuyo-xxxxx')}"
        )
        return

    if user_id in _AYD_ACTIVE_USERS:
        await message.reply(
            f"{pe(E['warn'])} {bold('Your Adyen check is already in progress!')}\n\n"
            f"{pe(E['next'])} {bold('Wait for it to complete or tap')} {bold('Stop')} {bold('first.')}"
        )
        return

    # ── Extract link + CCs ──
    raw_text = ""
    args = message.text.split(maxsplit=1)
    if len(args) >= 2:
        raw_text = args[1]

    if message.reply_to_message:
        reply_text = message.reply_to_message.text or message.reply_to_message.caption or ""
        raw_text = raw_text + "\n" + reply_text if raw_text else reply_text

    if not raw_text.strip():
        await message.reply(
            f"{pe(E['warn'])} {bold('Usage:')}\n\n"
            f"{pe(E['next'])} /ayd https://eu.adyen.link/...\n"
            f"cc|mm|yy|cvv\n"
            f"cc|mm|yy|cvv\n\n"
            f"{pe(E['bolt'])} {bold('Max')} {bold(str(AYD_MAX_CCS))} {bold('CCs per check.')}"
        )
        return

    # ── Find Adyen link ──
    link_match = re.search(r'https?://[^\s]+adyen[^\s]+', raw_text, re.IGNORECASE)
    if not link_match:
        await message.reply(
            f"{pe(E['cross'])} {bold('No Adyen link found!')}\n\n"
            f"{pe(E['next'])} {bold('Paste a valid Adyen checkout link.')}"
        )
        return
    adyen_link = link_match.group(0)

    # ── Find CCs ──
    from helpers import CC_PATTERN
    all_ccs = _DedupeList()
    for m in CC_PATTERN.finditer(raw_text):
        cc = f"{m.group(1)}|{m.group(2)}|{m.group(3)}|{m.group(4)}"
        if cc not in all_ccs:
            all_ccs.append(cc)

    if not all_ccs:
        for line in raw_text.strip().splitlines():
            line = line.strip()
            parts = re.split(r'[|/]', line)
            if len(parts) >= 4:
                num = parts[0].strip()
                if num.isdigit() and len(num) >= 13:
                    cc = "|".join(p.strip() for p in parts[:4])
                    if cc not in all_ccs:
                        all_ccs.append(cc)

    if not all_ccs:
        await message.reply(
            f"{pe(E['cross'])} {bold('No valid CCs found!')}\n\n"
            f"{pe(E['next'])} {bold('Format:')} cc|mm|yy|cvv"
        )
        return

    skipped = 0
    if len(all_ccs) > AYD_MAX_CCS:
        skipped = len(all_ccs) - AYD_MAX_CCS
        all_ccs = all_ccs[:AYD_MAX_CCS]

    # ── Check proxy ──
    proxies = get_user_proxies(user_id)
    if not proxies:
        proxies = _global_fallback_proxy_dicts()
    if not proxies:
        await message.reply(
            f"{pe(E['cross'])} {bold('No Proxy Set!')}\n\n"
            f"{pe(E['warn'])} {bold('You must add a proxy before checking.')}\n"
            f"{pe(E['next'])} {bold('Use:')} /proxy host:port:user:pass"
        )
        return

    user_name = message.from_user.full_name or ""
    user_uname = message.from_user.username or ""
    total = len(all_ccs)
    chat_id = message.chat.id
    stop_key = f"ayd:{chat_id}:{user_id}"
    _AYD_STOP_FLAGS[stop_key] = False
    _AYD_ACTIVE_USERS.add(user_id)

    link_short = adyen_link.split("/")[-1][:20] + "..."

    # ── Fetch checkout info with first proxy ──
    loading_msg = await message.reply(
        f"{pe(E['loading'])} {bold('Loading Adyen checkout...')}\n\n"
        f"{pe(E['link'])} {bold(adyen_link)}"
    )

    try:
        proxy_data = random.choice(proxies)
        # v32 — fresh SID for the very first session-loading request too
        # (no-op on non-SID proxies).
        if proxy_data:
            try:
                proxy_data = _rotate_proxy_dict_sid(proxy_data)
            except Exception:
                pass
        setup_result = await ayden.process_payment(adyen_link, all_ccs[0], proxy_data)
    except Exception as e:
        _AYD_ACTIVE_USERS.discard(user_id)
        _AYD_STOP_FLAGS.pop(stop_key, None)
        await safe_edit(loading_msg, 
            f"{pe(E['cross'])} {bold('Failed to load checkout!')}\n\n"
            f"{pe(E['warn'])} {bold(str(e)[:100])}"
        )
        return

    if _is_checkout_expired(setup_result):
        _AYD_ACTIVE_USERS.discard(user_id)
        _AYD_STOP_FLAGS.pop(stop_key, None)
        await safe_edit(loading_msg, 
            f"{pe(E['cross2'])} {bold('Checkout Expired!')}\n\n"
            f"{pe(E['warn'])} {bold('This Adyen link is no longer active.')}"
        )
        return

    merchant = setup_result.get("merchant_name") or "-"
    product = setup_result.get("product_name") or "-"
    return_url = setup_result.get("return_url") or "-"
    amount_val = setup_result.get("amount")
    currency = setup_result.get("currency") or ""
    if amount_val is not None:
        amount_str = f"{currency} {amount_val / 100:.2f}" if amount_val > 100 else f"{currency} {amount_val}"
    else:
        amount_str = "-"

    checkout_info = {
        "merchant": merchant,
        "product": product,
        "amount_str": amount_str,
        "link_short": link_short,
        "return_url": return_url,
    }

    # First CC already checked
    results: dict = {all_ccs[0]: setup_result}
    order = list(all_ccs)

    # ── Build initial status message ──
    header = (
        f"{pe(E['gem'])} {bold('Adyen Hitter')} [{bold('1')}/{bold(str(total))}]\n\n"
        f"{pe(E['bolt'])} {bold('Merchant:')} {bold(merchant)}\n"
        f"{pe(E['star'])} {bold('Product:')} {bold(product)}\n"
        f"{pe(E['bank'])} {bold('Amount:')} {bold(amount_str)}\n"
        f"{pe(E['link'])} {bold('Link:')} {bold(link_short)}\n"
        f"{pe(E['globe'])} {bold('URL:')} {bold(return_url)}\n"
    )

    init_lines = [header]
    init_lines.append(_ayd_cc_block(all_ccs[0], setup_result))
    for cc in all_ccs[1:]:
        init_lines.append(f"{pe(E['loading'])} <tg-spoiler>{cc}</tg-spoiler> {bold('checking...')}")

    if skipped > 0:
        init_lines.append(f"\n{pe(E['warn'])} {bold(str(skipped))} {bold('CCs skipped (max')} {bold(str(AYD_MAX_CCS))}{bold(')')}")

    init_lines.append(f"\n{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}")

    stop_btn = {
        "inline_keyboard": [[{
            "text": f"{bold('Stop Checking')}",
            "callback_data": f"ayd_stop:{stop_key}",
            "icon_custom_emoji_id": E["stop"],
        }]]
    }

    try:
        await safe_edit(loading_msg, "\n\n".join(init_lines), reply_markup=stop_btn)
    except Exception:
        pass

    status_msg = loading_msg

    # ── Send success to monitor if first CC hit ──
    if _is_success(setup_result):
        auth.save_charged_cc(all_ccs[0], user_id, user_name, "Adyen", amount_str)
        try:
            hit_text = (
                f"{pe(E['gem'])} {bold('Adyen Hit!')} {pe(E['gem'])}\n\n"
                f"{pe(R['cc'])} {bold('CC:')} <tg-spoiler>{all_ccs[0]}</tg-spoiler>\n"
                f"{pe(E['bolt'])} {bold('Merchant:')} {bold(merchant)}\n"
                f"{pe(E['bank'])} {bold('Amount:')} {bold(amount_str)}\n\n"
                f"{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}"
            )
            await _send_charged_group(user_id, hit_text)
        except Exception:
            pass

    # ── If checkout already expired on first CC, stop ──
    if _is_checkout_expired(setup_result):
        _AYD_ACTIVE_USERS.discard(user_id)
        _AYD_STOP_FLAGS.pop(stop_key, None)
        return

    # ── Process remaining CCs one by one (sequential for same link) ──
    try:
        for cc in all_ccs[1:]:
            if _AYD_STOP_FLAGS.get(stop_key):
                results[cc] = {"error": "Stopped", "cc": cc}
                continue

            await _ayd_check_single(
                cc, adyen_link, user_id, status_msg, results, order,
                user_name, user_uname, stop_key, checkout_info,
            )

            if _is_success(results.get(cc, {})):
                auth.save_charged_cc(cc, user_id, user_name, "Adyen", amount_str)
                try:
                    hit_text = (
                        f"{pe(E['gem'])} {bold('Adyen Hit!')} {pe(E['gem'])}\n\n"
                        f"{pe(R['cc'])} {bold('CC:')} <tg-spoiler>{cc}</tg-spoiler>\n"
                        f"{pe(E['bolt'])} {bold('Merchant:')} {bold(merchant)}\n"
                        f"{pe(E['bank'])} {bold('Amount:')} {bold(amount_str)}\n\n"
                        f"{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}"
                    )
                    await _send_charged_group(user_id, hit_text)
                except Exception:
                    pass

            if _AYD_STOP_FLAGS.get(stop_key):
                for remaining_cc in all_ccs[all_ccs.index(cc) + 1:]:
                    if remaining_cc not in results:
                        results[remaining_cc] = {"error": "Stopped (checkout expired)", "cc": remaining_cc}
                break

        # ── Final update (remove stop button) ──
        done_count = sum(1 for cc in order if cc in results)
        final_lines = [
            f"{pe(E['gem'])} {bold('Adyen Hitter')} [{bold(str(done_count))}/{bold(str(total))}]\n\n"
            f"{pe(E['bolt'])} {bold('Merchant:')} {bold(merchant)}\n"
            f"{pe(E['star'])} {bold('Product:')} {bold(product)}\n"
            f"{pe(E['bank'])} {bold('Amount:')} {bold(amount_str)}\n"
            f"{pe(E['link'])} {bold('Link:')} {bold(link_short)}\n"
            f"{pe(E['globe'])} {bold('URL:')} {bold(return_url)}\n"
        ]
        for cc in order:
            if cc in results:
                final_lines.append(_ayd_cc_block(cc, results[cc]))
        if skipped > 0:
            final_lines.append(f"\n{pe(E['warn'])} {bold(str(skipped))} {bold('CCs skipped (max')} {bold(str(AYD_MAX_CCS))}{bold(')')}")

        expired_any = any(_is_checkout_expired(results.get(cc, {})) for cc in order)
        if expired_any:
            final_lines.append(f"\n{pe(E['cross2'])} {bold('Checkout expired — stopped.')}")

        final_lines.append(f"\n{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}")

        try:
            await safe_edit(status_msg, "\n\n".join(final_lines))
        except Exception:
            pass

        # Pin if any success
        if any(_is_success(results.get(cc, {})) for cc in order):
            try:
                await bot.pin_chat_message(message.chat.id, status_msg.message_id, disable_notification=True)
            except Exception:
                pass

    finally:
        _AYD_ACTIVE_USERS.discard(user_id)
        _AYD_STOP_FLAGS.pop(stop_key, None)


@router.callback_query(F.data.startswith("ayd_stop:"))
async def cb_ayd_stop(callback: types.CallbackQuery):
    stop_key = callback.data.split(":", 1)[1]
    parts = stop_key.split(":")
    if len(parts) >= 3:
        owner_id = int(parts[2])
    else:
        owner_id = 0

    if callback.from_user.id != owner_id and not auth.is_owner(callback.from_user.id):
        await safe_callback_answer(callback, bold("Only the owner can stop this check!"), show_alert=True)
        return

    _AYD_STOP_FLAGS[stop_key] = True
    await safe_callback_answer(callback, bold("Stopping Adyen check..."), show_alert=True)


# ══════════════════════════════════════════════════════════════════════════════
#  /hit COMMAND — Stripe checkout autohitter (max 10 CCs)
# ══════════════════════════════════════════════════════════════════════════════

HIT_MAX_CCS = 10
_HIT_EDIT_LOCKS: dict[int, asyncio.Lock] = {}
_HIT_STOP_FLAGS: dict[str, bool] = {}
_HIT_ACTIVE_USERS: set[int] = set()



def _hit_is_payment_success(result: dict) -> bool:
    """True when hit.php reports a successful charge (status or response text)."""
    if not result.get("ok"):
        return False
    status = (result.get("result_status") or "").lower()
    if status in ("charge", "charged"):
        return True
    msg = (result.get("result_msg") or "").lower()
    return any(x in msg for x in ("payment successful", "succeeded", " paid"))


def _hit_status_line(result: dict) -> str:
    """Map Stripe hit result to a styled status line."""
    if not result.get("ok"):
        err = result.get("error") or ""
        if result.get("session_dead"):
            return f"{pe(E['cross2'])} {bold('Session Dead')}"
        return f"{pe(E['warn2'])} {bold(err[:60])}"

    if result.get("hcaptcha"):
        return f"{pe(E['warn2'])} {bold('hCaptcha Required')}"

    status = result.get("result_status", "")
    msg = result.get("result_msg", "")

    if _hit_is_payment_success(result):
        return f"{pe(E['gem'])} {bold('Charged / Success!')}"
    if status in ("live", "approved"):
        msg_lower = msg.lower()
        if "insufficient" in msg_lower:
            return f"{pe(E['check2'])} {bold('Insufficient Funds')}"
        if "cvc" in msg_lower:
            return f"{pe(E['check3'])} {bold('Incorrect CVC — Live')}"
        return f"{pe(E['check'])} {bold('Live — ' + msg)}"
    return f"{pe(E['cross'])} {bold('Declined')}"


def _hit_raw_response(result: dict) -> str:
    if not result.get("ok"):
        return result.get("error") or "Failed"
    return result.get("result_msg") or "Unknown"


def _hit_cc_block(cc: str, result: dict) -> str:
    sl = _hit_status_line(result)
    raw = _hit_raw_response(result)
    tds_line = f"\n{pe(E['bolt'])} {bold('3D Bypassed')}" if result.get("tds_bypassed") else ""
    return (
        f"{sl}\n"
        f"{pe(R['cc'])} {bold('CC:')} <tg-spoiler>{cc}</tg-spoiler>\n"
        f"{pe(R['gate'])} {bold('Response:')} {bold(raw)}"
        f"{tds_line}"
    )


def _hit_is_session_dead(result: dict) -> bool:
    return bool(result.get("session_dead"))


def _hit_is_success(result: dict) -> bool:
    return _hit_is_payment_success(result)


def _hit_is_live(result: dict) -> bool:
    return (
        result.get("ok", False)
        and result.get("result_status") in ("live", "approved")
        and not _hit_is_payment_success(result)
    )


async def _hit_check_single(
    cc_str: str, checkout_url: str, user_id: int,
    status_msg: types.Message, results: dict, order: list,
    user_name: str, user_uname: str, stop_key: str,
    checkout_info: dict,
    nopecha_key: str = "",
):
    if _HIT_STOP_FLAGS.get(stop_key):
        results[cc_str] = {"ok": False, "error": "Stopped"}
        return

    proxies = get_user_proxies(user_id)

    if not proxies:

        proxies = _global_fallback_proxy_dicts()
    proxy_data = random.choice(proxies) if proxies else None
    # v32 — fresh SID per Hit check (no-op on non-SID proxies).
    if proxy_data:
        try:
            proxy_data = _rotate_proxy_dict_sid(proxy_data)
        except Exception:
            pass

    sem = get_user_semaphore(user_id)
    async with sem:
        try:
            result = await asyncio.get_running_loop().run_in_executor(
                CHECKER_POOL, hit.run_hit_check, checkout_url, cc_str, proxy_data, 3, nopecha_key,
            )
        except Exception as e:
            result = {"ok": False, "error": str(e)[:80]}

    msg_id = status_msg.message_id
    if msg_id not in _HIT_EDIT_LOCKS:
        _HIT_EDIT_LOCKS[msg_id] = asyncio.Lock()

    results[cc_str] = result

    if _hit_is_session_dead(result):
        _HIT_STOP_FLAGS[stop_key] = True

    # ── Update shared message ──
    async def _do_edit():
        async with _HIT_EDIT_LOCKS[msg_id]:
            done_count = sum(1 for cc in order if cc in results)
            total = len(order)
            header = (
                f"{pe(E['gem'])} {bold('Stripe Checker')} [{bold(str(done_count))}/{bold(str(total))}]\n\n"
                f"{pe(E['bolt'])} {bold('Merchant:')} {bold(checkout_info.get('merchant', '-'))}\n"
                f"{pe(E['star'])} {bold('Product:')} {bold(checkout_info.get('product', '-'))}\n"
                f"{pe(E['bank'])} {bold('Amount:')} {bold(checkout_info.get('amount_str', '-'))}\n"
                f"{pe(E['link'])} {bold('Link:')} {bold(checkout_info.get('link_short', '-'))}\n"
                f"{pe(E['globe'])} {bold('URL:')} {bold(checkout_info.get('success_url', '-'))}\n"
            )
            lines = [header]
            for cc in order:
                if cc in results:
                    lines.append(_hit_cc_block(cc, results[cc]))
                else:
                    lines.append(
                        f"{pe(E['loading'])} <tg-spoiler>{cc}</tg-spoiler> {bold('checking...')}"
                    )
            if _HIT_STOP_FLAGS.get(stop_key) and _hit_is_session_dead(results.get(cc_str, {})):
                lines.append(f"\n{pe(E['cross2'])} {bold('Session dead — stopped.')}")
            lines.append(f"\n{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}")
            if _mass_edit_due(msg_id, done_count, total):
                try:
                    await safe_edit(status_msg, "\n\n".join(lines))
                except Exception:
                    pass

    await _do_edit()

    if sum(1 for cc in order if cc in results) == len(order):
        _HIT_EDIT_LOCKS.pop(msg_id, None)


@router.message(Command("hit"))
async def cmd_hit(message: types.Message):
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return

    user_id = message.from_user.id

    if auth.is_banned(user_id):
        return

    # Owner only — no admin, no premium, nobody else
    if not auth.is_owner(user_id):
        await message.reply(
            f"{pe(E['cross'])} {bold('Owner only command')}"
        )
        return

    if user_id in _HIT_ACTIVE_USERS:
        await message.reply(
            f"{pe(E['warn'])} {bold('Your Stripe check is already in progress!')}\n\n"
            f"{pe(E['next'])} {bold('Wait for it to complete or tap')} {bold('Stop')} {bold('first.')}"
        )
        return

    # ── Extract link + CCs ──
    raw_text = ""
    args = message.text.split(maxsplit=1)
    if len(args) >= 2:
        raw_text = args[1]

    if message.reply_to_message:
        reply_text = message.reply_to_message.text or message.reply_to_message.caption or ""
        raw_text = raw_text + "\n" + reply_text if raw_text else reply_text

    if not raw_text.strip():
        await message.reply(
            f"{pe(E['warn'])} {bold('Usage:')}\n\n"
            f"{pe(E['next'])} /hit <Stripe URL>\n"
            f"cc|mm|yy|cvv\n\n"
            f"{pe(E['bolt'])} {bold('Supported links:')}\n"
            f"• checkout.stripe.com/c/pay/...\n"
            f"• billing.stripe.com/p/session/...\n"
            f"• invoice.stripe.com/i/...\n"
            f"• Custom domain with cs_live_...\n\n"
            f"{pe(E['bolt'])} {bold('Max')} {bold(str(HIT_MAX_CCS))} {bold('CCs per check.')}"
        )
        return

    # ── Find Stripe link (checkout / billing portal / invoice / payment link / custom domain) ──
    link_match = re.search(
        r'https?://[^\s]*(?:'
        r'checkout\.stripe\.com'
        r'|billing\.stripe\.com'
        r'|invoice\.stripe\.com'
        r'|payment\.stripe\.com'
        r'|pay\.stripe\.com'
        r'|cs_(?:live|test)_'
        r'|plink_(?:live|test)_'
        r')[^\s]*',
        raw_text, re.IGNORECASE,
    )
    if not link_match:
        await message.reply(
            f"{pe(E['cross'])} {bold('No Stripe link found!')}\n\n"
            f"{pe(E['next'])} {bold('Supported URLs:')}\n"
            f"• checkout.stripe.com/c/pay/...\n"
            f"• billing.stripe.com/p/session/...\n"
            f"• invoice.stripe.com/i/...\n"
            f"• Custom domain with cs_live_... or plink_live_..."
        )
        return
    checkout_url = link_match.group(0)

    # ── Find CCs ──
    from helpers import CC_PATTERN
    all_ccs = _DedupeList()
    for m in CC_PATTERN.finditer(raw_text):
        cc = f"{m.group(1)}|{m.group(2)}|{m.group(3)}|{m.group(4)}"
        if cc not in all_ccs:
            all_ccs.append(cc)

    if not all_ccs:
        for line in raw_text.strip().splitlines():
            line = line.strip()
            parts = re.split(r'[|/]', line)
            if len(parts) >= 4:
                num = parts[0].strip()
                if num.isdigit() and len(num) >= 13:
                    cc = "|".join(p.strip() for p in parts[:4])
                    if cc not in all_ccs:
                        all_ccs.append(cc)

    if not all_ccs:
        await message.reply(
            f"{pe(E['cross'])} {bold('No valid CCs found!')}\n\n"
            f"{pe(E['next'])} {bold('Format:')} cc|mm|yy|cvv"
        )
        return

    skipped = 0
    if len(all_ccs) > HIT_MAX_CCS:
        skipped = len(all_ccs) - HIT_MAX_CCS
        all_ccs = all_ccs[:HIT_MAX_CCS]

    # ── Check proxy ──
    proxies = get_user_proxies(user_id)
    if not proxies:
        proxies = _global_fallback_proxy_dicts()
    if not proxies:
        await message.reply(
            f"{pe(E['cross'])} {bold('No Proxy Set!')}\n\n"
            f"{pe(E['warn'])} {bold('You must add a proxy before checking.')}\n"
            f"{pe(E['next'])} {bold('Use:')} /proxy host:port:user:pass"
        )
        return

    user_name = message.from_user.full_name or ""
    user_uname = message.from_user.username or ""
    total = len(all_ccs)
    chat_id = message.chat.id
    stop_key = f"hit:{chat_id}:{user_id}"
    _HIT_STOP_FLAGS[stop_key] = False
    _HIT_ACTIVE_USERS.add(user_id)

    # ── Get NopeCHA key for auto captcha solving ──
    nopecha_key = auth.get_nopecha_key(user_id)

    # Build a readable short label from any Stripe link type
    _id_m = re.search(r'(cs_(?:live|test)_[a-zA-Z0-9]+|plink_(?:live|test)_[a-zA-Z0-9]+)', checkout_url)
    if _id_m:
        link_short = _id_m.group(1)[:28] + "..."
    elif "billing.stripe.com" in checkout_url:
        link_short = "billing.stripe.com/..."
    elif "invoice.stripe.com" in checkout_url:
        link_short = "invoice.stripe.com/..."
    elif "payment.stripe.com" in checkout_url or "pay.stripe.com" in checkout_url:
        link_short = "pay.stripe.com/..."
    else:
        link_short = checkout_url.split("/")[-1][:28] + "..."

    # ── Grab session info with first CC ──
    loading_msg = await message.reply(
        f"{pe(E['loading'])} {bold('Loading Stripe checkout...')}\n\n"
        f"{pe(E['link'])} {bold(checkout_url[:60] + '...')}"
    )

    try:
        proxy_data = random.choice(proxies)
        # v32 — fresh SID for the very first session-loading request too
        # (no-op on non-SID proxies).
        if proxy_data:
            try:
                proxy_data = _rotate_proxy_dict_sid(proxy_data)
            except Exception:
                pass
        first_result = await asyncio.get_running_loop().run_in_executor(
            CHECKER_POOL, hit.run_hit_check, checkout_url, all_ccs[0], proxy_data, 3, nopecha_key,
        )
    except Exception as e:
        _HIT_ACTIVE_USERS.discard(user_id)
        _HIT_STOP_FLAGS.pop(stop_key, None)
        await safe_edit(loading_msg, 
            f"{pe(E['cross'])} {bold('Failed to load checkout!')}\n\n"
            f"{pe(E['warn'])} {bold(str(e)[:100])}"
        )
        return

    if not first_result.get("ok") and _hit_is_session_dead(first_result):
        _HIT_ACTIVE_USERS.discard(user_id)
        _HIT_STOP_FLAGS.pop(stop_key, None)
        await safe_edit(loading_msg, 
            f"{pe(E['cross2'])} {bold('Session Dead!')}\n\n"
            f"{pe(E['warn'])} {bold(first_result.get('error', 'Checkout expired or completed.'))}"
        )
        return

    merchant = first_result.get("merchant") or "-"
    product = first_result.get("product") or "-"
    amount_str = first_result.get("price_display") or "-"
    success_url = first_result.get("success_url") or "-"
    if success_url != "-" and len(success_url) > 50:
        from urllib.parse import urlparse as _urlparse
        _p = _urlparse(success_url)
        success_url = f"{_p.scheme}://{_p.netloc}{_p.path[:30]}..."

    checkout_info = {
        "merchant": merchant,
        "product": product,
        "amount_str": amount_str,
        "link_short": link_short,
        "success_url": success_url,
    }

    results: dict = {all_ccs[0]: first_result}
    order = list(all_ccs)

    # ── Build initial status message ──
    header = (
        f"{pe(E['gem'])} {bold('Stripe Checker')} [{bold('1')}/{bold(str(total))}]\n\n"
        f"{pe(E['bolt'])} {bold('Merchant:')} {bold(merchant)}\n"
        f"{pe(E['star'])} {bold('Product:')} {bold(product)}\n"
        f"{pe(E['bank'])} {bold('Amount:')} {bold(amount_str)}\n"
        f"{pe(E['link'])} {bold('Link:')} {bold(link_short)}\n"
        f"{pe(E['globe'])} {bold('URL:')} {bold(success_url)}\n"
    )

    init_lines = [header]
    init_lines.append(_hit_cc_block(all_ccs[0], first_result))
    for cc in all_ccs[1:]:
        init_lines.append(f"{pe(E['loading'])} <tg-spoiler>{cc}</tg-spoiler> {bold('checking...')}")

    if skipped > 0:
        init_lines.append(f"\n{pe(E['warn'])} {bold(str(skipped))} {bold('CCs skipped (max')} {bold(str(HIT_MAX_CCS))}{bold(')')}")

    init_lines.append(f"\n{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}")

    init_kb = {
        "inline_keyboard": [[{
            "text": f"{bold('Stop Checking')}",
            "callback_data": f"hit_stop:{stop_key}",
            "icon_custom_emoji_id": E["stop"],
        }]]
    }

    try:
        await safe_edit(loading_msg, "\n\n".join(init_lines), reply_markup=init_kb)
    except Exception:
        pass

    status_msg = loading_msg
    msg_id_first = loading_msg.message_id
    _HIT_EDIT_LOCKS[msg_id_first] = asyncio.Lock()

    # ── Send success to monitor if first CC hit ──
    if _hit_is_success(first_result):
        auth.save_charged_cc(all_ccs[0], user_id, user_name, "Stripe", amount_str)
        try:
            hit_text = (
                f"{pe(E['gem'])} {bold('Stripe Hit!')} {pe(E['gem'])}\n\n"
                f"{pe(R['cc'])} {bold('CC:')} <tg-spoiler>{all_ccs[0]}</tg-spoiler>\n"
                f"{pe(E['bolt'])} {bold('Merchant:')} {bold(merchant)}\n"
                f"{pe(E['bank'])} {bold('Amount:')} {bold(amount_str)}\n"
                f"{pe(R['gate'])} {bold('Response:')} {bold(_hit_raw_response(first_result))}\n\n"
                f"{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}"
            )
            await _send_charged_group(user_id, hit_text)
        except Exception:
            pass
        # Charged notification to join channel
        await _send_charged_notification(
            user_id=user_id,
            username=user_uname or "",
            full_name=user_name or "",
            amount=amount_str,
            gate_type="stripe",
            is_3d_bypassed=bool(first_result.get("tds_bypassed")),
        )
    elif _hit_is_live(first_result):
        try:
            live_text = (
                f"{_hit_status_line(first_result)}\n\n"
                f"{pe(R['cc'])} {bold('CC:')} <tg-spoiler>{all_ccs[0]}</tg-spoiler>\n"
                f"{pe(E['bolt'])} {bold('Merchant:')} {bold(merchant)}\n"
                f"{pe(E['bank'])} {bold('Amount:')} {bold(amount_str)}\n"
                f"{pe(R['gate'])} {bold('Response:')} {bold(_hit_raw_response(first_result))}\n\n"
                f"{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}"
            )
            await _send_approved(live_text)
        except Exception:
            pass

    # ── If session dead on first CC, stop ──
    if _hit_is_session_dead(first_result):
        _HIT_ACTIVE_USERS.discard(user_id)
        _HIT_STOP_FLAGS.pop(stop_key, None)
        return

    # ── Process remaining CCs sequentially ──
    try:
        for cc in all_ccs[1:]:
            if _HIT_STOP_FLAGS.get(stop_key):
                results[cc] = {"ok": False, "error": "Stopped"}
                continue

            await _hit_check_single(
                cc, checkout_url, user_id, status_msg, results, order,
                user_name, user_uname, stop_key, checkout_info,
                nopecha_key=nopecha_key,
            )

            if _hit_is_success(results.get(cc, {})):
                auth.save_charged_cc(cc, user_id, user_name, "Stripe", amount_str)
                try:
                    hit_text = (
                        f"{pe(E['gem'])} {bold('Stripe Hit!')} {pe(E['gem'])}\n\n"
                        f"{pe(R['cc'])} {bold('CC:')} <tg-spoiler>{cc}</tg-spoiler>\n"
                        f"{pe(E['bolt'])} {bold('Merchant:')} {bold(merchant)}\n"
                        f"{pe(E['bank'])} {bold('Amount:')} {bold(amount_str)}\n"
                        f"{pe(R['gate'])} {bold('Response:')} {bold(_hit_raw_response(results[cc]))}\n\n"
                        f"{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}"
                    )
                    await _send_charged_group(user_id, hit_text)
                except Exception:
                    pass
                # Charged notification to join channel
                await _send_charged_notification(
                    user_id=user_id,
                    username=user_uname or "",
                    full_name=user_name or "",
                    amount=amount_str,
                    gate_type="stripe",
                    is_3d_bypassed=bool(results.get(cc, {}).get("tds_bypassed")),
                )
            elif _hit_is_live(results.get(cc, {})):
                try:
                    live_text = (
                        f"{_hit_status_line(results[cc])}\n\n"
                        f"{pe(R['cc'])} {bold('CC:')} <tg-spoiler>{cc}</tg-spoiler>\n"
                        f"{pe(E['bolt'])} {bold('Merchant:')} {bold(merchant)}\n"
                        f"{pe(E['bank'])} {bold('Amount:')} {bold(amount_str)}\n"
                        f"{pe(R['gate'])} {bold('Response:')} {bold(_hit_raw_response(results[cc]))}\n\n"
                        f"{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}"
                    )
                    await _send_approved(live_text)
                except Exception:
                    pass

            if _HIT_STOP_FLAGS.get(stop_key):
                for remaining_cc in all_ccs[all_ccs.index(cc) + 1:]:
                    if remaining_cc not in results:
                        results[remaining_cc] = {"ok": False, "error": "Stopped (session dead)"}
                break

        # ── Final update (remove stop button) ──
        done_count = sum(1 for cc in order if cc in results)
        final_lines = [
            f"{pe(E['gem'])} {bold('Stripe Checker')} [{bold(str(done_count))}/{bold(str(total))}]\n\n"
            f"{pe(E['bolt'])} {bold('Merchant:')} {bold(merchant)}\n"
            f"{pe(E['star'])} {bold('Product:')} {bold(product)}\n"
            f"{pe(E['bank'])} {bold('Amount:')} {bold(amount_str)}\n"
            f"{pe(E['link'])} {bold('Link:')} {bold(link_short)}\n"
            f"{pe(E['globe'])} {bold('URL:')} {bold(success_url)}\n"
        ]
        for cc in order:
            if cc in results:
                final_lines.append(_hit_cc_block(cc, results[cc]))
        if skipped > 0:
            final_lines.append(f"\n{pe(E['warn'])} {bold(str(skipped))} {bold('CCs skipped (max')} {bold(str(HIT_MAX_CCS))}{bold(')')}")

        dead_any = any(_hit_is_session_dead(results.get(cc, {})) for cc in order)
        if dead_any:
            final_lines.append(f"\n{pe(E['cross2'])} {bold('Session dead — stopped.')}")

        final_lines.append(f"\n{pe(R['checked_by'])} {bold('Checked by:')} {user_link(user_id, user_name, user_uname)}")

        try:
            await safe_edit(status_msg, "\n\n".join(final_lines), reply_markup=None)
        except Exception:
            pass

        # Pin if any success
        if any(_hit_is_success(results.get(cc, {})) for cc in order):
            try:
                await bot.pin_chat_message(message.chat.id, status_msg.message_id, disable_notification=True)
            except Exception:
                pass

    finally:
        _HIT_ACTIVE_USERS.discard(user_id)
        _HIT_STOP_FLAGS.pop(stop_key, None)
        _HIT_EDIT_LOCKS.pop(msg_id_first, None)


@router.callback_query(F.data.startswith("hit_stop:"))
async def cb_hit_stop(callback: types.CallbackQuery):
    stop_key = callback.data.split(":", 1)[1]
    parts = stop_key.split(":")
    if len(parts) >= 3:
        owner_id = int(parts[2])
    else:
        owner_id = 0

    if callback.from_user.id != owner_id and not auth.is_owner(callback.from_user.id):
        await safe_callback_answer(callback, bold("Only the owner can stop this check!"), show_alert=True)
        return

    _HIT_STOP_FLAGS[stop_key] = True
    await safe_callback_answer(callback, bold("Stopping Stripe check..."), show_alert=True)


# ══════════════════════════════════════════════════════════════════════════════
#  /broad COMMAND — Owner broadcasts message to all users
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("broad"))
async def cmd_broad(message: types.Message):
    if not auth.is_owner(message.from_user.id):
        await message.reply(f"{pe(E['cross'])} {bold('Owner only command!')}")
        return

    broadcast_text = None
    broadcast_entities = None
    use_copy = False
    reply_msg = None

    # ── Mode 1: Reply to a message ────────────────────────────────────────────
    if message.reply_to_message:
        use_copy = True
        reply_msg = message.reply_to_message

    # ── Mode 2: Inline text after /broad ──────────────────────────────────────
    else:
        raw_text = message.text or ""
        raw_entities = message.entities or []

        # Find where /broad command ends
        cmd_end = 0
        for ent in raw_entities:
            if ent.type == "bot_command" and ent.offset == 0:
                cmd_end = ent.offset + ent.length
                break

        if cmd_end == 0:
            cmd_end = len("/broad")

        # Strip the command prefix and any leading whitespace/newline
        remaining = raw_text[cmd_end:]
        # Count how many chars of whitespace/newline after command
        stripped = remaining.lstrip("\n \t")
        ws_count = len(remaining) - len(stripped)
        total_prefix = cmd_end + ws_count

        broadcast_text = stripped

        if not broadcast_text:
            await message.reply(
                f"{pe(E['warn'])} {bold('Usage:')}\n\n"
                f"{pe(E['next'])} /broad {bold('Your message here')}\n"
                f"{pe(E['next'])} {bold('Or reply to any message with')} /broad"
            )
            return

        # Shift entities: only keep entities that fall within the broadcast text
        adjusted = []
        for ent in raw_entities:
            if ent.type == "bot_command" and ent.offset == 0:
                continue  # Skip the /broad command entity itself

            new_offset = ent.offset - total_prefix
            # Only include entities that are within the broadcast text
            if new_offset >= 0 and (new_offset + ent.length) <= len(broadcast_text):
                adjusted.append(types.MessageEntity(
                    type=ent.type,
                    offset=new_offset,
                    length=ent.length,
                    url=ent.url if hasattr(ent, 'url') else None,
                    user=ent.user if hasattr(ent, 'user') else None,
                    language=ent.language if hasattr(ent, 'language') else None,
                    custom_emoji_id=ent.custom_emoji_id if hasattr(ent, 'custom_emoji_id') else None,
                ))

        broadcast_entities = adjusted if adjusted else None

    # ── Get all user IDs ──────────────────────────────────────────────────────
    all_ids = auth.get_all_user_ids()
    total = len(all_ids)

    if total == 0:
        await message.reply(f"{pe(E['cross'])} {bold('No users found in users.txt!')}")
        return

    # ── Status message ────────────────────────────────────────────────────────
    status_msg = await message.reply(
        f"{pe(E['rocket'])} {bold('Broadcasting...')}\n\n"
        f"{pe(E['bolt'])} {bold('Total Users:')} {bold(str(total))}\n"
        f"{pe(E['hourglass'])} {bold('Sending...')} {bold('0')}/{bold(str(total))}"
    )

    counters = {"sent": 0, "failed": 0, "blocked": 0, "pinned": 0, "done": 0}
    lock = asyncio.Lock()
    failed_ids: list[int] = []
    sem = asyncio.Semaphore(25)  # 25 concurrent sends ≈ safe Telegram flood limit

    async def _send_one(uid: int) -> bool:
        async with sem:
            try:
                if use_copy:
                    r = await bot.copy_message(
                        chat_id=uid,
                        from_chat_id=reply_msg.chat.id,
                        message_id=reply_msg.message_id,
                    )
                else:
                    r = await bot.send_message(
                        chat_id=uid,
                        text=broadcast_text,
                        entities=broadcast_entities,
                    )
                try:
                    await bot.pin_chat_message(uid, r.message_id, disable_notification=True)
                    async with lock:
                        counters["pinned"] += 1
                except Exception:
                    pass
                async with lock:
                    counters["sent"] += 1
                return True
            except Exception as e:
                err = str(e).lower()
                async with lock:
                    if "blocked" in err or "deactivated" in err or "not found" in err:
                        counters["blocked"] += 1
                    else:
                        counters["failed"] += 1
                        failed_ids.append(uid)
                return False
            finally:
                async with lock:
                    counters["done"] += 1

    # ── Progress updater ──────────────────────────────────────────────────────
    async def _update_progress(phase: str):
        while True:
            await asyncio.sleep(1.5)
            async with lock:
                d = counters["done"]
            try:
                await safe_edit(status_msg, 
                    f"{pe(E['rocket'])} {bold(phase)}\n\n"
                    f"{pe(E['bolt'])} {bold('Progress:')} {bold(str(d))}/{bold(str(total))}\n"
                    f"{pe(E['check'])} {bold('Sent:')} {bold(str(counters['sent']))}\n"
                    f"{pe(E['star'])} {bold('Pinned:')} {bold(str(counters['pinned']))}\n"
                    f"{pe(E['cross'])} {bold('Blocked:')} {bold(str(counters['blocked']))}\n"
                    f"{pe(E['warn'])} {bold('Failed:')} {bold(str(counters['failed']))}"
                )
            except Exception:
                pass
            if d >= total:
                break

    # ── Pass 1: send to everyone in parallel ─────────────────────────────────
    prog_task = asyncio.create_task(_update_progress("Broadcasting..."))
    await asyncio.gather(*[_send_one(uid) for uid in all_ids])
    prog_task.cancel()

    # ── Pass 2: retry failed users ───────────────────────────────────────────
    if failed_ids:
        retry_list = list(failed_ids)
        failed_ids.clear()
        counters["failed"] = 0
        counters["done"] = 0
        total_retry = len(retry_list)
        total = total_retry

        try:
            await safe_edit(status_msg, 
                f"{pe(E['refresh'])} {bold('Retrying')} {bold(str(total_retry))} {bold('failed users...')}"
            )
        except Exception:
            pass

        await asyncio.sleep(2)
        prog_task2 = asyncio.create_task(_update_progress("Retrying failed..."))
        await asyncio.gather(*[_send_one(uid) for uid in retry_list])
        prog_task2.cancel()

    # ── Final summary ─────────────────────────────────────────────────────────
    try:
        await safe_edit(status_msg, 
            f"{pe(E['check'])} {bold('Broadcast Complete!')}\n\n"
            f"{pe(E['bolt'])} {bold('Total Users:')} {bold(str(len(all_ids)))}\n"
            f"{pe(E['check'])} {bold('Delivered:')} {bold(str(counters['sent']))}\n"
            f"{pe(E['star'])} {bold('Pinned:')} {bold(str(counters['pinned']))}\n"
            f"{pe(E['cross'])} {bold('Blocked/Deactivated:')} {bold(str(counters['blocked']))}\n"
            f"{pe(E['warn'])} {bold('Still Failed:')} {bold(str(counters['failed']))}"
        )
    except Exception:
        pass


# ══════════════════════════════════════════════════════════════════════════════
#  /sfilter COMMAND — Owner-only SITE filter (100 parallel, keep good sites)
#  (renamed from /filter in v70 — /filter is now the card country filter)
# ══════════════════════════════════════════════════════════════════════════════

_FILTER_CC = "5324430102980098|07|2032|670"

_FILTER_GOOD_RESPONSES = {
    "card_declined", "otp_required", "fraudulent",
    "pick_up_card", "stolen_card", "fraud_suspected",
    "authentication_required",  # maps to OTP_REQUIRED in format_result
}

FILTER_BATCH_SIZE = 100


async def _filter_check_site(site: str, proxy_data: dict | None) -> dict:
    """Check a single site with the hardcoded CC and return verdict."""
    # v32 — fresh SID per /filter probe (no-op on non-SID proxies).
    if proxy_data:
        try:
            proxy_data = _rotate_proxy_dict_sid(proxy_data)
        except Exception:
            pass
    try:
        result = await checker_bridge.check_card_site(_FILTER_CC, site, proxy_data)
    except Exception as e:
        return {"site": site, "keep": False, "reason": str(e)[:60]}

    response = (result.get("Response") or "").lower()
    gate = (result.get("Gate") or "").lower()
    price_raw = result.get("Price", "-")

    # ── Parse price ───────────────────────────────────────────────────────────
    price_val = 999.0
    try:
        price_num = re.sub(r'[^\d.]', '', str(price_raw).split()[0])
        if price_num:
            price_val = float(price_num)
    except Exception:
        pass

    # ── Check criteria ────────────────────────────────────────────────────────
    price_ok = price_val < 10.0
    gate_ok = "shopify payments" in gate
    response_ok = any(r in response for r in _FILTER_GOOD_RESPONSES)

    keep = price_ok and gate_ok and response_ok

    return {
        "site": site,
        "keep": keep,
        "response": result.get("Response", "?"),
        "gate": result.get("Gate", "?"),
        "price": price_raw,
    }


@router.message(Command("sfilter"))
async def cmd_filter(message: types.Message):
    """v70 — renamed from /filter to /sfilter (this is the SITE filter).
    The new /filter is now the card country filter (see below)."""
    log.info(f"[SFILTER] Command received from user_id={message.from_user.id}")
    user_id = message.from_user.id

    if not auth.is_owner(user_id):
        log.info(f"[FILTER] Denied — user {user_id} is not owner (OWNER_ID={auth.OWNER_ID})")
        await message.reply(f"{pe(E['cross'])} {bold('Owner only command!')}")
        return

    log.info("[FILTER] Owner verified, loading sites...")

    # ── Load sites ────────────────────────────────────────────────────────────
    sites_list = _load_sites()
    log.info(f"[FILTER] Loaded {len(sites_list)} sites from sites.txt")
    if not sites_list:
        await message.reply(f"{pe(E['cross'])} {bold('sites.txt is empty!')}")
        return

    # ── Check proxy ───────────────────────────────────────────────────────────
    proxy_data = get_user_proxy(user_id)
    if not proxy_data:
        _gfb = _global_fallback_proxy_dicts()
        proxy_data = _gfb[0] if _gfb else None
    if not proxy_data:
        await message.reply(
            f"{pe(E['cross'])} {bold('No Proxy Set!')}\n\n"
            f"{pe(E['warn'])} {bold('Add a proxy first:')} /proxy host:port:user:pass"
        )
        return

    total = len(sites_list)

    status_msg = await message.reply(
        f"{pe(E['rocket'])} {bold('Site Filter Started!')}\n\n"
        f"{pe(E['bolt'])} {bold('Total Sites:')} {bold(str(total))}\n"
        f"{pe(E['hourglass'])} {bold('Batch Size:')} {bold(str(FILTER_BATCH_SIZE))}\n"
        f"{pe(R['cc'])} {bold('Test CC:')} <tg-spoiler>{_FILTER_CC}</tg-spoiler>\n\n"
        f"{pe(E['star'])} {bold('Criteria:')}\n"
        f"{pe(E['next'])} {bold('Price < $10')}\n"
        f"{pe(E['next'])} {bold('Gate = Shopify Payments')}\n"
        f"{pe(E['next'])} {bold('Response = Declined / OTP / Fraud / Stolen')}\n\n"
        f"{pe(E['loading'])} {bold('Processing...')}"
    )

    kept_sites = []
    removed = 0
    checked = 0
    errors = 0
    _last_edit = 0.0
    proxy_list = get_user_proxies(user_id)
    if not proxy_list:
        proxy_list = _global_fallback_proxy_dicts()

    for batch_start in range(0, total, FILTER_BATCH_SIZE):
        batch = sites_list[batch_start:batch_start + FILTER_BATCH_SIZE]

        tasks = []
        for site in batch:
            p = random.choice(proxy_list) if proxy_list else proxy_data
            tasks.append(_filter_check_site(site, p))

        results = await asyncio.gather(*tasks, return_exceptions=True)

        for r in results:
            checked += 1
            if isinstance(r, Exception):
                errors += 1
                removed += 1
                continue
            if r.get("keep"):
                kept_sites.append(r["site"])
            else:
                removed += 1

        # ── Update progress every 3 seconds ───────────────────────────────────
        _now = time.time()
        if _now - _last_edit >= 3 or checked >= total:
            _last_edit = _now
            try:
                await safe_edit(status_msg, 
                    f"{pe(E['rocket'])} {bold('Filtering Sites...')}\n\n"
                    f"{pe(E['bolt'])} {bold('Progress:')} {bold(str(checked))}/{bold(str(total))}\n"
                    f"{pe(E['check'])} {bold('Kept:')} {bold(str(len(kept_sites)))}\n"
                    f"{pe(E['cross'])} {bold('Removed:')} {bold(str(removed))}\n"
                    f"{pe(E['warn'])} {bold('Errors:')} {bold(str(errors))}\n\n"
                    f"{pe(E['loading'])} {bold('Processing...')}"
                )
            except Exception:
                pass

    # ── Save filtered sites back to sites.txt ─────────────────────────────────
    global _sites_cache, _sites_cache_mtime
    with open(SITES_FILE, "w", encoding="utf-8") as f:
        for site in kept_sites:
            f.write(site.strip() + "\n")
    _sites_cache = [s.strip() for s in kept_sites if s.strip()]
    try:
        _sites_cache_mtime = os.path.getmtime(SITES_FILE)
    except OSError:
        _sites_cache_mtime = 0.0

    # ── Final summary ─────────────────────────────────────────────────────────
    try:
        await safe_edit(status_msg, 
            f"{pe(E['check'])} {bold('Site Filter Complete!')}\n\n"
            f"{pe(E['bolt'])} {bold('Total Checked:')} {bold(str(total))}\n"
            f"{pe(E['check'])} {bold('Kept:')} {bold(str(len(kept_sites)))}\n"
            f"{pe(E['cross'])} {bold('Removed:')} {bold(str(removed))}\n"
            f"{pe(E['warn'])} {bold('Errors:')} {bold(str(errors))}\n\n"
            f"{pe(E['star'])} {bold('sites.txt updated!')} {bold(str(len(kept_sites)))} {bold('sites remaining.')}"
        )
    except Exception:
        pass


# ══════════════════════════════════════════════════════════════════════════════
#  /test COMMAND — v71 — Admin-only site phone-verification tester
#
#  Tests EVERY site in sites.txt with the fixed test card
#  4509351002561046|03|26|423 and auto-removes any site that returns the
#  "This seller requires a verified phone number" response.
#
#  • Admin-only (auth.is_admin) — non-admins get "Admin only command!".
#  • The /whop and /mwhop check lanes are UNCHANGED — phone-verif during
#    a real check is still shown to the user as a normal DECLINED with the
#    text (v70 behavior, per the user's explicit request).  The eviction
#    ONLY happens through this /test command.
#  • Live status box shows: total, processing, phone verification sites
#    shown, total removed, current (sites still in sites.txt).
#  • Uses the existing whop_check_card() so the admin's proxies + the
#    project's API pool do all the heavy lifting (no new HTTP code).
#  • Sites that return a real verdict (APPROVED / DECLINED with $amount /
#    3DS / INSUFFICIENT) are kept — they're not phone-protected.
#  • Sites that return phone-verif are atomically removed from sites.txt
#    via _remove_whop_site() (thread-safe, atomic, never raises).
# ══════════════════════════════════════════════════════════════════════════════

# Fixed test card the user specified for /test.
_TEST_FIXED_CARD = "4509351002561046|03|26|423"

# How many sites to test in parallel — small enough to be polite to the
# API pool but big enough that 50 sites finish in a couple of minutes.
_TEST_CONCURRENCY = 5

# Status box refresh interval (seconds).
_TEST_STATUS_INTERVAL = 5.0


@router.message(Command("test"))
async def cmd_test_sites(message: types.Message):
    """v71 — /test: admin-only site phone-verif tester.

    Tests every site in sites.txt with the fixed test card and auto-removes
    any site that returns a phone-verification response.  Live status box
    shows total / processing / phone-verif-shown / removed / current.
    """
    user_id = message.from_user.id
    # Admin-only gate.
    try:
        if not auth.is_admin(user_id):
            await message.reply(
                f"{pe(E['cross'])} {bold('Admin only command!')}"
            )
            return
    except Exception:
        await message.reply(
            f"{pe(E['cross'])} {bold('Admin only command!')}"
        )
        return

    # Lazy-import the v71 helpers from whop.py.
    try:
        from whop import (
            _load_whop_sites,
            _remove_whop_site,
            _is_phone_verif_response,
            _reset_whop_sites_evicted,
            whop_check_card,
        )
    except Exception as _e:
        log.error("[/test] cannot import whop helpers: %s", _e)
        await message.reply(
            f"{pe(E['cross'])} {bold('Internal error — whop module not loaded.')}"
        )
        return

    # Load the current sites list (a snapshot of sites.txt at this moment).
    sites_snapshot = _load_whop_sites()
    total = len(sites_snapshot)
    if total == 0:
        await message.reply(
            f"{pe(E['warn'])} {bold('sites.txt is empty!')}\n\n"
            f"{pe(E['next'])} {bold('Add some sites first (one URL per line, optionally with - biz_XXX).')}"
        )
        return

    # Reset the in-process eviction de-dup set so previously-evicted sites
    # (which may have been re-added to sites.txt) can be re-detected.
    _reset_whop_sites_evicted()

    # Send the initial status message — the live status box.
    status_msg = await message.reply(
        f"{pe(E['rocket'])} {bold('Site Phone-Verification Test')} {pe(E['rocket'])}\n\n"
        f"{'=' * 30}\n"
        f"{pe(E['bolt'])} {bold('Total:')} {bold(str(total))}\n"
        f"{pe(E['refresh'])} {bold('Processing:')} {bold('0')}\n"
        f"{pe(E['warn'])} {bold('Phone-verif shown:')} {bold('0')}\n"
        f"{pe(E['cross'])} {bold('Total removed:')} {bold('0')}\n"
        f"{pe(E['check'])} {bold('Current:')} {bold(str(total))}\n"
        f"{'=' * 30}\n\n"
        f"{pe(E['loading'])} {bold('Starting...')}"
    )

    # Shared state — workers read/increment these under the lock.
    state_lock = asyncio.Lock()
    counters = {
        "processed": 0,           # sites that finished (any outcome)
        "phone_verif_shown": 0,   # sites that returned a phone-verif response
        "removed": 0,             # sites actually evicted from sites.txt
        "in_flight": 0,           # sites currently being tested
    }

    async def _test_one(site_url: str, biz_id: str):
        """Test a single site and evict it if it returns phone-verif."""
        # Increment in-flight under the lock.
        async with state_lock:
            counters["in_flight"] += 1
        try:
            # Run the check via the existing whop lane — never raises.
            try:
                result = await whop_check_card(
                    _TEST_FIXED_CARD, site_url, biz_id,
                    user_id=user_id,
                    priority=False,
                    chat_id=message.chat.id,
                )
            except Exception as _ce:
                # Never crash the whole /test on one card.
                log.warning("[/test] whop_check_card crashed for %s: %s",
                            str(site_url)[:80], _ce)
                result = {
                    "status": "ERROR",
                    "response": "Card declined",
                    "site": site_url, "biz_id": biz_id,
                    "card_brand": "-", "price": "-",
                    "is_charged": False, "is_insufficient": False,
                    "is_dead": True, "is_retryable": False,
                }

            # Detect phone-verif.
            is_pv = False
            try:
                is_pv = _is_phone_verif_response(result)
            except Exception:
                is_pv = False

            removed = False
            if is_pv:
                # Evict the offending site from sites.txt IMMEDIATELY.
                try:
                    removed = _remove_whop_site(site_url)
                except Exception as _re:
                    log.warning("[/test] eviction crashed for %s: %s",
                                str(site_url)[:80], _re)
                    removed = False

            # Update counters under the lock.
            async with state_lock:
                counters["processed"] += 1
                counters["in_flight"] -= 1
                if is_pv:
                    counters["phone_verif_shown"] += 1
                if removed:
                    counters["removed"] += 1
        except Exception as _oe:
            # Absolute last resort — never crash the test.
            log.error("[/test] _test_one crashed for %s: %s",
                      str(site_url)[:80], _oe)
            async with state_lock:
                counters["processed"] += 1
                counters["in_flight"] = max(0, counters["in_flight"] - 1)

    # ── Live status-box refresh task ────────────────────────────────────
    async def _refresh_status():
        """Edit the status message every _TEST_STATUS_INTERVAL seconds."""
        last_text = ""
        while True:
            try:
                await asyncio.sleep(_TEST_STATUS_INTERVAL)
                async with state_lock:
                    processed = counters["processed"]
                    in_flight = counters["in_flight"]
                    pv_shown = counters["phone_verif_shown"]
                    removed = counters["removed"]
                # "Current" = sites still in sites.txt (total - removed).
                current = max(0, total - removed)
                # Done when every site has been processed AND no workers
                # are still in-flight.
                if processed >= total and in_flight == 0:
                    return  # caller will send the final summary
                new_text = (
                    f"{pe(E['rocket'])} {bold('Site Phone-Verification Test')} {pe(E['rocket'])}\n\n"
                    f"{'=' * 30}\n"
                    f"{pe(E['bolt'])} {bold('Total:')} {bold(str(total))}\n"
                    f"{pe(E['refresh'])} {bold('Processing:')} {bold(str(processed))}\n"
                    f"{pe(E['warn'])} {bold('Phone-verif shown:')} {bold(str(pv_shown))}\n"
                    f"{pe(E['cross'])} {bold('Total removed:')} {bold(str(removed))}\n"
                    f"{pe(E['check'])} {bold('Current:')} {bold(str(current))}\n"
                    f"{'=' * 30}\n\n"
                    f"{pe(E['loading'])} {bold(f'Testing {in_flight} site(s) in parallel...')}"
                )
                if new_text != last_text:
                    last_text = new_text
                    try:
                        await safe_edit(status_msg, new_text)
                    except Exception:
                        pass
            except asyncio.CancelledError:
                return
            except Exception:
                # Keep the loop alive — never crash the status refresher.
                continue

    # ── Run all tests with limited concurrency ──────────────────────────
    async def _run_all():
        # Start the status refresher.
        refresher = asyncio.create_task(_refresh_status())
        # Use a small semaphore so we don't hammer the API pool.
        sem = asyncio.Semaphore(_TEST_CONCURRENCY)

        async def _bounded(site_url, biz_id):
            async with sem:
                await _test_one(site_url, biz_id)

        tasks = [asyncio.create_task(_bounded(u, b)) for u, b in sites_snapshot]
        try:
            await asyncio.gather(*tasks, return_exceptions=True)
        finally:
            # Stop the status refresher.
            try:
                refresher.cancel()
                await asyncio.gather(refresher, return_exceptions=True)
            except Exception:
                pass

    try:
        await _run_all()
    except Exception as _re:
        log.error("[/test] _run_all crashed: %s", _re, exc_info=True)

    # ── Final summary ───────────────────────────────────────────────────
    async with state_lock:
        processed = counters["processed"]
        pv_shown = counters["phone_verif_shown"]
        removed = counters["removed"]
    current = max(0, total - removed)
    final_text = (
        f"{pe(E['check'])} {bold('Site Phone-Verification Test Complete')} {pe(E['check'])}\n\n"
        f"{'=' * 30}\n"
        f"{pe(E['bolt'])} {bold('Total tested:')} {bold(str(processed))}\n"
        f"{pe(E['warn'])} {bold('Phone-verif shown:')} {bold(str(pv_shown))}\n"
        f"{pe(E['cross'])} {bold('Total removed:')} {bold(str(removed))}\n"
        f"{pe(E['check'])} {bold('Current sites:')} {bold(str(current))}\n"
        f"{'=' * 30}\n\n"
        f"{pe(E['star'])} {bold('sites.txt has been updated — phone-verif sites are gone.')}"
    )
    try:
        await safe_edit(status_msg, final_text)
    except Exception:
        # If we can't edit the original, send a new message as a fallback.
        try:
            await message.reply(final_text)
        except Exception:
            pass


# ══════════════════════════════════════════════════════════════════════════════
#  /filter COMMAND — v70 — Card country filter (reply to .txt file)
#
#  Two modes:
#    1. /filter              (reply to .txt)  →  group ALL cards by country,
#                                                 send a .txt with each country
#                                                 as a section header.
#    2. /filter <country>    (reply to .txt)  →  extract only cards whose BIN
#                                                 country matches the requested
#                                                 country, send a .txt with
#                                                 just those cards.
#
#  Role-based card limits:
#    Key-redeemed user : 100 – 2,000 cards
#    Admin             : 100 – 10,000 cards
#    Owner             : 100 – 100,000 cards
#
#  Processing:
#    - BIN-lookup each card via the project's `bin_lookup()` helper (uses the
#      project's existing BIN API).
#    - Live progress box, updated every 10 seconds, 0% → 100%.
#    - At the end, shows a per-country breakdown (one line per country, with
#      flag + count), then attaches the .txt file.
# ══════════════════════════════════════════════════════════════════════════════

# ── Role-based card limits ─────────────────────────────────────────────────
FILTER_MIN_CARDS = 100
FILTER_MAX_KEYED = 2_000       # key-redeemed user
FILTER_MAX_ADMIN = 10_000      # admin
FILTER_MAX_OWNER = 100_000     # owner

# Progress update interval (10 seconds, per user spec)
FILTER_PROGRESS_INTERVAL = 10.0

# BIN-lookup concurrency (we don't want to DDOS the BIN API)
_FILTER_BIN_SEMAPHORE = asyncio.Semaphore(40)


def _filter_max_for_user(user_id: int) -> int:
    """Return the per-role max card count for /filter."""
    try:
        if auth.is_owner(user_id):
            return FILTER_MAX_OWNER
    except Exception:
        pass
    try:
        if auth.is_admin(user_id):
            return FILTER_MAX_ADMIN
    except Exception:
        pass
    return FILTER_MAX_KEYED


def _filter_role_label(user_id: int) -> str:
    try:
        if auth.is_owner(user_id):
            return "OWNER"
    except Exception:
        pass
    try:
        if auth.is_admin(user_id):
            return "ADMIN"
    except Exception:
        pass
    return "KEY"


# Country-name normalization — handles user input like "USA", "US",
# "United States", "United States of America" → canonical key for matching.
_FILTER_COUNTRY_ALIASES = {
    # USA
    "usa": "united states", "us": "united states",
    "united states of america": "united states",
    "united states": "united states",
    "estados unidos": "united states",
    # UK
    "uk": "united kingdom", "gb": "united kingdom",
    "great britain": "united kingdom",
    "united kingdom": "united kingdom",
    "britain": "united kingdom",
    "england": "united kingdom",
    # Russia
    "ru": "russia", "russian federation": "russia",
    "russia": "russia",
    # Canada
    "ca": "canada", "canada": "canada",
    # Malaysia
    "my": "malaysia", "malaysia": "malaysia",
    # Brazil
    "br": "brazil", "brazil": "brazil",
    "brasil": "brazil",
    # Germany
    "de": "germany", "deutschland": "germany",
    "germany": "germany",
    # India
    "in": "india", "india": "india",
    "ind": "india",
    # Australia
    "au": "australia", "australia": "australia",
    # Japan
    "jp": "japan", "japan": "japan",
    # Turkey
    "tr": "turkey", "turkey": "turkey",
    "türkiye": "turkey", "turkiye": "turkey",
    # Mexico
    "mx": "mexico", "mexico": "mexico",
    "méxico": "mexico",
    # France
    "fr": "france", "france": "france",
    "république française": "france",
    # Netherlands
    "nl": "netherlands", "netherlands": "netherlands",
    "holland": "netherlands",
    # Indonesia
    "id": "indonesia", "indonesia": "indonesia",
    # Philippines
    "ph": "philippines", "philippines": "philippines",
    # Argentina
    "ar": "argentina", "argentina": "argentina",
    # South Africa
    "za": "south africa", "south africa": "south africa",
}


def _filter_normalize_country(name: str) -> str:
    """Normalize a country name (used for both BIN-side and user-side matching)."""
    if not name:
        return ""
    s = str(name).strip().lower()
    # Try alias map first
    if s in _FILTER_COUNTRY_ALIASES:
        return _FILTER_COUNTRY_ALIASES[s]
    # ISO-2 codes (length 2) — try upper, see if alias exists for the upper
    if len(s) == 2 and s.upper().lower() in _FILTER_COUNTRY_ALIASES:
        return _FILTER_COUNTRY_ALIASES[s]
    # Generic: lowercase + strip
    return s


def _filter_country_flag(country: str) -> str:
    """Return a flag emoji for a country name. Falls back to 🏳️ if unknown.

    Uses the same flag string returned by the project's bin_lookup() when
    available; for the section headers in the output .txt we want a sensible
    fallback.
    """
    if not country:
        return "🏳️"
    s = str(country).strip().lower()
    # Mapping by country name → ISO-2 (for flag rendering)
    name_to_iso2 = {
        "united states": "us", "united kingdom": "gb", "russia": "ru",
        "canada": "ca", "malaysia": "my", "brazil": "br", "germany": "de",
        "india": "in", "australia": "au", "japan": "jp", "turkey": "tr",
        "mexico": "mx", "france": "fr", "netherlands": "nl", "indonesia": "id",
        "philippines": "ph", "argentina": "ar", "south africa": "za",
        "spain": "es", "italy": "it", "portugal": "pt", "china": "cn",
        "south korea": "kr", "korea": "kr", "saudi arabia": "sa",
        "uae": "ae", "united arab emirates": "ae", "egypt": "eg",
        "nigeria": "ng", "kenya": "ke", "ghana": "gh", "pakistan": "pk",
        "bangladesh": "bd", "thailand": "th", "vietnam": "vn",
        "singapore": "sg", "hong kong": "hk", "taiwan": "tw",
        "israel": "il", "iran": "ir", "iraq": "iq", "lebanon": "lb",
        "morocco": "ma", "algeria": "dz", "tunisia": "tn", "libya": "ly",
        "ukraine": "ua", "poland": "pl", "romania": "ro", "czech republic": "cz",
        "czechia": "cz", "greece": "gr", "sweden": "se", "norway": "no",
        "denmark": "dk", "finland": "fi", "switzerland": "ch",
        "austria": "at", "belgium": "be", "ireland": "ie", "hungary": "hu",
        "slovakia": "sk", "croatia": "hr", "serbia": "rs", "bulgaria": "bg",
        "lithuania": "lt", "latvia": "lv", "estonia": "ee",
        "slovenia": "si", "sri lanka": "lk", "nepal": "np", "afghanistan": "af",
        "chile": "cl", "colombia": "co", "peru": "pe", "venezuela": "ve",
        "ecuador": "ec", "uruguay": "uy", "paraguay": "py", "bolivia": "bo",
        "dominican republic": "do", "puerto rico": "pr", "cuba": "cu",
        "guatemala": "gt", "honduras": "hn", "el salvador": "sv",
        "costa rica": "cr", "panama": "pa", "jamaica": "jm",
        "trinidad and tobago": "tt", "bahamas": "bs", "barbados": "bb",
        "iceland": "is", "luxembourg": "lu", "malta": "mt", "cyprus": "cy",
        "qatar": "qa", "kuwait": "kw", "bahrain": "bh", "oman": "om",
        "jordan": "jo", "syria": "sy", "yemen": "ye", "sudan": "sd",
        "ethiopia": "et", "tanzania": "tz", "uganda": "ug", "cameroon": "cm",
        "ivory coast": "ci", "senegal": "sn", "zimbabwe": "zw",
        "botswana": "bw", "namibia": "na", "zambia": "zm", "angola": "ao",
        "mozambique": "mz", "madagascar": "mg", "mauritius": "mu",
    }
    iso2 = name_to_iso2.get(s)
    if not iso2:
        return "🏳️"
    # Convert ISO-2 to flag emoji (regional indicator symbols)
    try:
        return chr(0x1F1E6 + ord(iso2[0]) - ord('a')) + chr(0x1F1E6 + ord(iso2[1]) - ord('a'))
    except Exception:
        return "🏳️"


async def _filter_bin_lookup_one(bin6: str) -> dict:
    """Async wrapper around bin_lookup with a concurrency limit."""
    async with _FILTER_BIN_SEMAPHORE:
        try:
            return await bin_lookup(bin6)
        except Exception:
            return {}


@router.message(Command("filter"))
async def cmd_filter_cards(message: types.Message):
    """v70 — Card country filter.

    Reply to a .txt file containing cards (one per line) and use:

        /filter              → group every card by country, send .txt
        /filter usa          → only USA cards
        /filter canada       → only Canada cards
        /filter "United Kingdom"  → only UK cards

    Min 100 cards.  Max varies by role:
        key-redeemed : 2,000
        admin        : 10,000
        owner        : 100,000
    """
    # v70 — gate on/off check (dashboard toggle)
    if _gate_off("filter"):
        await _gate_disabled_reply(message, "filter")
        return

    user_id = message.from_user.id
    if auth.is_banned(user_id):
        return

    # Must have premium / admin / owner access
    is_owner = False
    is_admin = False
    try:
        is_owner = auth.is_owner(user_id)
    except Exception:
        pass
    try:
        is_admin = auth.is_admin(user_id)
    except Exception:
        pass
    has_access = is_owner or is_admin
    if not has_access:
        try:
            has_access = bool(auth.has_premium_access(user_id, message.chat.id))
        except Exception:
            has_access = False
    if not has_access:
        await message.reply(
            f"{pe(E['cross'])} {bold('Access Required!')}\n\n"
            f"{pe(E['bolt'])} {bold('You need premium access, admin, or owner to use /filter.')}"
        )
        return

    # ── Parse optional country arg ───────────────────────────────────────
    country_arg = ""
    args = message.text.split(maxsplit=1)
    if len(args) >= 2:
        country_arg = args[1].strip().strip('"').strip("'")
    target_country = _filter_normalize_country(country_arg) if country_arg else ""
    target_display = country_arg if country_arg else ""  # for the message header

    # ── Must reply to a .txt ─────────────────────────────────────────────
    if not message.reply_to_message or not message.reply_to_message.document:
        await message.reply(
            f"{wpe('warn')} {_to_bi('Reply to a .txt file with cards!')}\n\n"
            f"{wpe('arrow_right')} {_to_bi('Usage:')}\n"
            f"{wpe('arrow_right')} {_to_bi('Reply to .txt + send /filter (groups by country)')}\n"
            f"{wpe('arrow_right')} {_to_bi('Reply to .txt + send /filter usa (only USA)')}\n"
            f"{wpe('fire')} {_to_bi('Min 100 cards · see role limits in /cmds')}"
        )
        return

    doc = message.reply_to_message.document
    if doc.file_size and doc.file_size > 50 * 1024 * 1024:
        await message.reply(f"{wpe('cross')} {_to_bi('File too large (max 50 MB).')}")
        return

    # ── Initial status ───────────────────────────────────────────────────
    role_label = _filter_role_label(user_id)
    max_cards = _filter_max_for_user(user_id)
    filter_mode = (
        f"{wpe('arrow_right')} {_to_bi('Mode:')} {_to_bi('Country filter — ' + target_display.upper() if target_country else 'Group all cards by country')}\n"
        if True else ""
    )
    status_msg = await message.reply(
        f"{wpe('arc_reactor')} {_to_bi('Downloading file...')}\n"
        f"{wpe('arrow_right')} {_to_bi('Role:')} {_to_bi(role_label)}\n"
        f"{wpe('arrow_right')} {_to_bi('Limit:')} {_to_bi(f'100 - {max_cards:,} cards')}\n"
        f"{wpe('loading')} {_to_bi('Reading .txt...')}"
    )

    # ── Download + read .txt ─────────────────────────────────────────────
    try:
        file = await bot.download(doc.file_id)
        content = file.read().decode("utf-8", errors="replace")
    except Exception as e:
        await safe_edit(status_msg,
            f"{wpe('skull')} {_to_bi('Failed to read file:')} {_to_bi(str(e)[:80])}"
        )
        return

    # ── Parse cards ──────────────────────────────────────────────────────
    from helpers import CC_PATTERN
    all_ccs: list[str] = []
    seen: set[str] = set()
    # 1) try regex
    for m in CC_PATTERN.finditer(content):
        cc = f"{m.group(1)}|{m.group(2)}|{m.group(3)}|{m.group(4)}"
        if cc not in seen:
            seen.add(cc)
            all_ccs.append(cc)
    # 2) fallback: split on | or /
    if not all_ccs:
        for line in content.strip().splitlines():
            parts = re.split(r"[|/]", line.strip())
            if len(parts) >= 4:
                cc = "|".join(p.strip() for p in parts[:4])
                if cc not in seen:
                    seen.add(cc)
                    all_ccs.append(cc)

    total = len(all_ccs)
    if total == 0:
        await safe_edit(status_msg,
            f"{wpe('cross')} {_to_bi('No valid cards found in file!')}"
        )
        return

    if total < FILTER_MIN_CARDS:
        await safe_edit(status_msg,
            f"{wpe('warn')} {_to_bi('Not enough cards!')}\n\n"
            f"{wpe('arrow_right')} {_to_bi(f'Minimum is {FILTER_MIN_CARDS} cards, you sent {total}.')}"
        )
        return

    if total > max_cards:
        # Auto-cut to the role limit (don't reject the whole request).
        all_ccs = all_ccs[:max_cards]
        total = len(all_ccs)
        await safe_edit(status_msg,
            f"{wpe('warn')} {_to_bi('Auto-cut to role limit')}\n\n"
            f"{wpe('arrow_right')} {_to_bi(f'Kept first {max_cards:,} cards (your role: {role_label})')}\n"
            f"{wpe('loading')} {_to_bi('Starting country filter...')}"
        )
        await asyncio.sleep(1.5)

    # ── Reset status box ─────────────────────────────────────────────────
    await safe_edit(status_msg,
        f"{wpe('announcement')} {_to_bi('Card Country Filter')}\n\n"
        f"{wpe('card')} {_to_bi('Total cards:')} {_to_bi(str(total))}\n"
        + (f"{wpe('arrow_right')} {_to_bi('Mode:')} {_to_bi('Extract ' + target_display.upper() + ' cards only')}\n" if target_country else
           f"{wpe('arrow_right')} {_to_bi('Mode:')} {_to_bi('Group all cards by country')}\n")
        + f"{wpe('hourglass')} {_to_bi('Progress:')} {_to_bi('0%')}\n"
        f"{wpe('loading')} {_to_bi('BIN-looking up cards...')}"
    )

    # ── BIN-lookup every card, grouped ───────────────────────────────────
    # Build a deduplicated BIN→country map first (we may have 100k cards but
    # far fewer unique BINs — usually <5000).
    bin_to_cards: dict[str, list[str]] = {}
    for cc in all_ccs:
        bin6 = cc.split("|")[0][:6]
        bin_to_cards.setdefault(bin6, []).append(cc)
    unique_bins = list(bin_to_cards.keys())
    n_bins = len(unique_bins)

    bin_country: dict[str, tuple[str, str, str, str]] = {}  # bin6 → (country, flag, brand, type)
    # Process BINs in parallel batches of 40
    done_bins = 0
    last_edit = 0.0

    async def _lookup_bin(b6: str) -> tuple[str, dict]:
        info = await _filter_bin_lookup_one(b6)
        return (b6, info)

    # Use gather in chunks so we can update progress
    chunk = 40
    tasks_in_flight = []
    bins_iter = iter(unique_bins)

    async def _drain_some(n: int):
        """Launch up to n BIN lookups, await all, return list of (bin, info)."""
        out = []
        for _ in range(n):
            try:
                b6 = next(bins_iter)
            except StopIteration:
                break
            tasks_in_flight.append(asyncio.create_task(_lookup_bin(b6)))
        if tasks_in_flight:
            done, pending = await asyncio.wait(tasks_in_flight, return_when=asyncio.ALL_COMPLETED)
            tasks_in_flight.clear()
            for t in done:
                try:
                    out.append(t.result())
                except Exception:
                    pass
        return out

    while True:
        results = await _drain_some(chunk)
        if not results:
            break
        for b6, info in results:
            country = ""
            flag = ""
            brand = ""
            ctype = ""
            try:
                country = str(info.get("country", "") or "")
                flag = str(info.get("flag", "") or "")
                brand = str(info.get("brand", "") or "")
                ctype = str(info.get("type", "") or "")
            except Exception:
                pass
            bin_country[b6] = (country, flag, brand, ctype)
        done_bins = len(bin_country)
        # ── Live progress update every 10 seconds ──────────────────────
        _now = time.time()
        if _now - last_edit >= FILTER_PROGRESS_INTERVAL or done_bins >= n_bins:
            last_edit = _now
            pct = int(done_bins * 100 / n_bins) if n_bins else 100
            try:
                await safe_edit(status_msg,
                    f"{wpe('announcement')} {_to_bi('Card Country Filter')}\n\n"
                    f"{wpe('card')} {_to_bi('Total cards:')} {_to_bi(str(total))}\n"
                    + (f"{wpe('arrow_right')} {_to_bi('Mode:')} {_to_bi('Extract ' + target_display.upper() + ' cards only')}\n" if target_country else
                       f"{wpe('arrow_right')} {_to_bi('Mode:')} {_to_bi('Group all cards by country')}\n")
                    + f"{wpe('hourglass')} {_to_bi('Progress:')} {_to_bi(f'{pct}%')} "
                      f"{_to_bi(f'({done_bins}/{n_bins} BINs)')}\n"
                    f"{wpe('loading')} {_to_bi('BIN-looking up cards...')}"
                )
            except Exception:
                pass

    # ── Group cards by country ───────────────────────────────────────────
    # country_key (normalized) → {display_name, flag, cards: [cc,...]}
    by_country: dict[str, dict] = {}

    for b6, cards in bin_to_cards.items():
        country, flag, brand, ctype = bin_country.get(b6, ("", "", "", ""))
        if not country:
            country = "Unknown"
            flag = "🏳️"
        key = _filter_normalize_country(country) or "unknown"
        if key not in by_country:
            by_country[key] = {
                "display": country,    # original display name from BIN API
                "flag": flag,
                "cards": [],
            }
        by_country[key]["cards"].extend(cards)

    # ── Build the output ─────────────────────────────────────────────────
    # Two outputs:
    #   1. A summary message (per-country breakdown, one line per country,
    #      with flag + count) — shown in chat.
    #   2. A .txt file with cards grouped by country, sent as a document.

    # Sort by count descending
    sorted_countries = sorted(by_country.items(), key=lambda kv: -len(kv[1]["cards"]))

    # ── Build the .txt content ───────────────────────────────────────────
    out_lines = []
    out_lines.append(f"# Card Country Filter — Whopex v70")
    out_lines.append(f"# Source file:  {doc.file_name or 'cards.txt'}")
    out_lines.append(f"# Total cards:  {total}")
    out_lines.append(f"# Unique BINs:  {n_bins}")
    out_lines.append(f"# Countries:    {len(sorted_countries)}")
    if target_country:
        out_lines.append(f"# Mode:         EXTRACT ONLY — {target_display.upper()}")
    else:
        out_lines.append(f"# Mode:         GROUP ALL BY COUNTRY")
    out_lines.append(f"# Generated:    {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
    out_lines.append(f"# Filter run by user_id={user_id} (role={role_label})")
    out_lines.append("")

    # Header line per country, then the cards, then a blank line.
    matched_count = 0
    if target_country:
        # Extract mode — only the requested country's cards.
        # Match either by normalized name OR by display name containing the query.
        target_lc = target_country.lower()
        target_disp_lc = target_display.lower()
        chosen = None
        for key, info in sorted_countries:
            disp_lc = (info["display"] or "").lower()
            if key == target_country or disp_lc == target_lc \
               or target_disp_lc in disp_lc or disp_lc in target_disp_lc \
               or (len(target_display) >= 3 and target_disp_lc in disp_lc):
                chosen = (key, info)
                break
        if chosen is None:
            out_lines.append(f"# No cards found for country: {target_display}")
            out_lines.append("")
            out_lines.append(f"# Available countries in this file:")
            for key, info in sorted_countries:
                out_lines.append(f"#   {info['flag']} {info['display']}  —  {len(info['cards'])} cards")
        else:
            key, info = chosen
            out_lines.append(f"### {info['flag']}  {info['display']}  —  {len(info['cards'])} cards ###")
            out_lines.append("")
            for cc in info["cards"]:
                out_lines.append(cc)
            matched_count = len(info["cards"])
    else:
        # Group-all mode — every country as a section.
        for key, info in sorted_countries:
            out_lines.append(f"### {info['flag']}  {info['display']}  —  {len(info['cards'])} cards ###")
            out_lines.append("")
            for cc in info["cards"]:
                out_lines.append(cc)
            out_lines.append("")
            out_lines.append("----------------------------------------")
            out_lines.append("")
        matched_count = total

    out_text = "\n".join(out_lines) + "\n"

    # ── Save the .txt to disk so we can attach it ────────────────────────
    out_dir = os.path.join(_v70_dir, "filter_output")
    try:
        os.makedirs(out_dir, exist_ok=True)
    except Exception:
        pass
    if target_country:
        fname = f"filter_{target_display.lower().replace(' ', '_')}_{int(time.time())}.txt"
    else:
        fname = f"filter_all_countries_{int(time.time())}.txt"
    out_path = os.path.join(out_dir, fname)
    try:
        with open(out_path, "w", encoding="utf-8") as f:
            f.write(out_text)
    except Exception as e:
        log.error("[filter] failed to write output file: %s", e, exc_info=True)
        await safe_edit(status_msg,
            f"{wpe('cross')} {_to_bi('Failed to write output file:')} {_to_bi(str(e)[:80])}"
        )
        return

    # ── Final summary message in chat (one line per country) ─────────────
    if target_country and matched_count == 0:
        summary_lines = [
            f"{wpe('cross')} {_to_bi('No cards found for country:')} {_to_bi(target_display.upper())}",
            f"",
            f"{wpe('triple_ring')} {_to_bi('Available countries in file:')}",
        ]
        for key, info in sorted_countries[:30]:
            summary_lines.append(
                f"{info['flag']} {_to_bi(info['display'])}  —  {_to_bi(str(len(info['cards'])))}"
            )
        if len(sorted_countries) > 30:
            summary_lines.append(
                f"{wpe('arrow_right')} {_to_bi(f'...and {len(sorted_countries) - 30} more (see attached .txt)')}"
            )
    else:
        summary_lines = [
            f"{wpe('checkmark')} {_to_bi('Filter Complete')}\n",
            f"{wpe('card')} {_to_bi('Total cards:')} {_to_bi(str(total))}",
            f"{wpe('globe')} {_to_bi('Countries found:')} {_to_bi(str(len(sorted_countries)))}",
        ]
        if target_country:
            summary_lines.append(
                f"{wpe('arrow_right')} {_to_bi('Extracted:')} {_to_bi(str(matched_count))} {_to_bi('cards from ' + target_display.upper())}"
            )
        summary_lines.append(f"")
        summary_lines.append(f"{wpe('triple_ring')} {_to_bi('Country breakdown:')}")
        for key, info in sorted_countries[:50]:
            summary_lines.append(
                f"{info['flag']} {_to_bi(info['display'])}  —  {_to_bi(str(len(info['cards'])))} {_to_bi('cards')}"
            )
        if len(sorted_countries) > 50:
            summary_lines.append(
                f"{wpe('arrow_right')} {_to_bi(f'...and {len(sorted_countries) - 50} more (see attached .txt)')}"
            )

    try:
        await safe_edit(status_msg, "\n".join(summary_lines))
    except Exception:
        pass

    # ── Send the .txt file ────────────────────────────────────────────────
    try:
        from aiogram.types import FSInputFile
        out_doc = FSInputFile(out_path, filename=fname)
        await message.reply_document(
            out_doc,
            caption=(
                f"{wpe('star')} {_to_bi('Card Country Filter')}\n"
                f"{wpe('card')} {_to_bi('Total:')} {_to_bi(str(total))}\n"
                + (f"{wpe('arrow_right')} {_to_bi('Country:')} {_to_bi(target_display.upper())}\n" if target_country else "")
                + f"{wpe('globe')} {_to_bi('Countries:')} {_to_bi(str(len(sorted_countries)))}\n"
                f"{wpe('sparkle')} {_to_bi('Whopex v70')}"
            ),
        )
    except Exception as e:
        log.error("[filter] failed to send output file: %s", e, exc_info=True)
        try:
            await message.reply(
                f"{wpe('cross')} {_to_bi('Failed to send file:')} {_to_bi(str(e)[:80])}\n\n"
                f"{wpe('arrow_right')} {_to_bi('Output saved at:')} <code>{out_path}</code>"
            )
        except Exception:
            pass


# ══════════════════════════════════════════════════════════════════════════════
#  /rmadmin COMMAND — v70 — Owner removes an admin (by @username or user-id)
# ══════════════════════════════════════════════════════════════════════════════

@router.message(Command("rmadmin"))
async def cmd_rmadmin(message: types.Message):
    """v70 — Owner-only command. Removes a user from the admin list.

    Accepts:
      /rmadmin @username     (must have been seen by the bot before)
      /rmadmin <user_id>      (numeric Telegram user ID)
      /rmadmin                (reply to the admin's message)

    Only removes the user IF they are currently an admin. If they aren't,
    replies with "User is not an admin."
    """
    if not auth.is_owner(message.from_user.id):
        await message.reply(f"{pe(E['cross'])} {bold('Owner only command!')}")
        return

    args = message.text.split(maxsplit=1)
    target_id = 0
    target_username = ""

    # Method 1: Reply to a message
    if message.reply_to_message:
        target_id = message.reply_to_message.from_user.id
        target_username = message.reply_to_message.from_user.username or ""
    # Method 2: by @username or numeric ID
    elif len(args) >= 2:
        raw = args[1].strip().lstrip("@")
        if raw.isdigit():
            target_id = int(raw)
        else:
            target_username = raw
            # Resolve username → user_id via the bot's cache
            target_id = _resolve_username_to_id(target_username)
            if not target_id:
                await message.reply(
                    f"{wpe('cross')} {_to_bi('Cannot resolve @' + target_username + ' to a user ID.')}\n\n"
                    f"{wpe('arrow_right')} {_to_bi('The bot must have seen this user before (e.g. they sent /start).')}\n"
                    f"{wpe('arrow_right')} {_to_bi('Or use a numeric user ID:')} /rmadmin <user_id>"
                )
                return
    else:
        _reply_msg = (
            f"{wpe('warn')} {_to_bi('Usage:')}\n\n"
            f"{wpe('arrow_right')} /rmadmin @username\n"
            f"{wpe('arrow_right')} /rmadmin <user_id>\n"
            + wpe('arrow_right') + " " + _to_bi("Or reply to the admin's message with /rmadmin")
        )
        await message.reply(_reply_msg)
        return

    if not target_id:
        await message.reply(
            f"{wpe('cross')} {_to_bi('Could not determine target user.')}"
        )
        return

    # ── Confirm the target is currently an admin ────────────────────────
    is_admin = False
    try:
        is_admin = auth.is_admin(target_id)
    except Exception:
        is_admin = False

    if not is_admin:
        target_label = f"@{target_username}" if target_username else f"`{target_id}`"
        await message.reply(
            f"{wpe('warn')} {_to_bi('User is not an admin.')}\n\n"
            f"{wpe('user')} {_to_bi('Target:')} {_to_bi(target_label)}"
        )
        return

    # ── Remove the admin ─────────────────────────────────────────────────
    removed = False
    try:
        removed = bool(auth.remove_admin(target_id))
    except Exception as e:
        await message.reply(
            f"{wpe('cross')} {_to_bi('Failed to remove admin:')} {_to_bi(str(e)[:80])}"
        )
        return

    target_label = f"@{target_username}" if target_username else str(target_id)
    if removed:
        await message.reply(
            f"{wpe('check')} {_to_bi('Admin Removed!')}\n\n"
            f"{wpe('user')} {_to_bi('Target:')} {_to_bi(target_label)}\n"
            f"{wpe('user')} {_to_bi('ID:')} {_to_bi(str(target_id))}"
        )
        # Notify the demoted admin
        try:
            await bot.send_message(
                target_id,
                f"{pe(E['warn'])} {bold('You have been removed from admin.')}\n\n"
                f"{pe(E['bolt'])} {bold('You no longer have admin access.')}"
            )
        except Exception:
            pass
    else:
        await message.reply(
            f"{wpe('warn')} {_to_bi('User is not an admin.')}"
        )


# ══════════════════════════════════════════════════════════════════════════════
#  ST SITE STORAGE (stsite.json) — per-user WooCommerce site for /st /mst /stxt
# ══════════════════════════════════════════════════════════════════════════════

_ST_TEST_CC = "4147202717295883|12|2029|140"

_stsite_cache: dict | None = None
_stsite_cache_mtime: float = 0.0
STSITE_MAX = 25  # max sites per user

def _load_stsites() -> dict:
    global _stsite_cache, _stsite_cache_mtime
    try:
        mt = os.path.getmtime(STSITE_FILE)
    except OSError:
        return {}
    if _stsite_cache is not None and mt == _stsite_cache_mtime:
        return _stsite_cache
    try:
        with open(STSITE_FILE, "r", encoding="utf-8") as f:
            _stsite_cache = json.load(f)
            _stsite_cache_mtime = mt
            return _stsite_cache
    except Exception:
        return {}

def _save_stsites(data: dict):
    global _stsite_cache, _stsite_cache_mtime
    with open(STSITE_FILE, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)
    _stsite_cache = data
    try:
        _stsite_cache_mtime = os.path.getmtime(STSITE_FILE)
    except OSError:
        _stsite_cache_mtime = 0.0

def _normalize_stsite_url(url: str) -> str:
    return url.strip().replace("https://", "").replace("http://", "").strip("/")

def _coerce_stsite_list(val) -> list:
    """Backward-compat: old format was a plain string, new format is a list."""
    if isinstance(val, str):
        return [val] if val else []
    if isinstance(val, list):
        return val
    return []

def get_user_stsites(user_id: int) -> list[str]:
    """Return all saved ST sites for a user."""
    return _coerce_stsite_list(_load_stsites().get(str(user_id)))

def get_user_stsite(user_id: int) -> str | None:
    """Return a random site from the user's list, or None if empty."""
    sites = get_user_stsites(user_id)
    return random.choice(sites) if sites else None

def add_user_stsite(user_id: int, url: str) -> str:
    """Add a site. Returns 'added', 'duplicate', or 'limit'."""
    url = _normalize_stsite_url(url)
    data = _load_stsites()
    sites = _coerce_stsite_list(data.get(str(user_id)))
    if url in sites:
        return "duplicate"
    if len(sites) >= STSITE_MAX:
        return "limit"
    sites.append(url)
    data[str(user_id)] = sites
    _save_stsites(data)
    return "added"

def set_user_stsite(user_id: int, url: str):
    """Legacy alias — adds url to list (called by /sadd after site test)."""
    add_user_stsite(user_id, url)

def del_user_stsite(user_id: int, index: int | None = None):
    """Remove site by 1-based index, or all sites if index is None."""
    data = _load_stsites()
    key = str(user_id)
    sites = _coerce_stsite_list(data.get(key))
    if index is None:
        data.pop(key, None)
    else:
        if 1 <= index <= len(sites):
            sites.pop(index - 1)
            if sites:
                data[key] = sites
            else:
                data.pop(key, None)
    _save_stsites(data)

def _proxy_dict_to_url(proxy_data: dict) -> str | None:
    """Convert a proxy dict (ip/port/username/password/proxy_url) to a URL.

    v75: SID rotation REMOVED. Uses the EXACT proxy the user added.
    No SID swapping, no modification. The proxy is returned as-is.
    """
    from helpers import proxy_dict_to_url
    url = proxy_dict_to_url(proxy_data)
    return url


def _rotate_proxy_dict_sid(proxy_data):
    """v75: NO-OP. Returns the proxy_data unchanged. SID rotation removed.
    Uses the EXACT proxy the user added — no modification.
    """
    return proxy_data


# ══════════════════════════════════════════════════════════════════════════════
#  UNIFIED PROXY POOL — v76 NEW
#  Whop, Shopify, Braintree, Stripe already use a unified fallback chain
#  (whop_proxies.json → proxy.json → global_proxies.txt). /sq and /msq were
#  the ONLY gates that read from proxy.json alone, which meant proxies a user
#  added via /addproxy (saved to whop_proxies.json) were NEVER used by /sq or
#  /msq — leading to "CONNECT tunnel failed / response 403" errors with stale
#  proxies in proxy.json. This helper unifies the pool for /sq and /msq too.
# ══════════════════════════════════════════════════════════════════════════════

def _get_unified_proxy_pool(user_id: int) -> list[str]:
    """Build a unified proxy URL pool for a user.

    Order of preference (first non-empty wins, but ALL are merged into the
    pool so the gate can rotate through them):
      1. whop_proxies.json — where /addproxy saves proxies (RAW strings:
         host:port:user:pass, http://user:pass@host:port, etc.)
      2. proxy.json — legacy store (parsed dicts with proxy_url field)
      3. global_proxies.txt — global fallback pool (RAW strings)

    All proxies are returned as URL-formatted strings suitable for passing
    to sqcharge.square_check_card(proxy_pool=...) or any HTTP client.
    Returns an empty list if no proxies are configured anywhere.
    """
    pool: list[str] = []
    seen: set = set()

    def _add_url(url: str | None):
        if not url:
            return
        url = str(url).strip()
        if not url:
            return
        if url in seen:
            return
        seen.add(url)
        pool.append(url)

    # 1. whop_proxies.json — raw strings the user added via /addproxy
    try:
        for raw in get_user_whop_proxies(user_id):
            if not raw or not str(raw).strip():
                continue
            url = _parse_proxy_to_url(str(raw).strip())
            _add_url(url)
    except Exception as e:
        log.debug("unified pool: whop_proxies load failed for %s: %s", user_id, e)

    # 2. proxy.json — legacy dict store
    try:
        for pd in get_user_proxies(user_id):
            if not pd:
                continue
            if isinstance(pd, dict):
                url = _proxy_dict_to_url(pd)
                _add_url(url)
            elif isinstance(pd, str) and pd.strip():
                url = _parse_proxy_to_url(pd.strip())
                _add_url(url)
    except Exception as e:
        log.debug("unified pool: proxy.json load failed for %s: %s", user_id, e)

    # 3. global_proxies.txt — global fallback
    try:
        for pd in _global_fallback_proxy_dicts():
            if not pd:
                continue
            url = _proxy_dict_to_url(pd) if isinstance(pd, dict) else _parse_proxy_to_url(str(pd))
            _add_url(url)
    except Exception as e:
        log.debug("unified pool: global_proxies load failed: %s", e)

    log.info("unified proxy pool for user %s: %d proxies", user_id, len(pool))
    return pool


_ST_VALID_RESPONSES = ("card added", "3d requires_action", "card was declined")

def _st_status_line(msg: str) -> str:
    ml = msg.lower().strip()
    if "card added" in ml:
        return f"{pe(E['gem'])} {bold('Card Added!')}"
    if "3d requires_action" in ml or "requires_action" in ml:
        return f"{pe(E['check'])} {bold('3DS Required — Live')}"
    if "card was declined" in ml or "declined" in ml:
        return f"{pe(E['cross'])} {bold('Declined')}"
    if "insufficient" in ml:
        return f"{pe(E['check2'])} {bold('Insufficient Funds — Live')}"
    if "incorrect_cvc" in ml or "invalid_cvc" in ml:
        return f"{pe(E['check3'])} {bold('Incorrect CVC — Live')}"
    if "expired" in ml:
        return f"{pe(E['cross2'])} {bold('Card Expired')}"
    return f"{pe(E['warn2'])} {bold(msg[:60])}"

def _st_is_working_response(msg: str) -> bool:
    ml = msg.lower().strip()
    return any(r in ml for r in _ST_VALID_RESPONSES)


# ── /sadd — Add / test WooCommerce sites (1 or many) ─────────────────────────

def _parse_sadd_urls(raw: str) -> list[str]:
    """
    Extract clean domain/URL tokens from bulk-paste input.
    Handles:
      • One per line: "example.com\nfoo.com"
      • Inline Markdown links: "site.com (https://site.com/)"
      • Mixed whitespace
    """
    # Replace newlines with spaces so we can split uniformly
    flat = raw.replace("\n", " ").replace("\r", " ")
    tokens = flat.split()
    seen = set()
    result = []
    for tok in tokens:
        # Skip parenthesised http(s) link wrappers like "(https://site.com/)"
        if tok.startswith("(") and "http" in tok:
            continue
        # Strip surrounding punctuation/parens
        tok = tok.strip("()")
        # Must look like a domain (has a dot, no spaces, not just a protocol)
        if "." not in tok or tok.startswith("http"):
            # Accept raw http/https URLs too — normalize them
            if tok.startswith("http://") or tok.startswith("https://"):
                clean = _normalize_stsite_url(tok)
                if clean and clean not in seen:
                    seen.add(clean)
                    result.append(clean)
            continue
        clean = _normalize_stsite_url(tok)
        if clean and clean not in seen:
            seen.add(clean)
            result.append(clean)
    return result


@router.message(Command("sadd"))
async def cmd_sadd(message: types.Message):
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return

    user_id = message.from_user.id
    if auth.is_banned(user_id):
        return

    if not auth.has_premium_access(user_id, message.chat.id):
        await message.reply(
            f"{pe(E['cross'])} {bold('Premium Access Required!')}"
            f"\n\n{pe(E['bolt'])} {bold('Contact admin or redeem a key: @tatsuyo_001')}"
            f"\n{pe(E['next'])} /redeem {bold('Tatsuyo-xxxxx')}"
        )
        return

    # Extract everything after /sadd (handles both inline and next-line formats)
    args = message.text.split(maxsplit=1)
    if len(args) < 2 or not args[1].strip():
        sites = get_user_stsites(user_id)
        usage = (
            f"{pe(E['warn'])} {bold('Usage:')}\n\n"
            f"{pe(E['next'])} /sadd {bold('example.com')}\n"
            f"{pe(E['next'])} {bold('Paste multiple sites (one per line) after /sadd')}\n\n"
            f"{pe(E['bolt'])} {bold('Adds working WooCommerce sites (max 25 total)')}\n"
            f"{pe(E['star'])} {bold('A random site is picked each check.')}\n"
            f"{pe(E['cross'])} {bold('Remove:')} /srem {bold('N')} {bold('or /srem all')}"
        )
        if sites:
            numbered = "\n".join(f"{pe(E['next'])} {bold(str(i+1)+'.')} {bold(s)}" for i, s in enumerate(sites))
            usage += f"\n\n{pe(E['check'])} {bold(f'Your sites ({len(sites)}/25):')}\n{numbered}"
        await message.reply(usage)
        return

    urls_to_test = _parse_sadd_urls(args[1])
    if not urls_to_test:
        await message.reply(
            f"{pe(E['warn'])} {bold('No valid sites found in your message.')}\n\n"
            f"{pe(E['next'])} {bold('Send domains like:')} example.com"
        )
        return

    proxy_data = get_user_proxy(user_id)

    if not proxy_data:

        _gfb = _global_fallback_proxy_dicts()

        proxy_data = _gfb[0] if _gfb else None
    proxy_url = _proxy_dict_to_url(proxy_data) if proxy_data else None
    _px_list = [_proxy_dict_to_url(p) for p in get_user_proxies(user_id) if _proxy_dict_to_url(p)]

    added_list: list[str] = []
    failed_list: list[str] = []
    skipped_dup: list[str] = []
    skipped_limit: list[str] = []

    _SADD_BATCH   = 25   # parallel test slots per batch
    _SADD_RETRIES = 2    # attempts per site before marking failed

    async def _test_one_stsite(url: str) -> tuple[str, bool, str]:
        """Test a single ST site with up to _SADD_RETRIES attempts. Returns (url, ok, response)."""
        last_resp = "No response"
        for attempt in range(_SADD_RETRIES):
            try:
                res = await asyncio.get_running_loop().run_in_executor(
                    CHECKER_POOL, lambda u=url: st.VW(_ST_TEST_CC, u, proxy_url, proxy_list=_px_list)
                )
                last_resp = str(res).strip()
                if _st_is_working_response(last_resp):
                    return url, True, last_resp
            except Exception as exc:
                last_resp = str(exc)[:80]
        return url, False, last_resp

    total = len(urls_to_test)
    loading_msg = await message.reply(
        f"{pe(E['loading'])} {bold(f'Testing {total} site(s) in batches of 25...')}\n\n"
        f"{pe(R['cc'])} {bold('Test CC:')} <tg-spoiler>{_ST_TEST_CC}</tg-spoiler>\n"
        f"{pe(E['hourglass'])} {bold('Starting...')}"
    )

    processed = 0
    for batch_start in range(0, total, _SADD_BATCH):
        # Pre-check: separate sites that need testing from those already done/over limit
        remaining_slots = STSITE_MAX - len(get_user_stsites(user_id))
        batch_raw = urls_to_test[batch_start: batch_start + _SADD_BATCH]

        to_test = []
        for url in batch_raw:
            current = get_user_stsites(user_id)
            if url in current:
                skipped_dup.append(url)
            elif len(current) + len(to_test) >= STSITE_MAX:
                skipped_limit.append(url)
            else:
                to_test.append(url)

        # If nothing left to test in this batch (all dup/limit), skip the rest
        if skipped_limit:
            remaining_urls = [u for u in urls_to_test[batch_start + _SADD_BATCH:] if u not in skipped_dup]
            skipped_limit.extend(remaining_urls)
            processed += len(batch_raw)
            break

        if not to_test:
            processed += len(batch_raw)
            continue

        # Progress update
        await safe_edit(loading_msg,
            f"{pe(E['loading'])} {bold(f'Batch {batch_start // _SADD_BATCH + 1} — testing {len(to_test)} sites in parallel...')}\n\n"
            f"{pe(E['check'])} {bold(f'Added: {len(added_list)}')}"
            f"  {pe(E['cross'])} {bold(f'Failed: {len(failed_list)}')}"
            f"  {pe(E['hourglass'])} {bold(f'Done: {processed}/{total}')}"
        )

        # Run entire batch in parallel
        results = await asyncio.gather(*[_test_one_stsite(u) for u in to_test])
        processed += len(batch_raw)

        for url, ok, resp in results:
            if ok:
                add_user_stsite(user_id, url)
                added_list.append(url)
                try:
                    await bot.send_message(
                        auth.APPROVED_GROUP_ID,
                        f"{pe(E['check'])} {bold('ST Site Saved!')}\n"
                        f"{pe(R['checked_by'])} {bold('User:')} {user_link(user_id, message.from_user.full_name, message.from_user.username or '')}\n"
                        f"{pe(E['globe'])} {bold('Site:')} {bold(url)}\n"
                        f"{pe(R['gate'])} {bold('Response:')} {bold(resp)}",
                        disable_notification=True,
                    )
                except Exception:
                    pass
            else:
                failed_list.append(f"{url} — {resp[:55]}")

    # Final summary
    final_count = len(get_user_stsites(user_id))
    lines = [f"{pe(E['check'])} {bold(f'Done! Your sites: {final_count}/25')}\n"]

    if added_list:
        lines.append(f"{pe(E['check'])} {bold(f'Added ({len(added_list)}):')} "
                     + ", ".join(bold(s) for s in added_list))

    if failed_list:
        lines.append(f"{pe(E['cross'])} {bold(f'Failed ({len(failed_list)}):')} "
                     + "\n  ".join(bold(s) for s in failed_list))

    if skipped_dup:
        lines.append(f"{pe(E['warn'])} {bold(f'Already in list ({len(skipped_dup)}):')} "
                     + ", ".join(bold(s) for s in skipped_dup))

    if skipped_limit:
        lines.append(f"{pe(E['warn'])} {bold(f'Skipped — limit reached ({len(skipped_limit)}):')} "
                     + ", ".join(bold(s[:30]) for s in skipped_limit[:5])
                     + (f"... +{len(skipped_limit)-5}" if len(skipped_limit) > 5 else ""))

    if added_list:
        lines.append(f"\n{pe(E['bolt'])} {bold('Use /st /mst /stxt — random site picked each run')}")

    await safe_edit(loading_msg, "\n".join(lines))


# ── /srem — Remove saved site(s) ─────────────────────────────────────────────

@router.message(Command("srem"))
async def cmd_srem(message: types.Message):
    joined = await check_user_joined(message.from_user.id)
    if not joined:
        await message.reply(JOIN_MSG, reply_markup=join_keyboard())
        return

    user_id = message.from_user.id
    sites = get_user_stsites(user_id)
    if not sites:
        await message.reply(f"{pe(E['warn'])} {bold('No sites saved! Use /sadd to add one.')}")
        return

    args = message.text.split(maxsplit=1)
    arg = args[1].strip() if len(args) > 1 else ""

    if not arg:
        numbered = "\n".join(f"{pe(E['next'])} {bold(str(i+1)+'.')} {bold(s)}" for i, s in enumerate(sites))
        await message.reply(
            f"{pe(E['warn'])} {bold('Usage:')}\n\n"
            f"{pe(E['next'])} /srem {bold('1')} — {bold('remove site #1')}\n"
            f"{pe(E['next'])} /srem {bold('all')} — {bold('remove all sites')}\n\n"
            f"{pe(E['check'])} {bold(f'Your sites ({len(sites)}/25):')}\n{numbered}"
        )
        return

    if arg.lower() == "all":
        del_user_stsite(user_id)
        await message.reply(f"{pe(E['check'])} {bold('All ST sites removed!')}")
        return

    try:
        idx = int(arg)
    except ValueError:
        await message.reply(f"{pe(E['warn'])} {bold('Use a number: /srem 1')} or {bold('/srem all')}")
        return

    if idx < 1 or idx > len(sites):
        await message.reply(f"{pe(E['warn'])} {bold(f'Invalid number. You have {len(sites)} site(s).')}")
        return

    removed = sites[idx - 1]
    del_user_stsite(user_id, idx)
    await message.reply(
        f"{pe(E['check'])} {bold('Site removed!')}\n\n"
        f"{pe(E['globe'])} {bold(removed)}"
    )


