# ══════════════════════════════════════════════════════════════════════════════
#  MAIN ENTRY
# ══════════════════════════════════════════════════════════════════════════════

async def main():
    me = await bot.get_me()
    log.info(f"⚡ Bot @{me.username} is running...")
    log.info("═══════════════════════════════════════════════════════════════════════")
    log.info("🌐  BOTv75 — Square gate integrated")
    log.info("    NEW:  /sq  /sq2-10  /msq  (Square charger)")
    log.info("    /sq  = 1-20 cards, $1.00 default, /sq2-/sq10 for $2-$10 amounts")
    log.info("    /msq = bulk .txt, always $1.00/card, KEY:10-200 ADMIN:10-500 OWNER:10-10M")
    log.info("    AVS bypass: billing_postal_code omitted → AVS_NOT_CHECKED always")
    log.info("    Real Square processor responses with Response + Reason + Price + Time")
    log.info("    Files: sqcharge.py · sqapis.txt · sqsites.txt")
    log.info("═══════════════════════════════════════════════════════════════════════")

    # ═══════════════════════════════════════════════════════════════════════════
    #  v70 — DASHBOARD SERVER + AUTO-OPEN BROWSER + BROADCAST DISPATCHER
    # ═══════════════════════════════════════════════════════════════════════════
    _dash_port = 0
    try:
        if _dashboard_mod is not None:
            _dash_port = _dashboard_mod.start(host="0.0.0.0", port=8080)
            log.info("═══════════════════════════════════════════════════════════════════════")
            log.info("🌐  DASHBOARD ENABLED  (v70)")
            log.info("    URL:           http://localhost:%d/", _dash_port)
            log.info("    Local URL:     http://127.0.0.1:%d/", _dash_port)
            log.info("    Gates toggle:  /api/gates/toggle")
            log.info("    Broadcast:     /api/broadcast")
            try:
                _gates_file = os.path.abspath(gate_manager.GATES_FILE)
            except Exception:
                _gates_file = os.path.join(_v70_dir, "gates.json")
            try:
                _vbv_file = os.path.abspath(vbv_api.VBU_APIS_FILE)
            except Exception:
                _vbv_file = os.path.join(_v70_dir, "vbvapis.txt")
            log.info("    Gates file:    %s", _gates_file)
            log.info("    VBV APIs file: %s", _vbv_file)
            log.info("═══════════════════════════════════════════════════════════════════════")
            # Auto-open the dashboard in the user's default browser.
            # (Will silently fail on headless servers — see dashboard.open_in_browser.)
            try:
                _dashboard_mod.open_in_browser(_dash_port)
            except Exception as _ob:
                log.info("    (auto-open browser skipped: %s)", _ob)
        else:
            log.warning("dashboard module not loaded — dashboard disabled")
    except Exception as _de:
        log.error("dashboard startup failed: %s", _de, exc_info=True)

    # ── Broadcast dispatcher task ────────────────────────────────────────────
    # Polls the dashboard queue (filled by POST /api/broadcast) and sends
    # each pending broadcast to every user via `bot.send_message`.
    async def _broadcast_dispatcher():
        log.info("📡 broadcast dispatcher task running")
        while True:
            try:
                item = None
                if _dashboard_mod is not None:
                    item = _dashboard_mod.pop_pending_broadcast()
                if item is None:
                    await asyncio.sleep(1.0)
                    continue

                text = str(item.get("text", "")).strip()
                if not text:
                    continue

                # Get every known user ID.  Falls back to empty list if the
                # auth module doesn't expose get_all_user_ids (very old build).
                try:
                    all_ids = list(auth.get_all_user_ids())
                except Exception:
                    all_ids = []
                if not all_ids:
                    log.warning("[broadcast] no users found in users.txt — skipping")
                    _dashboard_mod.update_broadcast_status(sent=0, failed=0,
                                                            last_text=text,
                                                            last_error="no users")
                    continue

                sent = 0
                failed = 0
                sem = asyncio.Semaphore(25)  # 25 concurrent sends ≈ safe Telegram flood limit

                async def _send_one(uid: int) -> bool:
                    nonlocal sent, failed
                    async with sem:
                        try:
                            await bot.send_message(uid, text,
                                                    disable_web_page_preview=True)
                            sent += 1
                            return True
                        except Exception as e:
                            failed += 1
                            return False

                # Fan out in parallel; we don't retry here — the dashboard
                # status page will reflect sent vs failed.
                await asyncio.gather(*[_send_one(u) for u in all_ids],
                                       return_exceptions=True)
                _dashboard_mod.update_broadcast_status(
                    sent=sent, failed=failed,
                    last_text=text,
                    last_error="" if failed == 0 else f"{failed} users unreachable",
                )
                log.info("[broadcast] sent=%d failed=%d total=%d", sent, failed, len(all_ids))
            except asyncio.CancelledError:
                raise
            except Exception as _be:
                log.error("[broadcast] dispatcher error: %s", _be, exc_info=True)
                await asyncio.sleep(2.0)

    _bcast_task = asyncio.create_task(_broadcast_dispatcher())

    def _stop_bcast_task():
        try:
            _bcast_task.cancel()
        except Exception:
            pass

    # ── hit_sites.txt diagnostic banner ────────────────────────────────────────
    # This runs at EVERY startup. If you don't see this block in the bot logs,
    # you are NOT running the new bot.py — the old one is still loaded.
    try:
        _ok, _info = _hit_sites_selftest()
        abs_path = os.path.abspath(HIT_SITES_FILE)
        debug_path = os.path.abspath(HITS_DEBUG_FILE)
        if _ok:
            log.info("═══════════════════════════════════════════════════════════════════════")
            log.info("✅ HIT SITES LOGGING ENABLED")
            log.info("   hit_sites.txt path:    %s", abs_path)
            log.info("   hits_debug.txt path:   %s", debug_path)
            log.info("   selftest: OK (test line written)")
            log.info("   Commands available:")
            log.info("     /hitstest  — write a test line + show abs path")
            log.info("     /hits      — show last N lines of hit_sites.txt")
            log.info("     /hits debug — show raw dump of EVERY check from hits_debug.txt")
            log.info("     /mshdebug  — run one check and dump the full result dict")
            log.info("═══════════════════════════════════════════════════════════════════════")
        else:
            log.error("═══════════════════════════════════════════════════════════════════════")
            log.error("❌ HIT SITES LOGGING DISABLED — self-test FAILED")
            log.error("   hit_sites.txt path: %s", abs_path)
            log.error("   error: %s", _info)
            log.error("   Hits will NOT be logged until this is fixed.")
            log.error("═══════════════════════════════════════════════════════════════════════")
    except Exception as _bexc:
        log.error("hit_sites startup banner crashed: %s", _bexc, exc_info=True)

    # ── checked.txt diagnostic banner ────────────────────────────────────────
    try:
        checked_path = os.path.abspath(CHECKED_FILE)
        # Try to create the file if it doesn't exist
        if not os.path.isfile(checked_path):
            with open(checked_path, "w", encoding="utf-8") as f:
                f.write("")
        log.info("═══════════════════════════════════════════════════════════════════════")
        log.info("CHECKED.TXT LOGGING ENABLED")
        log.info("   checked.txt path:  %s", checked_path)
        log.info("   Logs: APPROVED + INSUFFICIENT cards with full details")
        log.info("   Format: [timestamp] STATUS | card | $price | brand | time | user | site | response")
        log.info("   Hit channel (@whophits): ONLY APPROVED (not insufficient)")
        log.info("═══════════════════════════════════════════════════════════════════════")
    except Exception as _cexc:
        log.error("checked.txt startup banner crashed: %s", _cexc, exc_info=True)

    # ── Shopify files auto-create + diagnostic banner ────────────────────
    try:
        _ensure_shopify_files()
        shopify_sites_path = os.path.abspath(SHOPIFY_SITES_FILE)
        shopify_apis_path = os.path.abspath(SHOPIFY_APIS_FILE)
        shopify_dec_path = os.path.abspath(SHOPIFY_DEC_APPROVED_FILE)
        shopify_logs_path = os.path.abspath(SHOPIFY_LOGS_FILE)
        _sites_count = len(_load_shopify_sites())
        _apis_count = len(_load_shopify_apis())
        log.info("═══════════════════════════════════════════════════════════════════════")
        log.info("✨ SHOPIFY CHECKER ENABLED")
        log.info("   /shopify  — 1-30 cards (free, proxy required)")
        log.info("   /mshopify — bulk upload (admin only, unlimited)")
        log.info("   shopify_sites.txt: %s  (%d sites loaded)",
                 shopify_sites_path, _sites_count)
        log.info("   shopify_apis.txt:  %s  (%d APIs loaded)",
                 shopify_apis_path, _apis_count)
        log.info("   dec&approved.txt:  %s  (auto-created on first write)",
                 shopify_dec_path)
        log.info("   shopify_logs.txt:  %s  (auto-created on first write)",
                 shopify_logs_path)
        log.info("   Retry policy: NO RETRIES (one request per card)")
        log.info("   Proxy retry: up to 3 different proxies on proxy/connection failures")
        log.info("   Per-API concurrency: max %d concurrent requests (global, all users)",
                 ShopifyAPIPool._MAX_PER_API)
        log.info("   Progress interval: every 30 cards")
        log.info("═══════════════════════════════════════════════════════════════════════")
    except Exception as _sexc:
        log.error("Shopify startup banner crashed: %s", _sexc, exc_info=True)

    # ── Check for interrupted Shopify bulk check ────────────────────────
    try:
        pending = _load_shopify_pending()
        if pending:
            saved_uid = pending.get("user_id")
            remaining = pending.get("remaining", [])
            saved_name = pending.get("user_name", "")
            saved_uname = pending.get("user_uname", "")
            log.info("═══════════════════════════════════════════════════════════════════════")
            log.info("⚠️  INTERRUPTED SHOPIFY BULK DETECTED")
            log.info("   User: %s (@%s, ID: %s)", saved_name, saved_uname, saved_uid)
            log.info("   Remaining cards: %d", len(remaining))
            log.info("   Tell the user to run /shopify_resume")
            log.info("═══════════════════════════════════════════════════════════════════════")
            # Notify the user via DM
            if saved_uid:
                try:
                    notify_text = (
                        f"{wpe('sparkle')} {_to_bi('Shopify Bulk Interrupted')} {wpe('sparkle')}\n"
                        f"{_SHOPIFY_SEP}\n"
                        f"{wpe('warn')} {_to_bi('The bot restarted during your bulk check.')}\n"
                        f"{wpe('triple_ring')} {_to_bi('Remaining cards:')} {_to_bi(str(len(remaining)))}\n\n"
                        f"{wpe('arrow_right')} {_to_bi('Run /shopify_resume to continue.')}"
                    )
                    await bot.send_message(saved_uid, notify_text)
                except Exception as _ne:
                    log.warning("Could not notify user about pending bulk: %s", _ne)
    except Exception as _pe:
        log.error("Pending bulk check failed: %s", _pe)

    # Log all registered handlers for debugging
    for obs in router.message.handlers:
        log.info(f"  📌 Registered handler: {obs.callback.__name__}")

    await bot.delete_webhook(drop_pending_updates=True)
    try:
        # drop_pending_updates=True + skip_updates=True: drop old queued
        # messages from downtime so the bot starts fresh. This prevents
        # a flood of old /shopify commands from stacking up and freezing
        # the event loop on restart.
        #
        # handle_as_tasks=True (DEFAULT): each update runs as its own
        # asyncio task. This means a long-running /mshopify bulk check
        # does NOT block other users' /start, /cmds, /addproxy, etc.
        # This is the fix for the "bot freezes until I press Enter" issue.
        #
        # allowed_updates whitelist prevents Telegram from sending exotic
        # update types (rich_message, etc.) that cause pydantic to hang.
        await dp.start_polling(
            bot,
            skip_updates=True,
            allowed_updates=[
                "message",
                "edited_message",
                "callback_query",
                "inline_query",
                "chat_member",
                "my_chat_member",
                "chat_join_request",
            ],
            handle_as_tasks=True,
            backoff_on_timeout=2,
        )
    finally:
        # v70 — stop broadcast dispatcher + dashboard server
        try:
            _stop_bcast_task()
        except Exception:
            pass
        try:
            if _dashboard_mod is not None:
                _dashboard_mod.stop()
        except Exception:
            pass
        CHECKER_POOL.shutdown(wait=False)
        try:
            await _whop_api_pool.close()
        except Exception:
            pass
        # v67 — close the dedicated single-lane engine too
        try:
            await _single_whop_pool.close()
        except Exception:
            pass
        # v76 — close the direct fallback layer (whopapidirect.py)
        try:
            import whopapidirect as _wad
            await _wad.close()
        except Exception:
            pass
        try:
            await _shopify_api_pool.close()
        except Exception:
            pass
        try:
            await _st_api_pool.close()
        except Exception:
            pass
        await close_session()
        await bot.session.close()


if __name__ == "__main__":
    # Raise OS file descriptor limit to prevent "too many open files" under load
    try:
        import resource
        soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
        target = min(65536, hard)
        if soft < target:
            resource.setrlimit(resource.RLIMIT_NOFILE, (target, hard))
            log.info(f"📂 Raised fd limit: {soft} → {target}")
    except Exception:
        pass  # Windows or restricted — handled by reduced thread count

    # ── AUTO-RESTART LOOP — runs 24/7, never stops ─────────────────────
    # If the bot crashes, disconnects, or hits a fatal error, it automatically
    # restarts after a 5-second delay. Only Ctrl+C (KeyboardInterrupt) stops it.
    _restart_count = 0
    while True:
        try:
            log.info("═══════════════════════════════════════════════════════════")
            log.info("🚀 Starting bot (attempt %d)...", _restart_count + 1)
            log.info("═══════════════════════════════════════════════════════════")
            asyncio.run(main())
            # If main() returns normally (shouldn't happen), wait and restart
            log.warning("Bot main() returned unexpectedly — restarting in 5s...")
            time.sleep(5)
        except KeyboardInterrupt:
            log.info("Bot stopped by user (Ctrl+C).")
            break
        except SystemExit:
            log.info("Bot stopped by system exit.")
            break
        except Exception as _fatal:
            _restart_count += 1
            log.error("═══════════════════════════════════════════════════════════")
            log.error("💥 BOT CRASHED (crash #%d): %s", _restart_count, _fatal,
                       exc_info=True)
            log.error("🔄 Auto-restarting in 5 seconds...")
            log.error("═══════════════════════════════════════════════════════════")
            try:
                time.sleep(5)
            except KeyboardInterrupt:
                log.info("Bot stopped by user during restart delay.")
                break
